# --- lobby control survey (once per version): which modules and tables drive notices, event ads, activity
# entrances, banners and seasonal panels, so the server can take them over.  Writes screen_code.json
# entries (dump_module_code) and logs/lobby_survey.json.
_DH_LOBBY_SURVEY_VERSION = 'm19'


def _dh_lobby_survey():
    if not _DH_DIAG:
        return None
    try:
        marker = _dh_os.path.join(_dh_os.path.dirname(client_tables_path()), 'lobby_survey.json.' + _DH_LOBBY_SURVEY_VERSION)
        if _dh_os.path.exists(marker):
            return 'done-before'
        words = ('notice', 'announce', 'activity', 'advert', 'banner', 'festival', 'season', 'carnival', 'holiday', 'promo', 'event', 'welfare', 'signin', 'sign_in', 'loading')
        out = {'modules': [n for n in sorted(_dh_sys.modules) if any(w in n.lower() for w in words)], 'tables': {}, 'ads': [], 'errors': []}
        try:
            try:
                import tables
            except ImportError:
                tables = __import__('ui.UIAdvertisementCenter', fromlist=['x']).tables
            names = [a for a in dir(tables) if any(w in a.lower() for w in words + ('limittime', 'limit_time', 'anniversary', 'blackfriday', 'valentine', 'xmas', 'christmas', 'monthcard', 'supply', 'jump', 'entrance', 'mainentrance'))]
            out['table_accessors'] = names[:200]
            for name in names[:60]:
                try:
                    table = getattr(tables, name)
                    if hasattr(table, 'keys'):
                        keys = list(table.keys())
                        sample = dict(table[keys[0]]) if keys else {}
                        out['tables'][name] = {'rows': len(keys), 'sample': dict((str(k), safe(v, 120)) for k, v in list(sample.items())[:40])}
                except Exception as error:
                    out['tables'][name] = 'error %r' % (error,)
        except Exception as error:
            out['errors'].append('tables: %r' % (error,))
        try:
            try:
                import tables
            except ImportError:
                tables = __import__('ui.UIAdvertisementCenter', fromlist=['x']).tables
            table = tables.Advertisement
            for key in sorted(table.keys())[:80]:
                row = dict(table[key])
                out['ads'].append(dict((str(k), safe(v, 160)) for k, v in row.items()))
        except Exception as error:
            out['errors'].append('ads: %r' % (error,))
        try:
            out['switches'] = {}
            for module_name in ('shared.switches', 'shared.switches_publish', 'switches'):
                module = _dh_sys.modules.get(module_name)
                if module is None:
                    try:
                        module = __import__(module_name, fromlist=['x'])
                    except Exception:
                        continue
                values = {}
                for attr in dir(module):
                    if attr.startswith('_'):
                        continue
                    value = getattr(module, attr)
                    if isinstance(value, (bool, int, float, str)) and not callable(value):
                        values[attr] = value
                out['switches'][module_name] = values
        except Exception as error:
            out['errors'].append('switches: %r' % (error,))
        try:
            for name in ('DtsActivity', 'DtsLimitActivity'):
                try:
                    table = getattr(tables, name)
                    out['rows_' + name] = [dict((str(k), safe(v, 160)) for k, v in dict(table[key]).items()) for key in sorted(table.keys())[:60]]
                except Exception as error:
                    out['errors'].append('%s rows: %r' % (name, error))
        except Exception as error:
            out['errors'].append('rows: %r' % (error,))
        try:
            import client_utils
            out['server_sys_time'] = client_utils.getServerSysTime()
            out['real_time'] = _dh_time.time()
            import Globals
            out['main_entrance_open'] = safe(getattr(Globals, 'MainEntranceOpenActivities', None), 400)
        except Exception as error:
            out['errors'].append('time: %r' % (error,))
        dumped = {}
        for module_name in ('ui.UIAdvertisementCenter', 'ui.UIAnnounce', 'ui.UIMainActivityRightTop', 'client_utils', 'ui.UINotice',
                            'ui.UIDtsActivity', 'ui.dtsActivity.activityMgr', 'activity_limit_time_common', 'festival_activity.festival_activity_utils',
                            'ui.UIMainFunctionEntrance', 'red_package_utils', 'shared.switches',
                            'ui.UIActivityCenter', 'ui.UIMain', 'ui.UILoading', 'NoticeMgr', 'ui.UIAnnouncement'):
            module = _dh_sys.modules.get(module_name)
            if module is None:
                try:
                    module = __import__(module_name, fromlist=['x'])
                except Exception:
                    continue
            try:
                _screen_code['dumped'][module_name] = dump_module_code(module)
                dumped[module_name] = len(_screen_code['dumped'][module_name])
            except Exception as error:
                out['errors'].append('%s: %r' % (module_name, error))
        if dumped:
            schedule_catalog_write('screen')
        out['dumped'] = dumped
        path = _dh_os.path.join(_dh_os.path.dirname(client_tables_path()), 'lobby_survey.json')
        with open(path + '.tmp', 'wb') as handle:
            handle.write(u''.join(_dh_json_chunks(out)).encode('ascii'))
        if _dh_os.path.exists(path):
            _dh_os.remove(path)
        _dh_os.rename(path + '.tmp', path)
        with open(marker, 'w') as handle:
            handle.write(_DH_LOBBY_SURVEY_VERSION)
        log('local-lobby-surveyed', modules=len(out['modules']), tables=len(out['tables']), ads=len(out['ads']), dumped=dumped, errors=out['errors'][:3])
        return 'written'
    except Exception:
        log_error('local-lobby-survey-error')
        return 'error'


try:
    call_later(6.0, _dh_lobby_survey)
except Exception:
    pass


# --- lobby control from the server: the prop rlLobby (console -> Lobby tab) arrives with the other server
# props at lobby entry.  It sets the date the seasonal/supply code believes, filters the event pages
# (Advertisement table) that pop up, and hides lobby entrances by widget name.
_dh_lobby = globals().get('_dh_lobby') or {'config': None, 'applied': None}


def _dh_lobby_config():
    return _dh_lobby.get('config') or {}


# m108: one control for every lobby promo (console Seasons -> Lobby promos): rlLobby.promos
# {"<Table>.<row>": {"show": "always" | "never" | "seasons", "seasons": ["halloween", ..., "offseason"]}}.
# "seasons" shows the row only while one of those seasons is on (offseason = no season), using the same season the
# lobby theme follows (_dh_season_now, m107).  Folded into the event overrides (MainEntrance / EventButtons /
# DtsActivity / DtsLimitActivity: mode on / off) and the entry-popup allow / deny lists (Advertisement).
_DH_PROMO_TABLES = ('Advertisement', 'MainEntrance', 'EventButtons', 'DtsActivity', 'DtsLimitActivity')


def _dh_promo_merge(config):
    """(events, ads, season) with the lobby promos applied for today; the config itself is left unchanged."""
    config = config if isinstance(config, dict) else {}
    events = dict((str(t), dict(r)) for t, r in (config.get('events') or {}).items() if isinstance(r, dict))
    ads = dict(config.get('ads') or {})
    promos = config.get('promos')
    season_now = globals().get('_dh_season_now')
    if not isinstance(promos, dict) or not promos or season_now is None:
        return events, ads, None
    try:
        season = season_now(config)[0] or 'offseason'
    except Exception:
        log_error('local-promo-season-error')
        return events, ads, None
    allow = [int(x) for x in (ads.get('allow') or []) if str(x).lstrip('-').isdigit()]
    deny = [int(x) for x in (ads.get('deny') or []) if str(x).lstrip('-').isdigit()]
    shown_ads = []
    for key, rule in promos.items():
        if not isinstance(rule, dict):
            continue
        show = str(rule.get('show') or 'default')
        if show == 'always':
            on = True
        elif show == 'never':
            on = False
        elif show == 'seasons':
            on = season in [str(x) for x in (rule.get('seasons') or [])]
        else:
            continue
        table, _sep, row = str(key).partition('.')
        if table not in _DH_PROMO_TABLES or not row:
            continue
        if table == 'Advertisement':
            if not row.isdigit():
                continue
            ad = int(row)
            if on:
                shown_ads.append(ad)
                deny = [x for x in deny if x != ad]
                if ad not in allow:
                    allow.append(ad)
            else:
                allow = [x for x in allow if x != ad]
                if ad not in deny:
                    deny.append(ad)
            continue
        rows = events.setdefault(table, {})
        entry = dict(rows.get(row) or {})
        if on:
            if str(entry.get('mode') or 'stock') not in ('on', 'yearly'):
                entry['mode'] = 'on'
        else:
            entry['mode'] = 'off'
        rows[row] = entry
    ads['allow'], ads['deny'] = allow, deny
    if str(ads.get('mode') or 'all') == 'none' and shown_ads:
        ads['mode'] = 'list'                      # a popup the promos show beats "no popups"
    return events, ads, season


def _dh_apply_lobby(player, config):
    if not isinstance(config, dict):
        return
    _dh_lobby['config'] = config
    try:
        date = str(config.get('service_date') or '')
        if date and date != globals().get('_DH_SERVICE_DATE'):
            _dh_time.strptime(date, '%Y.%m.%d %H:%M:%S')
            globals()['_DH_SERVICE_DATE'] = date
            shifted = _dh_shift_service_clock()
            log('local-lobby-service-date', date=date, modules=shifted)
    except Exception:
        log_error('local-lobby-service-date-error')
    try:
        changed = _dh_set_switches(config.get('switches') or {})
        if changed:
            log('local-lobby-switches', changed=changed)
    except Exception:
        log_error('local-lobby-switches-error')
    try:
        date = str(config.get('client_date') or '')
        if date:
            log('local-lobby-client-date', **_dh_set_client_date(date))
    except Exception:
        log_error('local-lobby-client-date-error')
    try:
        names = [str(n) for n in (config.get('hide_entrances') or [])]
        if names:
            log('local-lobby-entrances-hidden', hidden=_dh_hide_widgets(names))
    except Exception:
        log_error('local-lobby-hide-error')
    try:
        log('local-top-tabs', unblocked=_dh_unblock_top_tabs(player))
    except Exception:
        log_error('local-top-tabs-error')
    try:
        state = _dh_fix_monthly_benefit(player)
        if state:
            log('local-monthly-benefit', state=state)
    except Exception:
        log_error('local-monthly-benefit-error')
    try:
        fixed = _dh_fix_pack_dates()
        if fixed:
            log('local-pack-dates', fixed=fixed)
    except Exception:
        log_error('local-pack-dates-error')
    try:
        events = _dh_promo_merge(config)[0]          # m108: the console's lobby promos for today's season
        if isinstance(events, dict):
            log('local-lobby-events', changed=_dh_apply_events(events))
    except Exception:
        log_error('local-lobby-events-error')
    try:
        _dh_apply_limited_modes(player, config.get('limited_modes'))
    except Exception:
        log_error('local-lobby-limited-modes-error')
    try:
        _dh_cache_lobby(config)
    except Exception:
        pass
    _dh_lobby['applied'] = config.get('version')


def _dh_set_switches(values):
    """Flip the client's feature switches (shared.switches and its published twin) - the gates every lobby
    entrance checks (EnableHorseRacing, EnableNewMonthcard, EnableBlackFriday2019, EnableValentine2021...)."""
    changed = {}
    if not isinstance(values, dict):
        return changed
    modules = []
    for module_name in ('shared.switches', 'shared.switches_publish', 'switches'):
        module = _dh_sys.modules.get(module_name)
        if module is None:
            try:
                module = __import__(module_name, fromlist=['x'])
            except Exception:
                continue
        modules.append(module)
    for name, value in values.items():
        name = str(name)
        if not name or name.startswith('_'):
            continue
        for module in modules:
            try:
                old = getattr(module, name, None)
                if isinstance(old, bool) or old is None:
                    value = bool(value)
                elif isinstance(old, int):
                    value = int(value)
                if old != value:
                    setattr(module, name, value)
                    changed[name] = value
            except Exception:
                continue
    return changed


def _dh_set_client_date(date):
    """Make client_utils.getServerSysTime() (the clock every dated event checks) read ``date`` now."""
    import client_utils
    import Globals
    target = _dh_time.mktime(_dh_time.strptime(date, '%Y.%m.%d %H:%M:%S'))
    current = client_utils.getServerSysTime()
    origin = getattr(Globals, 'SERVER_SYS_TIME_ORIGIN', None)
    if origin is None:
        return {'date': date, 'applied': False, 'reason': 'no SERVER_SYS_TIME_ORIGIN'}
    Globals.SERVER_SYS_TIME_ORIGIN = float(origin) + (target - current)
    return {'date': date, 'applied': True, 'now_reads': _dh_time.strftime('%Y.%m.%d %H:%M:%S', _dh_time.localtime(client_utils.getServerSysTime()))}


def _dh_lobby_cache_path():
    return _dh_os.path.join(_dh_os.path.dirname(client_tables_path()), 'lobby_control.json')


def _dh_cache_lobby(config):
    """Keep the last pushed control locally so the switches apply at the next game start before any
    lobby UI is built (the prop only arrives once the lobby loads)."""
    with open(_dh_lobby_cache_path() + '.tmp', 'wb') as handle:
        handle.write(u''.join(_dh_json_chunks(config)).encode('ascii'))
    path = _dh_lobby_cache_path()
    if _dh_os.path.exists(path):
        _dh_os.remove(path)
    _dh_os.rename(path + '.tmp', path)


def _dh_load_cached_lobby():
    try:
        import json as _json
        with open(_dh_lobby_cache_path(), 'rb') as handle:
            return _json.loads(handle.read().decode('ascii'))
    except Exception:
        return None


def _dh_hide_widgets(names, root=None):
    """Hide the lobby widgets/buttons named here (searched through UIMain and its children)."""
    hidden = []
    try:
        import Globals
        main_ui = getattr(Globals.uiMgr, 'UIMain', None) if root is None else root
    except Exception:
        return hidden
    if main_ui is None:
        return hidden
    wanted = set(names)
    seen = set()

    def walk(value, depth=0):
        if depth > 6 or value is None or id(value) in seen:
            return
        seen.add(id(value))
        for attr in dir(value):
            if attr.startswith('_'):
                continue
            if attr in wanted:
                try:
                    child = getattr(value, attr)
                    if hasattr(child, 'setVisible'):
                        child.setVisible(False)
                        hidden.append(attr)
                        continue
                except Exception:
                    pass
            if depth < 2 and attr in ('widget', 'panel', 'root', 'node', 'ui', 'main', 'layout'):
                try:
                    walk(getattr(value, attr), depth + 1)
                except Exception:
                    pass
        name_getter = getattr(value, 'getChildByName', None)
        if callable(name_getter):
            for name in wanted:
                try:
                    child = name_getter(name)
                    if child is not None and hasattr(child, 'setVisible'):
                        child.setVisible(False)
                        hidden.append(name)
                except Exception:
                    pass
    walk(main_ui)
    return sorted(set(hidden))


_dh_original_apply_server_props = _dh_lobby_inner(globals().get('apply_server_props'))


