_dh_original_event_ads = _dh_lobby_inner(globals().get('event_ads'))


def _dh_event_ads_wrapper(rows, loads=None):
    config = _dh_promo_merge(_dh_lobby_config())[1]     # m108: lobby promos fold into the popup allow / deny lists
    mode = str(config.get('mode') or 'all')
    allow = set(int(x) for x in (config.get('allow') or []) if str(x).lstrip('-').isdigit())
    deny = set(int(x) for x in (config.get('deny') or []) if str(x).lstrip('-').isdigit())
    kept = []
    for index, row in enumerate(rows or []):
        try:
            row_id = int(row.get('id', row.get('ID', index + 1)))
        except Exception:
            row_id = index + 1
        if mode == 'none' or row_id in deny or (mode == 'list' and row_id not in allow):
            continue
        kept.append(row)
    if config.get('once_per_day', True) and _dh_lobby.get('shown_day') == _dh_time.strftime('%Y-%m-%d') and _dh_lobby.get('shown_once'):
        kept = []
    if kept:
        _dh_lobby['shown_day'] = _dh_time.strftime('%Y-%m-%d')
        _dh_lobby['shown_once'] = True
    if mode != 'all' or deny or not kept:
        log('local-lobby-ads-filtered', mode=mode, kept=len(kept), of=len(rows or []))
    return _dh_original_event_ads(kept) if loads is None else _dh_original_event_ads(kept, loads)


