def _dh_install_mmt_guard():
    try:
        module = _dh_sys.modules.get('ui.main.UIModes')
        if module is None:
            module = __import__('ui.main.UIModes', fromlist=['x'])
        cls = getattr(module, 'UIModes', None)
        current = cls.__dict__.get('doGoEvent') if cls is not None else None
        if current is None:
            return False
        inner = current
        while hasattr(inner, '_dh_inner'):
            inner = inner._dh_inner
        _dh_do_go_event_wrapper._dh_inner = inner
        cls.doGoEvent = _dh_do_go_event_wrapper
        return True
    except Exception:
        log_error('local-mmt-guard-error')
        return False


log('local-mmt-guard-installed', installed=_dh_install_mmt_guard())



# --- m38: overlay test.  The engine reads loose files from <game>/Documents/res (its own patch folder).  Put
# the ROS Redemption truck there under the engine's own name (ui/images/loading/bg_loading_01.png + an opaque
# .alpha.png): if that folder wins over the archive, the startup and loading screens show it from the first
# frame, before any hook code runs.  Written once (same bytes are not rewritten); removing the two files undoes it.
_DH_OVERLAYS = {
    'ui/images/loading/bg_loading_01.png': 'ov_bg_loading_01.png',
    'ui/images/loading/bg_loading_01.alpha.png': 'ov_bg_loading_01.alpha.png',
}


def _dh_write_overlays():
    return None
    if not _DH_DIAG:
        return None
    import base64 as _b64
    written = []
    try:
        assets = globals().get('_DH_BRAND_ASSETS') or {}
        base = _dh_os.path.join(_dh_game_root(), 'Documents', 'res')
        for name, asset in _DH_OVERLAYS.items():
            data = assets.get(asset)
            if not data:
                continue
            raw = _b64.b64decode(data)
            target = _dh_os.path.join(base, *name.split('/'))
            folder = _dh_os.path.dirname(target)
            if not _dh_os.path.isdir(folder):
                _dh_os.makedirs(folder)
            if _dh_os.path.exists(target) and _dh_os.path.getsize(target) == len(raw):
                continue
            with open(target + '.tmp', 'wb') as handle:
                handle.write(raw)
            if _dh_os.path.exists(target):
                _dh_os.remove(target)
            _dh_os.rename(target + '.tmp', target)
            written.append(name)
        log('local-overlay-written', written=written, total=len(_DH_OVERLAYS))
    except Exception:
        log_error('local-overlay-error')





# --- m40: how the engine's own patcher installs a patched file (so a file in Documents/res is used in place
# of the archive's copy): dump every loaded module with 'patch' in its name, plus any function anywhere that
# calls C_file.save_res_file / find_res_file / get_res_file / validate_res_file or names 'hash_list'.
# logs/patcher_dump.json.  Read-only.
def _dh_patcher_dump():
    if not _DH_DIAG:
        return None
    out = {'modules': {}, 'users': {}, 'errors': []}
    try:
        import types as _types
        wanted = set(['save_res_file', 'find_res_file', 'get_res_file', 'validate_res_file', 'invalidate_res_file',
                      'remove_res_file', 'remove_res_dir', 'validate_res_dir', 'hash_list'])
        for mod_name, module in list(_dh_sys.modules.items()):
            if module is None or mod_name == 'ros_local_lobby':
                continue
            if 'patch' in mod_name.lower():
                try:
                    out['modules'][mod_name] = dump_module_code(module)
                except Exception as error:
                    out['errors'].append('%s %r' % (mod_name, error))
            try:
                members = list(vars(module).items())
            except Exception:
                continue
            for name, value in members:
                funcs = []
                if isinstance(value, _types.FunctionType):
                    funcs.append((name, value))
                elif isinstance(value, type) or type(value).__name__ == 'classobj':
                    try:
                        for attr, fn in list(value.__dict__.items()):
                            fn = getattr(fn, '__func__', fn)
                            if isinstance(fn, _types.FunctionType):
                                funcs.append(('%s.%s' % (name, attr), fn))
                    except Exception:
                        pass
                for label, fn in funcs:
                    try:
                        if getattr(fn, '__module__', mod_name) != mod_name:
                            continue
                        code = fn.func_code
                        hit = (set(code.co_names) | set(c for c in code.co_consts if isinstance(c, str))) & wanted
                        if hit:
                            out['users']['%s:%s' % (mod_name, label)] = _code_entry(fn)
                    except Exception:
                        pass
    except Exception as error:
        out['errors'].append(repr(error))
    try:
        path = _dh_os.path.join(_dh_logs_dir(), 'patcher_dump.json')
        with open(path, 'wb') as handle:
            handle.write(u''.join(_dh_json_chunks(out)).encode('ascii'))
    except Exception:
        pass
    log('local-patcher-dump', modules=sorted(out['modules'])[:30], users=sorted(out['users'])[:30], errors=out['errors'][:3])





# --- m41 (a) the PLAY screen is UILoginLoop; its widgets hang off ui.panel (walk_ui_nodes found none).  Walk
# that tree with getChildren, log every image (file name + size) once, rewrite texts, and swap the ROS REDEMPTION
# logo and the "Scan to Download" QR by file name.  (b) read-only: the engine's own archive writer
# (package.npkrawwriter, used by its patcher) - dir() and docstrings - logs/npk_api.json.
def _dh_cc_walk(root, limit=1500):
    out = []
    pending = [('', root)]
    seen = set()
    while pending and len(out) < limit:
        path, node = pending.pop()
        if node is None or id(node) in seen:
            continue
        seen.add(id(node))
        out.append((path, node))
        try:
            for child in list(node.getChildren()):
                try:
                    name = child.getName()
                except Exception:
                    name = '?'
                pending.append(((path + '/' if path else '') + str(name), child))
        except Exception:
            pass
    return out


def _dh_login_pass(step):
    try:
        import Globals
        ui = _ui_open(Globals.uiMgr, 'UILoginLoop')
        if ui is None:
            return
        root = getattr(ui, 'panel', None) or getattr(ui, 'widget', None)
        if root is None:
            return
        nodes = _dh_cc_walk(root)
        images, changed, swapped = [], [], []
        for path, node in nodes:
            try:
                text = _node_text(node)
                if text and any(k in _dh_lower(text) for k in _DH_SCREEN_KEYS):
                    new = _dh_screen_text(text)
                    setter = _node_setter(node)
                    if setter is not None and new != text:
                        setter(new)
                        changed.append((path, safe(new, 60)))
            except Exception:
                pass
            # ROS Redemption: hide nodes by name
            try:
                _leaf2 = path.split('/')[-1].lower()
                _HIDE2 = ('swing', 'layer_swing', 'panel_di', 'panel_che', 'erweima',
                          'qrcode', 'facebook', 'icon_facebook', 'bg_login_word')
                if any(_k in _leaf2 for _k in _HIDE2):
                    try:
                        if hasattr(node, 'stopAllActions'): node.stopAllActions()
                        node.setVisible(False)
                        node.setPosition(-99999, -99999)
                        if hasattr(node, 'setOpacity'): node.setOpacity(0)
                        swapped.append((path, 'hidden-by-name'))
                    except Exception:
                        pass
                    continue
            except Exception:
                pass
            filename = None
            for getter in ('getTextureFilename', 'getRenderFile'):
                fn = getattr(node, getter, None)
                if callable(fn):
                    try:
                        filename = str(fn())
                        break
                    except Exception:
                        pass
            if not filename:
                continue
            texture, size, gl = _dh_tex(node)
            images.append((path, filename[:120], size))
            low = filename.lower()
            target = None
            if 'login_logo' in low:
                target = _dh_logo_now()
            elif ('qrcode' in low or 'erweima' in low) and 'tab_' not in low and 'btn' not in low:
                target = 'dh_qr.png'
            if target is None or 'dh_brand/' in low:
                continue
            widget = node if callable(getattr(node, 'loadTexture', None)) else _dh_typed_widget(ui, path)
            file_path = _dh_art_file(target)
            if widget is not None and file_path:
                try:
                    swap = _dh_swap_logo if target in _DH_LOGOS else _dh_swap
                    if swap(('UILoginLoop', id(ui), path), widget, file_path):
                        swapped.append((path, target))
                except Exception:
                    log_error('local-login-swap-error')
        if not _dh_screens.get('login_logged'):
            _dh_screens['login_logged'] = True
            log('local-login-widgets', nodes=len(nodes), images=images[:60])
        if changed or swapped:
            log('local-login-rebranded', step=step, changed=changed[:8], swapped=swapped)
    except Exception:
        log_error('local-login-pass-error')


def _dh_login_watch(token):
    if _dh_screens.get('login_token') is not token:
        return
    try:
        import Globals
        ui = _ui_open(Globals.uiMgr, 'UILoginLoop')
        now = id(ui) if ui is not None else None
        if now is not None and _dh_screens.get('login_open') != now:
            _dh_screens['login_open'] = now
            for step, delay in enumerate((0.0, 0.5, 1.5, 3.0)):
                call_later(delay, _dh_login_pass, step)
        elif now is None:
            _dh_screens['login_open'] = None
    except Exception:
        pass
    call_later(0.4, _dh_login_watch, token)


_dh_screens['login_token'] = object()
call_later(0.4, _dh_login_watch, _dh_screens['login_token'])


def _dh_npk_api():
    if not _DH_DIAG:
        return None
    out = {}
    try:
        import package
        out['package'] = [a for a in dir(package) if not a.startswith('__')]
        for name in out['package']:
            obj = getattr(package, name, None)
            entry = {'type': type(obj).__name__, 'doc': safe(getattr(obj, '__doc__', None), 600)}
            try:
                entry['dir'] = [a for a in dir(obj) if not a.startswith('__')][:80]
                entry['docs'] = dict((a, safe(getattr(getattr(obj, a), '__doc__', None), 300)) for a in entry['dir'][:40])
            except Exception:
                pass
            out[name] = entry
    except Exception as error:
        out['error'] = repr(error)
    try:
        path = _dh_os.path.join(_dh_logs_dir(), 'npk_api.json')
        with open(path, 'wb') as handle:
            handle.write(u''.join(_dh_json_chunks(out)).encode('ascii'))
    except Exception:
        pass
    log('local-npk-api', names=out.get('package'), error=out.get('error'))





# --- m42 (read-only): what the engine's own archive reader says about the branded files: find_file (entry id),
# raw size + md5 of get_raw_file, size + md5 of get_file, and get_raw_file_hash(id).  Ties names to archive
# entries (offline index) and shows the per-entry checksum.  logs/npk_probe.json.  Runs in a worker thread.
_DH_NPK_NAMES = (
    'ui/images/loading/bg_loading_01.png', 'ui/images/loading/bg_loading_01.alpha.png',
    'ui/images/loading/bg_loading_08.png', 'ui/images/loading/bg_loading_08.alpha.png',
    'ui/out_game/ui_login/loginpanel/login.png', 'ui/out_game/ui_login/loginpanel/login.alpha.png',
    'ui/_international/en/ui/out_game/ui_login/ui_login_en.png', 'ui/_international/en/ui/out_game/ui_login/ui_login_en.alpha.png',
    'ui/_international/en/ui/out_game/ui_login/ui_login_en.plist', 'ui/out_game/ui_patch/ui_patch.png',
)


def _dh_npk_probe():
    if not _DH_DIAG:
        return None
    out = {'files': {}, 'errors': []}
    try:
        import package
        import hashlib as _hl
        base = _dh_os.path.join(_dh_game_root(), 'res', 'ui')
        pk = package.npkpackage(base)
        for name in _DH_NPK_NAMES:
            row = {}
            try:
                fid = pk.find_file(name)
                row['find'] = safe(fid, 80)
            except Exception as error:
                row['find'] = 'error %r' % (error,)
                fid = None
            try:
                raw = pk.get_raw_file(name)
                row['raw'] = [len(raw), _hl.md5(raw).hexdigest(), _dh_binascii_crc(raw)]
            except Exception as error:
                row['raw'] = 'error %r' % (error,)
            try:
                data = pk.get_file(name)
                if isinstance(data, tuple):
                    data = data[-1]
                row['data'] = [len(data), _hl.md5(data).hexdigest(), _dh_binascii_crc(data), safe(data[:8], 40)]
            except Exception as error:
                row['data'] = 'error %r' % (error,)
            if fid is not None and not isinstance(fid, bool):
                try:
                    row['raw_hash'] = safe(pk.get_raw_file_hash(fid), 80)
                except Exception as error:
                    row['raw_hash'] = 'error %r' % (error,)
            out['files'][name] = row
        try:
            pk.close()
        except Exception:
            pass
    except Exception as error:
        out['errors'].append(repr(error))
    try:
        path = _dh_os.path.join(_dh_logs_dir(), 'npk_probe.json')
        with open(path, 'wb') as handle:
            handle.write(u''.join(_dh_json_chunks(out)).encode('ascii'))
    except Exception:
        pass
    log('local-npk-probe', files=len(out['files']), errors=out['errors'][:3])


def _dh_binascii_crc(data):
    import binascii as _ba
    return '%08x' % (_ba.crc32(data) & 0xffffffff)


def _dh_npk_probe_thread():
    if not _DH_DIAG:
        return None
    import threading as _th
    worker = _th.Thread(target=_dh_npk_probe)
    worker.daemon = True
    worker.start()





# --- m43: the PLAY screen (logo "ROS REDEMPTION", "Scan to Download" QR) is not a uiMgr screen: it lives straight
# in the running cocos scene.  Until the lobby opens, walk the running scene every 1.5 s, log its images once,
