def _dh_scene_brand_pass():
    cc = _dh_cc()
    if cc is None:
        return
    scene = cc.Director.getInstance().getRunningScene()
    if scene is None:
        return

    # In lobby or in battle: remove wallpaper so 3D lobby, room, and character are clean
    if _dh_in_lobby() or _dh_in_battle():
        try:
            bg = scene.getChildByName('ros_redemption_bg')
            if bg is not None:
                bg.removeFromParent()
        except Exception:
            pass
        return

    # Strictly on Login / Play screen:
    # 1. Attach ROS Redemption HD Wallpaper (with the epic 3D winged logo) BEHIND UI (-999)
    try:
        bg_path = 'dh_brand/dh_bg1.jpg'
        win = cc.Director.getInstance().getWinSize()
        bg = scene.getChildByName('ros_redemption_bg')
        if bg is None:
            bg = cc.Sprite.create(bg_path)
            if bg is not None:
                bg.setName('ros_redemption_bg')
                bg.setPosition(win.width / 2.0, win.height / 2.0)
                sz = bg.getContentSize()
                if sz.width > 0 and sz.height > 0:
                    bg.setScaleX(float(win.width) / float(sz.width))
                    bg.setScaleY(float(win.height) / float(sz.height))
                scene.addChild(bg, -999)
        else:
            try:
                bg.setLocalZOrder(-999)
            except Exception:
                pass
    except Exception:
        pass

    # --- ROS Redemption: hide street squad, QR code, Facebook, animated layers by node name
    _ALWAYS_HIDE = ('swing', 'layer_swing', 'panel_di', 'panel_che',
                    'erweima', 'qrcode', 'facebook', 'icon_facebook',
                    'bg_login_word', 'vng_logo', 'scan_to_download')
    try:
        for _p, _n in _dh_cc_walk(scene, limit=4000):
            try:
                _leaf = _p.split('/')[-1].lower()
                if any(_k in _leaf for _k in _ALWAYS_HIDE):
                    try:
                        if hasattr(_n, 'stopAllActions'): _n.stopAllActions()
                        _n.setVisible(False)
                        _n.setPosition(-99999, -99999)
                        if hasattr(_n, 'setOpacity'): _n.setOpacity(0)
                    except Exception:
                        pass
            except Exception:
                pass
    except Exception:
        pass
    nodes = _dh_cc_walk(scene, limit=4000)
    images, swapped, changed = [], [], []
    for path, node in nodes:
        try:
            text = _node_text(node)
            if text and any(k in _dh_lower(text) for k in _DH_SCREEN_KEYS):
                new = _dh_screen_text(text)
                setter = _node_setter(node)
                if setter is not None and new != text:
                    setter(new)
                    changed.append((path[-60:], safe(new, 60)))
        except Exception:
            pass
        filename = None
        fn = getattr(node, 'getTextureFilename', None)
        if callable(fn):
            try:
                filename = str(fn())
            except Exception:
                filename = None
        if not filename:
            continue
        low = filename.lower()
        images.append((path[-80:], filename[:100], None))   # m58: no getTexture() probing on arbitrary widgets
        if 'dh_brand/' in low and not (_dh_is_logo_file(low) and not low.endswith(_dh_logo_now())):
            continue        # ours already (a rotating logo whose turn is over is swapped again, m112)
        target = None
        leaf = path.split('/')[-1].lower()
        if 'zjzc_wz' in low:
            # m55: the separate "LEGACY" title sprite under the logo; our logo carries its own lines
            try:
                if node.isVisible():
                    node.setVisible(False)
                    swapped.append((path[-60:], filename[:60], 'hidden'))
            except Exception:
                pass
            continue
        if 'login_logo' in low or 'txt_logo_zjzc' in low or 'zjzc' in low or _dh_is_logo_file(low):
            try:
                if hasattr(node, 'stopAllActions'): node.stopAllActions()
                node.setVisible(False)
                node.setPosition(-99999, -99999)
                if hasattr(node, 'setOpacity'): node.setOpacity(0)
            except Exception:
                pass
            target = 'dh_logo_1.png'
        elif 'qrcode' in low and 'tab_' not in low and 'btn' not in low:
            target = 'dh_qr.png'
        if target is None:
            continue
        file_path = _dh_art_file(target)
        loader = getattr(node, 'loadTexture', None) or getattr(node, 'setTexture', None)
        if file_path and callable(loader):
            try:
                swap = _dh_swap_logo if target in _DH_LOGOS else _dh_swap
                # m112: a logo is swapped again on every turn, and id(scene) is a fresh wrapper per pass - key the
                # remembered original box by the widget path, or each turn fits into the previous (smaller) logo
                key = ('scene-logo', path) if target in _DH_LOGOS else ('scene', id(scene), path)
                if swap(key, node, file_path):
                    swapped.append((path[-60:], filename[:60], target))
            except Exception:
                log_error('local-scene-swap-error')
    key = id(scene)
    if _dh_screens.get('scene_logged') != key:
        _dh_screens['scene_logged'] = key
        log('local-scene-images', nodes=len(nodes), images=images[:80])
    if swapped or changed:
        log('local-scene-rebranded', swapped=swapped, changed=changed[:8])


def _dh_in_battle():
    try:
        import BigWorld
        return 'BattleGround' in type(BigWorld.player()).__name__
    except Exception:
        return False


_DH_SCENE_PASSES = 400          # ~10 minutes of login screens at most


def _dh_scene_watch(token, passes=0):
    if _dh_screens.get('scene_token') is not token:
        return
    # m89: the watch is for the login screens only.  A hot-lobby reload during a match started it again and,
    # never reaching the lobby, it walked 4000 widgets every 1.5 s for the rest of the match (lag).
    if _dh_in_lobby() or _dh_in_battle() or passes >= _DH_SCENE_PASSES:
        log('local-scene-watch-done', passes=passes)
        return
    try:
        _dh_scene_brand_pass()
    except Exception:
        log_error('local-scene-pass-error')
    call_later(1.5, _dh_scene_watch, token, passes + 1)


_dh_screens['scene_token'] = object()
call_later(0.5, _dh_scene_watch, _dh_screens['scene_token'])



# --- m44 (read-only): the code that fetches and parses notice_pc_hw.txt (the PLAY screen's "system
# announcement"), so the server can answer it in the right format.  logs/notice_code.json.
def _dh_notice_code():
    if not _DH_DIAG:
        return None
    out = {'users': {}, 'errors': []}
    try:
        import types as _types
        for mod_name, module in list(_dh_sys.modules.items()):
            if module is None or mod_name == 'ros_local_lobby':
                continue
            try:
                members = list(vars(module).items())
            except Exception:
                continue
            for name, value in members:
                funcs = []
                if isinstance(value, _types.FunctionType):
                    funcs.append((name, value))
                elif isinstance(value, type) or type(value).__name__ == 'classobj':
                    try:
                        for attr, fn in list(value.__dict__.items()):
                            fn = getattr(fn, '__func__', fn)
                            if isinstance(fn, _types.FunctionType):
                                funcs.append(('%s.%s' % (name, attr), fn))
                    except Exception:
                        pass
                for label, fn in funcs:
                    try:
                        if getattr(fn, '__module__', mod_name) != mod_name:
                            continue
                        consts = [c for c in fn.func_code.co_consts if isinstance(c, str)]
                        names = fn.func_code.co_names
                        if any('notice' in c.lower() for c in consts) or any('notice' in n.lower() for n in names):
                            out['users']['%s:%s' % (mod_name, label)] = _code_entry(fn)
                    except Exception:
                        pass
    except Exception as error:
        out['errors'].append(repr(error))
    try:
        path = _dh_os.path.join(_dh_logs_dir(), 'notice_code.json')
        with open(path, 'wb') as handle:
            handle.write(u''.join(_dh_json_chunks(out)).encode('ascii'))
    except Exception:
        pass
    log('local-notice-code', users=sorted(out['users'])[:40], errors=out['errors'][:3])






# --- m46 (test, read-only for the real game files): does the engine's archive reader accept an entry whose
# checksum fields were NOT recomputed?  A 413 KB test archive (res/dh_test.npk: the two truck entries, our
# ROS Redemption truck as data, the original checksum fields) is written, read back with package.npkpackage, compared
# with our bytes, then deleted.  Control: the real res/ui.npk opened the same way.  Also records the patcher's
# check switches (patch.config).  logs/npk_test.json.
_DH_TRUCK_MD5 = '6ea6e626138f39039ef882b1c0db1cab'


def _dh_npk_test():
    if not _DH_DIAG:
        return None
    out = {'errors': []}
    test_path = _dh_os.path.join(_dh_game_root(), 'res', 'dh_test.npk')
    try:
        import base64 as _b64
        import hashlib as _hl
        import package
        with open(test_path, 'wb') as handle:
            handle.write(_b64.b64decode(_DH_TEST_NPK))
        name = 'ui/images/loading/bg_loading_01.png'
        for label, base in (('real_rel', 'res/ui'), ('real_abs', _dh_os.path.join(_dh_game_root(), 'res', 'ui')),
                            ('test_rel', 'res/dh_test'), ('test_abs', _dh_os.path.join(_dh_game_root(), 'res', 'dh_test'))):
            row = {}
            try:
                pk = package.npkpackage(base)
                row['find'] = safe(pk.find_file(name), 60)
                data = pk.get_file(name)
                if isinstance(data, tuple):
                    row['tuple'] = len(data)
                    data = data[-1]
                row['data'] = [len(data), _hl.md5(data).hexdigest(), _hl.md5(data).hexdigest() == _DH_TRUCK_MD5] if data else None
                try:
                    pk.close()
                except Exception:
                    pass
            except Exception as error:
                row['error'] = repr(error)
            out[label] = row
        try:
            import patch.config as _pc
            consts = {}
            for holder in (_pc, getattr(_pc, 'PatchConst', None)):
                if holder is None:
                    continue
                for key in ('CHECK_NPK_VALID', 'USE_CHECK_FILE_MD5', 'NPK_MD5_CK_CNT', 'FILES_MD5_PATH', 'USE_TOTAL_LIST'):
                    if hasattr(holder, key):
                        consts[key] = safe(getattr(holder, key), 120)
            out['patch_config'] = consts
        except Exception as error:
            out['errors'].append('patch.config %r' % (error,))
    except Exception as error:
        out['errors'].append(repr(error))
    try:
        _dh_os.remove(test_path)
    except Exception:
        pass
    try:
        path = _dh_os.path.join(_dh_logs_dir(), 'npk_test.json')
        with open(path, 'wb') as handle:
            handle.write(u''.join(_dh_json_chunks(out)).encode('ascii'))
    except Exception:
        pass
    log('local-npk-test', **out)





