# --- m61: Daily Special Offer (half-month packages).  The server now sells the diamond packs (server_ext/limit_packs.py);
# the client still checks each pack's own dates (2018-2025) before showing and buying it.  Give the game-currency packs
# whose window has closed an open window (2020 - 2030).  148 small objects, once per lobby entry.
_DH_PACK_OPEN = ('2020.1.1 00:00:00', '2030.12.31 23:59:59')


def _dh_pack_data():
    for module_name in ('ui.UITimeLimitActivityHalfMonthPackage', 'iLimitPackage'):
        module = _dh_sys.modules.get(module_name)
        if module is None:
            try:
                module = __import__(module_name, fromlist=['x'])
            except Exception:
                continue
        data = getattr(module, 'legacyProperties', None)
        if data is not None and hasattr(data, 'iterHalfMonthPackageData'):
            return data
    return None


def _dh_fix_pack_dates():
    data = _dh_pack_data()
    if data is None:
        return 0
    fixed = 0
    soon = _dh_time.time() + 30 * 86400
    for entry in data.iterHalfMonthPackageData():
        item = entry[1] if isinstance(entry, tuple) and len(entry) == 2 else entry
        if getattr(item, 'PAY_GOOD_ID', ''):
            continue
        try:
            ends = _dh_time.mktime(_dh_time.strptime(str(getattr(item, 'OFFLINE_TIME', '')), '%Y.%m.%d %H:%M:%S'))
        except Exception:
            ends = 0
        if ends < soon:
            setattr(item, 'ONLINE_TIME', _DH_PACK_OPEN[0])
            setattr(item, 'OFFLINE_TIME', _DH_PACK_OPEN[1])
            fixed += 1
    # m62: Draw Supply Box gifts (open N boxes -> claim) use the same date check for their "claimable" badge
    for entry in getattr(data, 'iterOpenSupplyGiftData', lambda: [])():
        item = entry[1] if isinstance(entry, tuple) and len(entry) == 2 else entry
        try:
            ends = _dh_time.mktime(_dh_time.strptime(str(getattr(item, 'OFFLINE_TIME', '')), '%Y.%m.%d %H:%M:%S'))
        except Exception:
            ends = 0
        if ends < soon:
            setattr(item, 'ONLINE_TIME', _DH_PACK_OPEN[0])
            setattr(item, 'OFFLINE_TIME', _DH_PACK_OPEN[1])
            fixed += 1
    return fixed


try:
    log('local-pack-dates', fixed=_dh_fix_pack_dates(), at='load')
except Exception:
    log_error('local-pack-dates-error')

# --- m64: "Event Now On" tiles did nothing when tapped: UIHotActivity hands client_utils.doUIJump the tile's JUMP_ID
# config object, but this build's doUIJump only accepts a number or a dict.  Give it the destination number (or a dict
# when the jump carries a parameter).  Verified: Amazing $0.99, Drone, Paraglider, Weekend Rush, Recruit, VIP open.
def _dh_jump_wrapper(jumpIdx, *args, **kwargs):
    inner = _dh_jump_wrapper._dh_inner
    try:
        if not isinstance(jumpIdx, (int, long, dict)) and hasattr(jumpIdx, 'JUMP_DESTINATION'):
            dest = int(getattr(jumpIdx, 'JUMP_DESTINATION'))
            param = getattr(jumpIdx, 'JUMP_PARAM_ID', 0) or 0
            if param:
                jumpIdx = dict((f, getattr(jumpIdx, f, None)) for f in
                               ('COULD_JUMP', 'JUMP_DES', 'JUMP_DESTINATION', 'JUMP_PARAM_ID', 'JUMP_TIMES'))
            else:
                jumpIdx = dest
    except Exception:
        log_error('local-jump-convert-error')
    return inner(jumpIdx, *args, **kwargs)


def _dh_install_jump_fix():
    module = _dh_sys.modules.get('client_utils')
    if module is None:
        try:
            module = __import__('client_utils')
        except Exception:
            return False
    current = getattr(module, 'doUIJump', None)
    if current is None:
        return False
    inner = current
    while hasattr(inner, '_dh_inner'):
        inner = inner._dh_inner
    _dh_jump_wrapper._dh_inner = inner
    module.doUIJump = _dh_jump_wrapper
    return True


try:
    log('local-jump-fix', installed=_dh_install_jump_fix())
except Exception:
    log_error('local-jump-fix-error')

# --- m65: Weekend Rush (King of the Hill board, rank type 71): the server answers with kind 'weekend'; hand the rows to
# the Weekend Rush screen's own callbacks instead of the generic leaderboard.
def _dh_fill_weekend_row(info):
    """Your own row of the King of the Hill board: unranked players kept the template's sample numbers."""
    try:
        import Globals
        ui = getattr(Globals.uiMgr, 'UIWeekendPush', None)
        panel = getattr(getattr(getattr(ui, 'rankListPanel', None), '_avatarInfoPanel', None), 'getChildByName', None)
        if not callable(panel):
            return
        rank = int(info.get('rank') or 0)
        games = int(info.get('gameCount') or 0)
        values = (('text_rank', str(rank) if rank else '-'), ('text_col_3', str(int(info.get('value') or 0))),
                  ('text_col_4', str(games)), ('text_col_5', '{:0.2f}%'.format(float(info.get('topFiveRate') or 0)) if games else '0%'))
        for name, text in values:
            widget = panel(name)
            if widget is not None:
                widget.setString(text)
        extra = panel('text_col_6')
        if extra is not None:
            extra.setString('')
    except Exception:
        log_error('local-weekend-row-error')


def _dh_install_weekend_board():
    callbacks = globals().get('RANK_LIST_CALLBACKS')
    local = globals().get('LOCAL_CALLBACKS')
    if not isinstance(callbacks, dict) or not isinstance(local, dict):
        return False
    callbacks['weekend'] = 'onRequireBattleGroundWeekendPushRankList'
    current = local.get('rlMyRank')
    inner = getattr(current, '_dh_inner', current)

    def my_rank(player, rank_type, info, kind, _inner=inner):
        if kind == 'weekend':
            target = getattr(player, 'onGetWeekendPushRankData', None)
            entry = globals().get('ItemEntry')
            if callable(target):
                target(entry(info or {'rank': 0}) if callable(entry) else info)
            _dh_fill_weekend_row(info or {})
            return None
        return _inner(player, rank_type, info, kind)

    my_rank._dh_inner = inner
    local['rlMyRank'] = my_rank
    return True


try:
    log('local-weekend-board', installed=_dh_install_weekend_board())
except Exception:
    log_error('local-weekend-board-error')

# --- m66: Event Now On tiles and lobby event buttons (MainEntrance) from the console: Off hides a tile/button
# (Vote Roulette: its activity data was the original server's and no longer exists), a title renames it.
_dh_entrance = globals().get('_dh_entrance') or {'hidden': set(), 'names': {}, 'stock_names': {}}
_dh_entrance.setdefault('originals', {})
_dh_entrance.setdefault('stock_resident', {})


def _dh_entrance_module():
    module = _dh_sys.modules.get('dts_main_entrance_utils')
    if module is None:
        try:
            module = __import__('dts_main_entrance_utils')
        except Exception:
            return None
    return module


def _dh_entrance_keys(item):
    """The console's names for one MainEntrance record: its jump id, and jump.<picture stem> (m108: the Lucky
    Carnival panel and the Carnival 50%-off slot share jump 301)."""
    try:
        key = str(int(getattr(getattr(item, 'JUMP_ID', None), 'JUMP_DESTINATION', 0) or 0))
    except Exception:
        return ('',)
    stem = str(getattr(item, 'NML_TEX_PATH', '') or '').replace('\\', '/').rsplit('/', 1)[-1].rsplit('.', 1)[0]
    return (key, key + '.' + stem) if stem else (key,)


def _dh_entrance_filter(items):
    hidden = _dh_entrance['hidden']
    out = []
    for item in items or []:
        if not any(k in hidden for k in _dh_entrance_keys(item)):
            out.append(item)
    return out


def _dh_install_entrance_filter():
    module = _dh_entrance_module()
    if module is None:
        return False
    for name in ('getAvailableActivityData', 'getStaticActivityData'):
        current = getattr(module, name, None)
        if current is None:
            continue
        original = current
        while getattr(original, '_dh_inner', None) is not None:   # m70: unwrap (m66-m69 wrappers shared one original)
            original = original._dh_inner
        original = _dh_entrance['originals'].setdefault(name, original)

        def make(inner):
            def wrapper(*args, **kwargs):
                return _dh_entrance_filter(inner(*args, **kwargs))
            wrapper._dh_inner = inner
            wrapper._dh_m70 = True
            wrapper._dh_m108 = True
            return wrapper
        if name == 'getStaticActivityData':
            # m108: the top-right slots are fixed-purpose (left = Carnival, right = Monthly Offer): the list stays
            # whole so row i keeps slot i, and a hidden row's own slot is hidden (_dh_right_top_panel_fix).  Filtering
            # it moved the next row into the wrong slot (Carnival art that opened Monthly Offer).
            if current is not original:
                setattr(module, name, original)
        elif not getattr(current, '_dh_m108', False):
            setattr(module, name, make(original))
    return True


def _dh_right_top_panel_fix(ui):
    """The lobby's top-right slots are fixed slots filled from getStaticActivityData (row i -> slot i): a slot with
    no row, or whose row is hidden in the console (Vote Roulette, a promo off this season), is hidden instead of
    keeping its old picture."""
    module = _dh_entrance_module()
    rows = list(module.getStaticActivityData() or []) if module else []
    hidden = _dh_entrance['hidden']
    panels = list(getattr(ui, 'activityPanelList', None) or [])
    for index, panel in enumerate(panels):
        try:
            widget = panel.get('panel') if isinstance(panel, dict) else panel
            show = index < len(rows) and not any(k in hidden for k in _dh_entrance_keys(rows[index]))
            if widget is not None and hasattr(widget, 'setVisible'):
                widget.setVisible(show)
        except Exception:
            pass


def _dh_install_right_top_fix():
    module = _dh_sys.modules.get('ui.main.UIMainActivityRightTop')
    if module is None:
        try:
            module = __import__('ui.main.UIMainActivityRightTop', fromlist=['x'])
        except Exception:
            module = None
    cls = getattr(module, 'UIMainActivityRightTop', None) if module else None
    # m108: initPanelInfo (lobby entry, our refresh) shows the slots again after filling them: the slot rule runs
    # after it too.  Same signature as the game's (self only).
    fill = cls.__dict__.get('initPanelInfo') if cls is not None else None
    if fill is not None and not getattr(fill, '_dh_m108', False):
        def initPanelInfo(self):
            result = initPanelInfo._dh_inner(self)
            try:
                _dh_right_top_panel_fix(self)
            except Exception:
                log_error('local-right-top-fix-error')
            return result
        initPanelInfo._dh_inner = fill
        initPanelInfo._dh_m108 = True
        cls.initPanelInfo = initPanelInfo
    current = cls.__dict__.get('updateActivityPanel') if cls is not None else None
    if current is None or getattr(current, '_dh_inner', None) is not None:
        return False

    def updateActivityPanel(self, *args, **kwargs):
        result = updateActivityPanel._dh_inner(self, *args, **kwargs)
        try:
            _dh_right_top_panel_fix(self)
        except Exception:
            log_error('local-right-top-fix-error')
        return result
    updateActivityPanel._dh_inner = current
    cls.updateActivityPanel = updateActivityPanel
    try:
        # m108: the block lives on UIMain (Globals.uiMgr has no UIMainActivityRightTop, so this never refreshed)
        refresh = globals().get('_dh_promo_refresh_panel')
        if refresh is not None:
            refresh()
    except Exception:
        log_error('local-right-top-refresh-error')
    return True


def _dh_apply_entrances(rows):
    """rows: {jump_destination: {mode, title}}."""
    changed = []
    hidden = set()
    shown = set()
    names = {}
    for key, override in (rows or {}).items():
        if not isinstance(override, dict):
            continue
        if str(override.get('mode') or 'stock') == 'off':
            hidden.add(str(key))
        elif str(override.get('mode') or 'stock') in ('on', 'yearly'):
            shown.add(str(key))
        title = str(override.get('title') or '').strip()
        if title:
            names[str(key)] = title
    if hidden != _dh_entrance['hidden']:
        changed.append('MainEntrance.hidden=%s' % ','.join(sorted(hidden)))
    _dh_entrance['hidden'] = hidden
    _dh_install_entrance_filter()
    _dh_install_right_top_fix()
    module = _dh_entrance_module()
    data = getattr(module, 'legacyProperties', None) if module else None
    if data is not None and hasattr(data, 'iterMainEntranceData'):
        for n, entry in enumerate(data.iterMainEntranceData()):
            item = entry[1] if isinstance(entry, tuple) and len(entry) == 2 else entry
            try:
                key = str(int(item.JUMP_ID.JUMP_DESTINATION))
            except Exception:
                continue
            # m108: a record the console turns on joins the lobby's event list (a static slot row already shows)
            resident_key = key + '/' + str(n)
            resident_stock = _dh_entrance['stock_resident'].setdefault(resident_key, bool(getattr(item, 'IS_RESIDENT_SHOW', False)))
            want_resident = resident_stock or (any(k in shown for k in _dh_entrance_keys(item)) and not getattr(item, 'IS_STATIC', False))
            if bool(getattr(item, 'IS_RESIDENT_SHOW', False)) != want_resident:
                try:
                    setattr(item, 'IS_RESIDENT_SHOW', want_resident)
                    changed.append('MainEntrance.%s.IS_RESIDENT_SHOW=%s' % (key, want_resident))
                except Exception:
                    pass
            stock = _dh_entrance['stock_names'].setdefault(key + '/' + str(n), getattr(item, 'NAME', ''))
            want = names.get(key, stock)
            if getattr(item, 'NAME', '') != want:
                setattr(item, 'NAME', want)
                changed.append('MainEntrance.%s.NAME' % key)
    if changed:
        refresh = globals().get('_dh_promo_refresh_panel')     # m108: redraw the lobby's top-right if it is up
        if refresh is not None:
            refresh()
    return changed



# m68: hidden tiles take effect before the lobby is built (the lobby's event buttons are fixed slots filled once):
# apply the last pushed MainEntrance settings from the local copy at patch load.
try:
    _dh_cached_events = (_dh_load_cached_lobby() or {}).get('events') or {}
    if isinstance(_dh_cached_events, dict) and _dh_cached_events.get('MainEntrance'):
        log('local-entrances-early', changed=_dh_apply_entrances(_dh_cached_events.get('MainEntrance')))
except Exception:
    log_error('local-entrances-early-error')

# --- m71: Monthly Offer (UIMonthlyBenefit34, top-up rewards): a tier without a status from the server kept the
# layout's "OBTAINED" stamp, so every reward looked claimed.  Until real top-ups are recorded, every tier is
# "not reached yet" (MonthPayRebateSpecialAwardStatusEnum, read from the client).
_DH_MONTHLY_TIERS = 4


def _dh_fix_monthly_benefit(player):
    if player is None:
        return None
    info = getattr(player, 'monthPayRebateSpecialAwardInfo', None)
    awards = (info or {}).get('awards') if hasattr(info, 'get') else None
    if awards:
        return None
    status = 0
    for module in list(_dh_sys.modules.values()):
        enum = getattr(module, 'MonthPayRebateSpecialAwardStatusEnum', None) if module is not None else None
        if enum is not None:
            for name in ('CANT', 'CAN_NOT', 'NOT_REACH', 'NOT_REACHED', 'UNREACHED', 'NONE', 'LOCKED'):
                if hasattr(enum, name):
                    status = int(getattr(enum, name))
                    break
            break
    value = {'awards': dict((i, {'status': status}) for i in range(1, _DH_MONTHLY_TIERS + 1))}
    try:
        player.monthPayRebateSpecialAwardInfo = value
    except Exception:
        try:
            info.clear()
            info.update(value)
        except Exception:
            return None
    return 'tiers %d set to status %d' % (_DH_MONTHLY_TIERS, status)



# --- m72: the lobby's Welfare tab did nothing: UIMain.onWelfareBtnClicked returns early when the player is a
# PlayerAccount (the pre-character login state) and our lobby player is one.  The screen itself works; open it.
def _dh_welfare_click(self, args, *rest, **kwargs):
    try:
        touch = getattr(args, 'touch', None)
        ended = getattr(_dh_sys.modules.get('Input'), 'TouchPhase', None)
        ended = getattr(ended, 'Ended', None)
        if touch is not None and ended is not None and getattr(touch, 'phase', None) != ended:
            return None
        import Globals
        Globals.uiMgr.enter_ui('UIWelfareController')
        return None
    except Exception:
        log_error('local-welfare-click-error')
    return _dh_welfare_click._dh_inner(self, args, *rest, **kwargs)


def _dh_install_welfare_click():
    module = _dh_sys.modules.get('ui.UIMain')
    if module is None:
        try:
            module = __import__('ui.UIMain', fromlist=['x'])
        except Exception:
            return False
    cls = getattr(module, 'UIMain', None)
    installed = []
    for name in ('onWelfareBtnClicked', 'onWelfareEvent'):
        current = cls.__dict__.get(name) if cls is not None else None
        if current is None:
            continue
        inner = current
        while getattr(inner, '_dh_inner', None) is not None:
            inner = inner._dh_inner

        def make(inner):
            def handler(self, args, *rest, **kwargs):
                return _dh_welfare_click(self, args, *rest, **kwargs)
            handler._dh_inner = inner
            return handler
        setattr(cls, name, make(inner))
        installed.append(name)
    _dh_welfare_click._dh_inner = cls.__dict__['onWelfareBtnClicked']._dh_inner if 'onWelfareBtnClicked' in installed else None
    return installed


def _dh_entrance_clicked(self, args):
    """UIMain.onBtnFunctionEntranceClicked: the top tabs' click message.  Its owner (UIMainFunctionEntrance) is not
    attached in this lobby, so the message found no receiver and Welfare / data / competition / Settings did
    nothing.  Same action as the original: jump to the tab's destination."""
    touch = getattr(args, 'touch', None)
    ended = getattr(getattr(_dh_sys.modules.get('Input'), 'TouchPhase', None), 'Ended', None)
    if touch is not None and ended is not None and getattr(touch, 'phase', None) != ended:
        return None
    try:
        cu = _dh_sys.modules.get('client_utils') or __import__('client_utils')
        cu.doUIJump(getattr(args, 'userData', None))
    except Exception:
        log_error('local-entrance-click-error')
    return None


def _dh_install_entrance_click():
    module = _dh_sys.modules.get('ui.UIMain')
    cls = getattr(module, 'UIMain', None) if module else None
    if cls is None or 'onBtnFunctionEntranceClicked' in cls.__dict__ and not getattr(cls.__dict__['onBtnFunctionEntranceClicked'], '_dh', False):
        return False
    _dh_entrance_clicked._dh = True
    cls.onBtnFunctionEntranceClicked = _dh_entrance_clicked
    return True


_DH_WEB_JUMPS = (1, 993, 10000)       # jumps that opened the old official web pages (competition = ROS Match site)


def _dh_open_competition(cu):
    """competition: the official tournament site is gone, so the tab opens our live competition (Weekend Rush and
    its rank board), else the ranking boards."""
    import Globals
    try:
        Globals.uiMgr.enter_ui('UIWeekendPush')
        return 'UIWeekendPush'
    except Exception:
        log_error('local-competition-open-error')
    cu.doUIJump(612)
    return 'rank'


def _dh_bind_top_tabs(ui):
    """Each top tab gets its own click listener that jumps to its destination (the panel object that normally
    receives the click message is inactive in this lobby)."""
    module = _dh_sys.modules.get('ui.main.UIMainFunctionEntrance')
    data = getattr(module, 'legacyProperties', None) if module else None
    if data is None:
        return 0
    dest = {}
    for n, entry in enumerate(data.iterMainEntranceFunctionData()):
        item = entry[1] if isinstance(entry, tuple) and len(entry) == 2 else entry
        try:
            dest[str(getattr(item, 'NAME', '')).strip()] = int(item.JUMP_ID.JUMP_DESTINATION)
        except Exception:
            continue
    cu = _dh_sys.modules.get('client_utils') or __import__('client_utils')
    bound = 0
    for path, node in walk_ui_nodes(ui, limit=3000):
        if not path.endswith('/entanceTop') or 'top-navigator' not in path:
            continue
        try:
            label = node.getChildByName('text')
            name = str(label.getString()).strip() if label is not None else ''
        except Exception:
            continue
        target = dest.get(name)
        if target is None:
            if name.lower() in ('data', 'leaderboard', 'rank') or 'data' in name.lower():
                target = 612
            else:
                continue

        try:
            if not node.isVisible():
                node.setVisible(True)
                parent = node.getParent()
                layout = getattr(parent, 'forceDoLayout', None)
                if callable(layout):
                    layout()
        except Exception:
            pass

        def on_touch(sender, event, _target=target):
            if int(event) == 2:          # ccui TOUCH_EVENT_ENDED
                try:
                    if _target in _DH_WEB_JUMPS:
                        _dh_open_competition(cu)
                    elif _target == 612:
                        try:
                            import Globals
                            Globals.uiMgr.enter_ui('UIRankList')
                        except Exception:
                            cu.doUIJump(612)
                    else:
                        cu.doUIJump(_target)
                except Exception:
                    log_error('local-top-tab-jump-error', target=_target)
        node.addTouchEventListener(on_touch)
        bound += 1
    return bound


def _dh_unblock_top_tabs(player=None):
    """The lobby's top tabs (Welfare, data...): the second, mostly empty tab list (entance_list_dynamic) lies over
    them and swallowed their clicks.  Let its touches pass through."""
    import Globals
    ui = getattr(Globals.uiMgr, 'UIMain', None)
    if ui is None:
        return False
    _dh_bind_top_tabs(ui)
    for path, node in walk_ui_nodes(ui, limit=3000):
        if path.endswith('top-navigator/entance_list_dynamic'):
            shown = [i for i in (node.getItems() or []) if i.isVisible()] if hasattr(node, 'getItems') else []
            if not shown:
                node.setTouchEnabled(False)       # empty: nothing of its own to tap, and it lay over Welfare / data
            node.setSwallowTouches(False)
            return 'disabled' if not shown else 'pass-through (%d tabs)' % len(shown)
    return False


