def _dh_install_death_killer_guard():
    """m133 (2026-11-06): UIDeathKillerDisplay._showKillerOverview crashed with 'NoneType' object has no attribute
    'body' when the killer has no body - killed by a despawned bot, the blue zone, a fall, or a killer who already
    left the match.  The exception aborted the death screen's whole on_enter (seen on 8 current-runtime players).
    Guard the killer-overview so a bodyless killer simply skips that sub-panel instead of crashing the death UI.
    Installed as the screen opens (the module is loaded by then) and idempotent."""
    mod = _dh_sys.modules.get('ui.UIDeathKillerDisplay')
    if mod is None:
        try:
            mod = __import__('ui.UIDeathKillerDisplay', fromlist=['UIDeathKillerDisplay'])
        except Exception:
            return 'no-module'
    cls = getattr(mod, 'UIDeathKillerDisplay', None)
    if cls is None or '_showKillerOverview' not in vars(cls):
        return 'no-method'
    base = vars(cls)['_showKillerOverview']
    if getattr(base, '_dh_death_guard', False):
        return 'already'

    def _showKillerOverview(self, *args, **kwargs):
        try:
            return base(self, *args, **kwargs)
        except Exception as error:
            log('local-death-killer-guard', err=type(error).__name__)
            return None
    _showKillerOverview._dh_death_guard = True
    _showKillerOverview._dh_inner = base
    cls._showKillerOverview = _showKillerOverview
    return 'installed'


_DH_CRASH_GUARDS = [
    ('ui.UIDtsAppearanceNewAdded', 'UIDtsAppearanceNewAdded', 'itemPanelSubWidgetInitFunc'),
    ('ui.UIDtsAppearanceCustomizedSuit', 'UIDtsAppearanceCustomizedSuit', 'itemPanelSubWidgetInitFunc'),
    ('ui.UISubModesEnter', 'UISubModesEnter', 'onSelectPanel'),
    ('ui.UISubModesEnter', 'UISubModesEnter', '_initGoldBattlePanel'),
    ('ui.UISubModesEnter', 'UIModesList', '_initGoldBattlePanel'),
    ('ui.UISubModesEnter', 'UIModesList', '__reorderTypePanels'),
    ('ui.UISubModesEnter', 'UISubModesEnter', 'onConfirmEvent'),
    ('ui.UISubModesEnter', 'UISubModesEnter', 'onCancelEvent'),
]


def _dh_patch_submodes_enter():
    for mod_name, mod in list(_dh_sys.modules.items()):
        if mod is not None:
            try:
                if not hasattr(mod, 'I_GOLD_BATTLE_NEW_YEAR_BASE_TIME'):
                    setattr(mod, 'I_GOLD_BATTLE_NEW_YEAR_BASE_TIME', 0)
            except Exception:
                pass
    try:
        mod = _dh_sys.modules.get('ui.UISubModesEnter')
        if mod is None:
            try:
                mod = __import__('ui.UISubModesEnter', fromlist=['UISubModesEnter', 'UIModesList'])
            except Exception:
                mod = None
        if mod is not None:
            if not hasattr(mod, 'I_GOLD_BATTLE_NEW_YEAR_BASE_TIME'):
                setattr(mod, 'I_GOLD_BATTLE_NEW_YEAR_BASE_TIME', 0)
            for attr_name, val in list(vars(mod).items()):
                if type(val).__name__ == 'module':
                    try:
                        if not hasattr(val, 'I_GOLD_BATTLE_NEW_YEAR_BASE_TIME'):
                            setattr(val, 'I_GOLD_BATTLE_NEW_YEAR_BASE_TIME', 0)
                    except Exception:
                        pass
                if isinstance(val, dict):
                    if 'RosTopia' not in val:
                        val['RosTopia'] = lambda *a, **k: None
                    if 'rostopia' not in val:
                        val['rostopia'] = lambda *a, **k: None

            for cls_name, cls in list(vars(mod).items()):
                if isinstance(cls, (type, type(object))) or type(cls).__name__ == 'classobj':
                    if hasattr(cls, '_initGoldBattlePanel'):
                        orig_g = getattr(cls, '_initGoldBattlePanel')
                        if orig_g and not getattr(orig_g, '_dh_guarded', False):
                            def _safe_gold(self, *a, **k):
                                try:
                                    return orig_g(self, *a, **k)
                                except Exception as err:
                                    try:
                                        log('local-gold-battle-error', err=str(err))
                                    except Exception:
                                        pass
                                    return None
                            _safe_gold._dh_guarded = True
                            setattr(cls, '_initGoldBattlePanel', _safe_gold)

                    for r_name in ('_UIModesList__reorderTypePanels', '__reorderTypePanels', 'onLimitGameTypeUpdate'):
                        if hasattr(cls, r_name):
                            orig_r = getattr(cls, r_name)
                            if orig_r and not getattr(orig_r, '_dh_guarded', False):
                                def _make_safe_r(orig_fn, fn_name):
                                    def _safe_r(self, *a, **k):
                                        try:
                                            return orig_fn(self, *a, **k)
                                        except Exception as err:
                                            try:
                                                log('local-submode-reorder-error', fn=fn_name, err=str(err))
                                            except Exception:
                                                pass
                                            return None
                                    _safe_r._dh_guarded = True
                                    return _safe_r
                                setattr(cls, r_name, _make_safe_r(orig_r, r_name))

                    if hasattr(cls, 'onConfirmEvent'):
                        orig_c = getattr(cls, 'onConfirmEvent')
                        if orig_c and not getattr(orig_c, '_dh_guarded', False):
                            def _safe_confirm(self, *a, **k):
                                try:
                                    for dname in dir(self):
                                        try:
                                            dval = getattr(self, dname, None)
                                            if isinstance(dval, dict):
                                                if 'RosTopia' not in dval:
                                                    dval['RosTopia'] = lambda *x, **y: None
                                                if 'rostopia' not in dval:
                                                    dval['rostopia'] = lambda *x, **y: None
                                        except Exception:
                                            pass
                                    return orig_c(self, *a, **k)
                                except KeyError as ke:
                                    try:
                                        log('local-submode-confirm-keyerror', key=str(ke))
                                    except Exception:
                                        pass
                                    try:
                                        import Globals
                                        Globals.uiMgr.leave_ui('UISubModesEnter')
                                    except Exception:
                                        pass
                                    try:
                                        if hasattr(self, 'close'):
                                            self.close()
                                    except Exception:
                                        pass
                                    return None
                                except Exception as err:
                                    try:
                                        log('local-submode-confirm-error', err=str(err))
                                    except Exception:
                                        pass
                                    try:
                                        import Globals
                                        Globals.uiMgr.leave_ui('UISubModesEnter')
                                    except Exception:
                                        pass
                                    return None
                            _safe_confirm._dh_guarded = True
                            setattr(cls, 'onConfirmEvent', _safe_confirm)

                    if hasattr(cls, 'onCancelEvent'):
                        orig_cancel = getattr(cls, 'onCancelEvent')
                        if orig_cancel and not getattr(orig_cancel, '_dh_guarded', False):
                            def _safe_cancel(self, *a, **k):
                                try:
                                    orig_cancel(self, *a, **k)
                                except Exception:
                                    pass
                                try:
                                    import Globals
                                    Globals.uiMgr.leave_ui('UISubModesEnter')
                                except Exception:
                                    pass
                                try:
                                    if hasattr(self, 'close'):
                                        self.close()
                                except Exception:
                                    pass
                            _safe_cancel._dh_guarded = True
                            setattr(cls, 'onCancelEvent', _safe_cancel)
    except Exception:
        pass


try:
    _dh_patch_submodes_enter()
except Exception:
    pass


def _dh_crash_guard_factory(base, tag):
    def _dh_guarded(self, *args, **kwargs):
        try:
            return base(self, *args, **kwargs)
        except Exception as error:
            log('local-crash-guard', where=tag, err=type(error).__name__)
            return None
    _dh_guarded._dh_crash_guard = True
    _dh_guarded._dh_inner = base
    return _dh_guarded


def _dh_install_crash_guards(tries=0):
    """m134 (2026-11-06): wrap a handful of game UI methods that crashed on current builds so one bad item or a
    missing table value skips that widget/panel instead of aborting the whole screen - the appearance/wardrobe
    item panel (NoneType.NAME on a mobile-only item, same family as the empty-inventory fix) and the mode-select
    panels.  Each method is wrapped once its module has loaded; the retry keeps trying as the screens open."""
    done = 0
    for modname, clsname, method in _DH_CRASH_GUARDS:
        try:
            mod = _dh_sys.modules.get(modname)
            if mod is None:
                continue
            cls = getattr(mod, clsname, None)
            if cls is None or method not in vars(cls):
                continue
            base = vars(cls)[method]
            if getattr(base, '_dh_crash_guard', False):
                done += 1
                continue
            setattr(cls, method, _dh_crash_guard_factory(base, clsname + '.' + method))
            done += 1
        except Exception:
            log_error('local-crash-guard-install-error', where=modname)
    if done < len(_DH_CRASH_GUARDS) and tries < 600:
        call_later(2.0, _dh_install_crash_guards, tries + 1)
    elif tries == 0 or done >= len(_DH_CRASH_GUARDS):
        log('local-crash-guards', installed=done, of=len(_DH_CRASH_GUARDS))


try:
    call_later(2.0, _dh_install_crash_guards)
except Exception:
    log_error('local-crash-guards-start-error')


_dh_last_pack_buy = globals().get('_dh_last_pack_buy') or {
    'active': False,
    'goodID': 0,
    'buyNum': 1,
    'cashCoupons': [],
    'MallLogStr': 'MallGiftBag',
    'rpcName': 'buyMallGood',
    'currencyID': 2,
    'price': 0,
    'confirmBtnTxt': 'Buy Again',
    'gotoCB': None,
    'seq': 0,
    'buying_again_at': 0.0,
    'last_conf_click_at': 0.0,
    'last_opened': []
}


def _dh_is_buying_again():
    try:
        import time as _t
        return (_t.time() - float(_dh_last_pack_buy.get('buying_again_at', 0.0) or 0.0)) < 2.5
    except Exception:
        return False


def _dh_buy_again_watchdog():
    """If a 'Buy Again' purchase failed (e.g. out of diamonds) and UIItemDisplay did not re-open, restore Store UI."""
    try:
        import Globals
        ui_mgr = getattr(Globals, 'uiMgr', None)
        disp = getattr(ui_mgr, 'UIItemDisplay', None) if ui_mgr else None
        if disp is not None and getattr(disp, 'is_enter', False):
            return
        _dh_last_pack_buy['buying_again_at'] = 0.0
        _dh_last_pack_buy['active'] = False
        _dh_restore_mall_and_supply_ui()
    except Exception:
        pass


def _dh_trigger_pack_buy_again():
    """Re-executes the active Mall Pack / GiftBag purchase when 'Buy Again' is clicked on UIItemDisplay."""
    try:
        import BigWorld
        player = BigWorld.player()
        if player is None:
            return False
        good_id = int(_dh_last_pack_buy.get('goodID') or 0)
        if good_id <= 0:
            return False
        buy_num = max(1, int(_dh_last_pack_buy.get('buyNum') or 1))
        coupons = list(_dh_last_pack_buy.get('cashCoupons') or [])
        log_str = str(_dh_last_pack_buy.get('MallLogStr') or 'MallGiftBag')
        rpc_name = str(_dh_last_pack_buy.get('rpcName') or 'buyMallGood')
        base_obj = getattr(player, 'base', None)
        fn = getattr(base_obj, rpc_name, None) if base_obj is not None else None
        if not callable(fn):
            fn = getattr(base_obj, 'buyMallGood', None) if base_obj is not None else None
        if callable(fn):
            fn(good_id, buy_num, coupons, log_str)
            log('local-pack-buy-again', good_id=good_id, count=buy_num, rpc=rpc_name)
            return True
    except Exception:
        log_error('local-pack-buy-again-error')
    return False


def _dh_install_main_watch():
    import Globals
    mgr = getattr(Globals, 'uiMgr', None)
    current = getattr(mgr, 'enter_ui', None) if mgr is not None else None
    if current is None:
        return False
    inner = current
    while getattr(inner, '_dh_inner', None) is not None or getattr(inner, '_redemption_inner', None) is not None:
        inner = getattr(inner, '_dh_inner', None) or getattr(inner, '_redemption_inner', None)

    def enter_ui(ui_name, *args, **kwargs):
        if ui_name == 'UIDeathKillerDisplay':
            try:
                _dh_install_death_killer_guard()
            except Exception:
                log_error('local-death-killer-install-error')
        elif ui_name == 'UIGiftBagConfirm':
            try:
                if args and isinstance(args[0], dict):
                    gb_args = args[0]
                    if gb_args.get('goodID') is not None:
                        _dh_last_pack_buy['goodID'] = int(gb_args.get('goodID') or 0)
                    if gb_args.get('currencyID') is not None:
                        _dh_last_pack_buy['currencyID'] = int(gb_args.get('currencyID') or 2)
                    if gb_args.get('price') is not None:
                        _dh_last_pack_buy['price'] = int(gb_args.get('price') or 0)
                    if gb_args.get('MallLogStr'):
                        _dh_last_pack_buy['MallLogStr'] = str(gb_args.get('MallLogStr'))
                    _dh_last_pack_buy['active'] = True
                    _dh_last_pack_buy['buying_again_at'] = 0.0
            except Exception:
                pass
        elif ui_name == 'UIItemDisplay':
            try:
                if args and isinstance(args[0], dict):
                    disp_args = args[0]
                    _dh_last_pack_buy['buying_again_at'] = 0.0
                    # Ensure isBGShow and isConfirmBtnShow are True so the UI and buttons are always rendered
                    disp_args['isBGShow'] = True
                    disp_args['isConfirmBtnShow'] = True
                    disp_args['onlyItem'] = False

                    if disp_args.get('confirmBtnTxt'):
                        _dh_last_pack_buy['confirmBtnTxt'] = disp_args.get('confirmBtnTxt')
                    if disp_args.get('gotoCB') or disp_args.get('gotoBtnCallback'):
                        _dh_last_pack_buy['gotoCB'] = disp_args.get('gotoCB') or disp_args.get('gotoBtnCallback')

                    if _dh_last_pack_buy.get('active'):
                        disp_args['onlyShowReturnBtn'] = False
                        disp_args['confirmBtnTxt'] = disp_args.get('confirmBtnTxt') or _dh_last_pack_buy.get('confirmBtnTxt') or 'Buy Again'
                        if not disp_args.get('currencyID') and _dh_last_pack_buy.get('currencyID'):
                            disp_args['currencyID'] = _dh_last_pack_buy.get('currencyID')
                        if not disp_args.get('gotoCB') and _dh_last_pack_buy.get('gotoCB'):
                            disp_args['gotoCB'] = _dh_last_pack_buy.get('gotoCB')

                    raw_ret = disp_args.get('returnBtnCb')
                    def _dh_safe_leave_ret(*_a, **_kw):
                        _dh_last_pack_buy['active'] = False
                        _dh_last_pack_buy['buying_again_at'] = 0.0
                        try:
                            if callable(raw_ret):
                                raw_ret(*_a, **_kw)
                        except Exception:
                            pass
                        try:
                            import Globals
                            Globals.uiMgr.leave_ui('UIItemDisplay')
                        except Exception:
                            pass
                        _dh_restore_mall_and_supply_ui()

                    raw_conf = disp_args.get('confirmBtnCb')
                    def _dh_safe_leave_conf(*_a, **_kw):
                        import time as _t
                        now = _t.time()
                        if (now - float(_dh_last_pack_buy.get('last_conf_click_at', 0.0) or 0.0)) < 0.35:
                            return
                        _dh_last_pack_buy['last_conf_click_at'] = now

                        if _dh_last_pack_buy.get('active') and int(_dh_last_pack_buy.get('goodID') or 0) > 0:
                            _dh_last_pack_buy['buying_again_at'] = now
                            seq_before = int(_dh_last_pack_buy.get('seq') or 0)
                            try:
                                import Globals
                                Globals.uiMgr.leave_ui('UIItemDisplay')
                            except Exception:
                                pass
                            try:
                                if callable(raw_conf) and raw_conf is not raw_ret:
                                    raw_conf(*_a, **_kw)
                            except Exception:
                                pass
                            if int(_dh_last_pack_buy.get('seq') or 0) == seq_before:
                                _dh_trigger_pack_buy_again()
                            call_later(1.2, _dh_buy_again_watchdog)
                            return

                        # Non-pack confirm button (e.g. Supply Box 'Buy Again' or normal 'Confirm')
                        _dh_last_pack_buy['buying_again_at'] = now
                        try:
                            if callable(raw_conf):
                                raw_conf(*_a, **_kw)
                        except Exception:
                            pass
                        try:
                            import Globals
                            Globals.uiMgr.leave_ui('UIItemDisplay')
                        except Exception:
                            pass
                        call_later(0.05, _dh_restore_mall_and_supply_ui)
                        call_later(0.3, _dh_restore_mall_and_supply_ui)
                        call_later(0.8, _dh_buy_again_watchdog)

                    disp_args['returnBtnCb'] = _dh_safe_leave_ret
                    disp_args['confirmBtnCb'] = _dh_safe_leave_conf

                    raw_items = disp_args.get('itemIDs')
                    if isinstance(raw_items, list):
                        safe_items = []
                        for entry in raw_items:
                            iid = entry[0] if isinstance(entry, (list, tuple)) and entry else entry
                            cnt = entry[1] if isinstance(entry, (list, tuple)) and len(entry) > 1 else 1
                            try:
                                iid = int(iid)
                            except Exception:
                                iid = 0
                            if iid == 0:
                                try:
                                    import BigWorld
                                    repl = getattr(BigWorld, '_dh_last_cultivate_target', 142008) or 142008
                                except Exception:
                                    repl = 142008
                                safe_items.append((repl, cnt) if isinstance(entry, (list, tuple)) else repl)
                            else:
                                safe_items.append(entry)
                        disp_args['itemIDs'] = safe_items
            except Exception:
                pass
        result = inner(ui_name, *args, **kwargs)
        try:
            if ui_name == 'UIItemDisplay':
                call_later(0.1, _dh_fix_item_display_ui)
                call_later(0.5, _dh_fix_item_display_ui)
                call_later(1.5, _dh_fix_item_display_ui)
            elif ui_name == 'UIMain':
                try:
                    _c = _dh_cc()
                    if _c:
                        _sc = _c.Director.getInstance().getRunningScene()
                        if _sc:
                            _b = _sc.getChildByName('ros_redemption_bg')
                            if _b is not None:
                                _b.setVisible(False)
                                _b.setPosition(-99999.0, -99999.0)
                except Exception:
                    pass
                call_later(0.5, _dh_main_ready)
            elif str(ui_name).startswith('UIBraveBook2'):
                call_later(0.3, _dh_relabel_manual)          # the season pass: its own refresh writes the number
                call_later(1.5, _dh_relabel_manual)
            elif ui_name in ('UILuckyCarnivalAdvance', 'UILuckyCarnivalSuper'):
                # m81c: on a fresh start the patch loads before these screens' code exists: hook them as they open
                _dh_carnival_opened(ui_name)
        except Exception:
            log_error('local-main-watch-error')
        return result
    enter_ui._dh_inner = inner
    mgr.enter_ui = enter_ui

    leave_current = getattr(mgr, 'leave_ui', None)
    if leave_current is not None:
        leave_inner = getattr(leave_current, '_dh_inner', leave_current)
        def leave_ui(ui_name, *args, **kwargs):
            if ui_name == 'UIItemDisplay':
                try:
                    cc = _dh_cc()
                    if cc:
                        sc = cc.Director.getInstance().getRunningScene()
                        if sc:
                            b = sc.getChildByName('dh_item_disp_fail_safe')
                            if b is not None:
                                sc.removeChild(b)
                except Exception:
                    pass
                if not _dh_is_buying_again():
                    _dh_last_pack_buy['active'] = False
                    call_later(0.05, _dh_restore_mall_and_supply_ui)
                    call_later(0.2, _dh_restore_mall_and_supply_ui)
                    call_later(0.5, _dh_restore_mall_and_supply_ui)
            return leave_inner(ui_name, *args, **kwargs)
        leave_ui._dh_inner = leave_inner
        mgr.leave_ui = leave_ui
    return True


def _dh_restore_mall_and_supply_ui():
    """Restores goods panels, subtabs, and touch interactivity for Mall, Supply, Workshop, and Depot when UIItemDisplay closes."""
    try:
        import Globals
        ui_mgr = getattr(Globals, 'uiMgr', None)
        if not ui_mgr:
            return

        # 1. Dismiss any lingering loading or confirmation dialogs that block touches
        for modal_name in ('UIPayLoading', 'UIGiftBagConfirm', 'UICommonMask'):
            try:
                modal = getattr(ui_mgr, modal_name, None)
                if modal is not None and getattr(modal, 'is_enter', False):
                    ui_mgr.leave_ui(modal_name)
            except Exception:
                pass
        try:
            import pay_utils
            pay_utils.closePay()
        except Exception:
            pass

        # 2. Hide UIMainActionAndEmoji so its floating stick-figure button never blocks Workshop or Depot touches
        try:
            for sub_name in ('UIDtsAppearance', 'UIDtsAppearanceVehicle', 'UIDtsAppearanceVehicleCultivate2', 'UIWorkshop', 'UIMall', 'UIMallController'):
                sub_scr = getattr(ui_mgr, sub_name, None)
                if sub_scr is not None and getattr(sub_scr, 'is_enter', False):
                    act_scr = getattr(ui_mgr, 'UIMainActionAndEmoji', None)
                    if act_scr is not None:
                        if hasattr(act_scr, 'setVisible'):
                            act_scr.setVisible(False)
                        if hasattr(act_scr, 'setTouchEnabled'):
                            act_scr.setTouchEnabled(False)
                    break
        except Exception:
            pass

        # 3. Restore all active screen panels and ensure full touch interactivity
        target_screens = [
            'UIMallController', 'UIMallCloth', 'UIMall',
            'UISupplyController', 'UISupplyPackage', 'UIAdvanceSupplyPackage',
            'UIMonthlySupplyPackage',
            'UIDtsAppearance', 'UIDtsAppearanceVehicle', 'UIDtsAppearanceVehicleCultivate2', 'UIWorkshop',
            'UIBraveBook2Tab', 'UIBraveBook2Award', 'UIBraveBook2Task',
            'UIBraveBook2Shop', 'UIBraveBook2'
        ]
        for scr_name in target_screens:
            scr = getattr(ui_mgr, scr_name, None)
            if scr is not None and getattr(scr, 'is_enter', False):
                try:
                    if hasattr(scr, 'setVisible'):
                        scr.setVisible(True)
                    if hasattr(scr, 'setTouchEnabled'):
                        scr.setTouchEnabled(True)
                    if scr_name in ('UIMall', 'UIMallController', 'UIMallCloth', 'UISupplyController'):
                        if hasattr(scr, 'leaveFullScreen') and callable(scr.leaveFullScreen):
                            scr.leaveFullScreen()
                    if hasattr(scr, 'refreshGeneralDisplayPanel') and callable(scr.refreshGeneralDisplayPanel):
                        scr.refreshGeneralDisplayPanel()
                    if hasattr(scr, 'refresh') and callable(scr.refresh):
                        scr.refresh()
                    if hasattr(scr, 'refreshMall') and callable(scr.refreshMall):
                        scr.refreshMall()
                    if hasattr(scr, 'refreshView') and callable(scr.refreshView):
                        scr.refreshView()
                    if hasattr(scr, '_UpdateSeasonView') and callable(scr._UpdateSeasonView):
                        scr._UpdateSeasonView()
                    if hasattr(scr, 'fillGoods') and callable(scr.fillGoods):
                        try:
                            import BigWorld
                            p = BigWorld.player()
                            if p:
                                g = getattr(p, 'recordMallGoods', None)
                                if isinstance(g, dict) and g:
                                    scr.fillGoods(g)
                        except Exception:
                            pass
                    root = getattr(scr, 'panel', None) or getattr(scr, 'widget', None)
                    if root is not None:
                        if hasattr(root, 'setVisible'):
                            root.setVisible(True)
                        if hasattr(root, 'setTouchEnabled'):
                            root.setTouchEnabled(True)
                    if scr_name in ('UIDtsAppearance', 'UIDtsAppearanceVehicle',
                                    'UIDtsAppearanceVehicleCultivate2', 'UIWorkshop'):
                        continue
                    for path, node in walk_ui_nodes(scr, limit=1000):
                        try:
                            if hasattr(node, 'setTouchEnabled'):
                                node.setTouchEnabled(True)
                            p_low = path.lower()
                            if any(k in p_low for k in ('right', 'goods', 'cloth', 'item_list', 'listview', 'panel_1', 'panel_di', 'panel_content', 'tab', 'btn', 'button', 'back', 'return', 'award', 'catalog', 'cell')):
                                if hasattr(node, 'setVisible'):
                                    node.setVisible(True)
                        except Exception:
                            pass
                except Exception:
                    pass
        call_later(0.1, _dh_relabel_manual)
    except Exception:
        pass


def _dh_fix_item_display_ui():
    """Ensure UIItemDisplay's BACK, Return and Confirm ('Buy Again') buttons are active and responsive."""
    try:
        import Globals
        ui_mgr = getattr(Globals, 'uiMgr', None)
        if not ui_mgr:
            return
        disp = getattr(ui_mgr, 'UIItemDisplay', None)
        if disp is not None and getattr(disp, 'is_enter', False):
            # 1. Ensure result panel and dlg root are visible
            for p in ('dlg', 'dlg/result_panel', 'dlg/result_panel/anchor-upper-left', 'dlg/result_panel/anchor-bottom-right', 'dlg/result_panel/anchor-bottom-left'):
                try:
                    w = disp.get_widget_by_path(p)
                    if w is not None:
                        w.setVisible(True)
                except Exception:
                    pass

            def _on_leave(sender, event):
                if int(event) == 2:
                    _dh_last_pack_buy['active'] = False
                    _dh_last_pack_buy['buying_again_at'] = 0.0
                    try:
                        if hasattr(disp, 'doReturnBtnClick') and callable(disp.doReturnBtnClick):
                            disp.doReturnBtnClick()
                        elif callable(getattr(disp, 'returnBtnCb', None)):
                            disp.returnBtnCb()
                            ui_mgr.leave_ui('UIItemDisplay')
                        else:
                            ui_mgr.leave_ui('UIItemDisplay')
                    except Exception:
                        try:
                            ui_mgr.leave_ui('UIItemDisplay')
                        except Exception:
                            pass
                    call_later(0.1, _dh_restore_mall_and_supply_ui)

            def _on_confirm(sender, event):
                if int(event) == 2:
                    try:
                        cb = getattr(disp, 'confirmBtnCb', None)
                        if callable(cb):
                            cb()
                            call_later(0.05, _dh_restore_mall_and_supply_ui)
                            call_later(0.3, _dh_restore_mall_and_supply_ui)
                        elif _dh_last_pack_buy.get('active') and int(_dh_last_pack_buy.get('goodID') or 0) > 0:
                            import time as _t
                            _dh_last_pack_buy['buying_again_at'] = _t.time()
                            ui_mgr.leave_ui('UIItemDisplay')
                            _dh_trigger_pack_buy_again()
                            call_later(1.2, _dh_buy_again_watchdog)
                        else:
                            ui_mgr.leave_ui('UIItemDisplay')
                            call_later(0.1, _dh_restore_mall_and_supply_ui)
                    except Exception:
                        try:
                            ui_mgr.leave_ui('UIItemDisplay')
                        except Exception:
                            pass
                        if not _dh_is_buying_again():
                            call_later(0.1, _dh_restore_mall_and_supply_ui)

            # 2. Wire returnBtn directly
            ret_btn = getattr(disp, 'returnBtn', None) or disp.get_widget_by_path('dlg/result_panel/anchor-upper-left/returnBtn')
            if ret_btn is not None:
                try:
                    ret_btn.setVisible(True)
                    ret_btn.setTouchEnabled(True)
                    ret_btn.addTouchEventListener(_on_leave)
                except Exception:
                    pass

            # 3. Wire confirmBtn directly
            conf_btn = getattr(disp, 'confirmBtn', None) or disp.get_widget_by_path('dlg/result_panel/anchor-bottom-right/confirmBtn')
            if conf_btn is not None:
                try:
                    conf_btn.setVisible(True)
                    conf_btn.setTouchEnabled(True)
                    conf_btn.addTouchEventListener(_on_confirm)
                except Exception:
                    pass
            if _dh_last_pack_buy.get('active'):
                try:
                    ct = getattr(disp, 'confirmBtnTxt', None)
                    if ct is not None and hasattr(ct, 'setString'):
                        ct.setString(str(_dh_last_pack_buy.get('confirmBtnTxt') or 'Buy Again'))
                except Exception:
                    pass

            # 4. Suppress duplicate "To Lobby" label
            try:
                txt = getattr(disp, 'returnBtnTxt', None)
                if txt is not None:
                    txt.setVisible(False)
            except Exception:
                pass

            # 5. Walk nodes to ensure all back/confirm/leave widgets are armed
            for path, node in walk_ui_nodes(disp, limit=400):
                p_low = path.lower()
                if 'return_btn_txt' in p_low:
                    try:
                        node.setVisible(False)
                    except Exception:
                        pass
                    continue
                if any(k in p_low for k in ('btn_back', 'btn_return', 'btnback', 'button_back', 'btn_close', 'returnbtn')):
                    if any(p_low.endswith(x) for x in ('_txt', '/text', '/txt', '_label')):
                        continue
                    try:
                        node.setVisible(True)
                        node.setTouchEnabled(True)
                        node.addTouchEventListener(_on_leave)
                    except Exception:
                        pass
                elif any(k in p_low for k in ('btn_confirm', 'btnconfirm', 'buyagain')):
                    if any(p_low.endswith(x) for x in ('_txt', '/text', '/txt', '_label')):
                        continue
                    try:
                        node.setVisible(True)
                        node.setTouchEnabled(True)
                        node.addTouchEventListener(_on_confirm)
                    except Exception:
                        pass

            # 6. Floating fail-safe BACK button on running scene
            try:
                cc = _dh_cc()
                if cc:
                    sc = cc.Director.getInstance().getRunningScene()
                    if sc and sc.getChildByName('dh_item_disp_fail_safe') is None:
                        win = cc.Director.getInstance().getWinSize()
                        lbl = cc.LabelTTF.create("< BACK", "Arial", 22)
                        lbl.setColor(cc.c3b(255, 255, 255))
                        lbl.setName('dh_item_disp_fail_safe')
                        lbl.setPosition(65.0, win.height - 40.0)
                        lbl.setTouchEnabled(True)
                        lbl.addTouchEventListener(_on_leave)
                        sc.addChild(lbl, 99999)
            except Exception:
                pass
    except Exception:
        pass


def _dh_remove_all_appearance_copies(player, item_id):
    """Safely remove ALL copies of an appearance item from player's package so no duplicates remain."""
    if not item_id:
        return 0
    try:
        pkg = getattr(player, 'dtsAppearancePackage', None)
        if pkg is None:
            return 0
        entries = pkg._getItemById(int(item_id)) or {}
        uuids = list(entries.keys())
        for u in uuids:
            try:
                player.onDelDtsAppearanceItem(int(item_id), u)
            except Exception:
                pass
        return len(uuids)
    except Exception:
        return 0


def _dh_clean_depot_duplicates(player=None):
    """Deduplicate cosmetics while preserving vehicle copies used by Workshop."""
    try:
        if player is None:
            import BigWorld
            player = BigWorld.player()
        if player is None:
            return 0
        import time as _time
        now = _time.time()
        if now - getattr(player, '_dh_last_depot_clean_time', 0.0) < 5.0:
            return 0
        player._dh_last_depot_clean_time = now

        pkg = getattr(player, 'dtsAppearancePackage', None)
        if pkg is None:
            return 0
        item_list = getattr(pkg, 'itemList', None)
        if not isinstance(item_list, dict):
            return 0

        cleaned = 0

        def _is_owned(iid):
            return (iid in item_list or str(iid) in item_list)

        def _wipe_id(iid):
            wiped = 0
            for k in (iid, str(iid), int(iid) if str(iid).isdigit() else iid):
                entries = item_list.get(k)
                if isinstance(entries, dict):
                    uuids = list(entries.keys())
                    for u in uuids:
                        try:
                            player.onDelDtsAppearanceItem(int(iid), u)
                        except Exception:
                            pass
                        entries.pop(u, None)
                        wiped += 1
                    item_list.pop(k, None)
            return wiped

        # 1. Group all keys by integer ID to resolve str vs int duplicates
        grouped = {}
        for k in list(item_list.keys()):
            try:
                iid = int(k)
            except Exception:
                continue
            grouped.setdefault(iid, []).append(k)

        for iid, keys in grouped.items():
            if iid in _VEHICLE_FAMILY_MAP:
                continue
            if len(keys) > 1:
                main_k = iid if iid in keys else keys[0]
                main_dict = item_list.setdefault(main_k, {})
                for other_k in keys:
                    if other_k != main_k:
                        other_dict = item_list.pop(other_k, {})
                        for u, udata in other_dict.items():
                            if u not in main_dict:
                                main_dict[u] = udata
                cleaned += 1

            main_k = keys[0] if keys[0] in item_list else iid
            entries = item_list.get(main_k)
            if isinstance(entries, dict):
                uuids = list(entries.keys())
                perm_uuids = []
                for u in uuids:
                    data = entries[u]
                    info = data.get('info') if isinstance(data, dict) else getattr(data, 'info', None)
                    ex_tm = 0
                    if isinstance(info, dict):
                        ex_tm = int(info.get('ex_tm') or 0)
                    elif hasattr(info, 'ex_tm'):
                        ex_tm = int(getattr(info, 'ex_tm', 0) or 0)
                    if ex_tm == 0:
                        perm_uuids.append(u)

                # Clamp permanent cosmetics strictly to 1 UUID
                if len(perm_uuids) > 1:
                    for extra_u in perm_uuids[1:]:
                        try:
                            player.onDelDtsAppearanceItem(iid, extra_u)
                        except Exception:
                            pass
                        entries.pop(extra_u, None)
                        cleaned += 1
                    perm_uuids = [perm_uuids[0]]

                # Clamp item count to 1 for permanent cosmetics
                if perm_uuids:
                    keep_u = perm_uuids[0]
                    keep_data = entries.get(keep_u)
                    num = 1
                    if isinstance(keep_data, dict):
                        num = int(keep_data.get('number') or 1)
                    elif hasattr(keep_data, 'number'):
                        num = int(getattr(keep_data, 'number', 1) or 1)
                    if num > 1:
                        try:
                            player.onUpdateDtsAppearanceItemNumber(iid, keep_u, 1)
                            cleaned += 1
                        except Exception:
                            pass

        # 2. Evolution consumption cleanup
        eq_vehicles = list(getattr(player, 'dtsVehicleAppearanceList', []) or [])
        evo_rules = [
            (140035, (140031,)),
            (140905, (140902,)),
            (140406, (140404, 140403)),
            (140404, (140403,)),
            (140013, (140010,)),
            (140024, (140021,)),
            (142030, (142029, 142028)),
            (142029, (142028,)),
            (140051, (140048,)),
            (140046, (140041,)),
            (140914, (140911,)),
            (140224, (140223, 140221)),
            (140223, (140221,)),
            (140061, (140056,)),
            (142003, (140241,)),
            (140077, (140076,)),
            (140214, (140211,)),
            (140205, (140202,)),
            (142006, (142005, 142004)),
            (142005, (142004,)),
            (142013, (142012, 142011)),
            (142012, (142011,)),
            (142008, (142007,)),
            (140237, (142007,)),
            (140074, (140073,)),
            (140065, (140064, 140062)),
            (140064, (140062,)),
        ]
        for target_id, src_ids in evo_rules:
            is_target_owned = _is_owned(target_id) or (target_id in eq_vehicles)
            if is_target_owned:
                if not _is_owned(target_id):
                    push_fn = globals().get('_push_one_item')
                    if callable(push_fn):
                        try:
                            push_fn(player, target_id, 1, 0, package='appearance')
                        except Exception:
                            pass

        # 3. Refresh appearance UIs if open
        if cleaned > 0:
            try:
                import Globals
                ui_mgr = getattr(Globals, 'uiMgr', None)
                if ui_mgr:
                    for ui_name in ('UIDtsAppearanceVehicle', 'UIDtsAppearanceVehicleCultivate2'):
                        scr = getattr(ui_mgr, ui_name, None)
                        if scr and getattr(scr, 'is_enter', False):
                            for mname in ('refreshAppearanceList',):
                                fn = getattr(scr, mname, None)
                                if callable(fn):
                                    try:
                                        fn()
                                    except Exception:
                                        pass
            except Exception:
                pass

        if cleaned:
            log('local-depot-cleaned', cleaned=cleaned)
        return cleaned
    except Exception:
        log_error('local-depot-clean-error')
        return 0


def _dh_rpc_appearance_cultivate_compound(player, *args, **kwargs):
    """Handle Workshop Tune: base.appearanceCultivateCompound(srcID, targetID, flag).
    Deducts src item and 1000 Gold, grants 1x target item, and calls onAppearanceCultivateCompound."""
    try:
        src_id = kwargs.get('src_id') if kwargs.get('src_id') is not None else (args[0] if len(args) > 0 else 0)
        target_id = kwargs.get('target_id') if kwargs.get('target_id') is not None else (args[1] if len(args) > 1 else 0)
        flag = kwargs.get('flag') if kwargs.get('flag') is not None else (args[2] if len(args) > 2 else 0)
        src_id = int(src_id or 0)
        target_id = int(target_id or 0)
    except Exception:
        log_error('local-cultivate-parse-error', args=safe(args))
        return None

    if not target_id:
        log('local-cultivate-no-target', src_id=src_id, target_id=target_id)
        return None

    try:
        import BigWorld
        BigWorld._dh_last_cultivate_target = target_id
    except Exception:
        pass

    log('local-cultivate-start', src_id=src_id, target_id=target_id)

    def on_upgrade_reply(reply):
        counts = reply.get('workshop_counts') if isinstance(reply, dict) else None
        if isinstance(counts, dict) and reply.get('ok') and str(target_id) in counts:
            _dh_apply_cultivate_reply(player, target_id, reply, counts)
        else:
            _dh_release_workshop_input()
            message = (reply.get('tip') or reply.get('message')) if isinstance(reply, dict) else None
            show_offline_tip(message or 'The server did not confirm this upgrade.', force=True)

    return ask_backend('appearanceCultivateCompound', [src_id, target_id, flag], kwargs, on_upgrade_reply)


def _dh_release_workshop_input():
    try:
        import Globals
        mgr = Globals.uiMgr
        workshop = getattr(mgr, 'UIDtsAppearanceVehicleCultivate2', None)
        if workshop is None or not getattr(workshop, 'is_enter', False):
            return
        for name in ('UIPayLoading', 'UICommonMask'):
            modal = getattr(mgr, name, None)
            if modal is not None and getattr(modal, 'is_enter', False):
                mgr.leave_ui(name)
        if hasattr(workshop, 'setTouchEnabled'):
            workshop.setTouchEnabled(True)
    except Exception:
        log_error('local-workshop-release-error')


def _dh_finish_workshop_upgrade(callback, target_id):
    try:
        callback(target_id)
    finally:
        _dh_release_workshop_input()


def _dh_sync_workshop_count(player, item_id, expected):
    package = getattr(player, 'dtsAppearancePackage', None)
    items = getattr(package, 'itemList', {})
    entries = items.get(item_id) or items.get(str(item_id)) or {}
    permanent = []
    for uuid, entry in entries.items():
        info = entry.get('info') if isinstance(entry, dict) else getattr(entry, 'info', None)
        expires = info.get('ex_tm') if isinstance(info, dict) else getattr(info, 'ex_tm', 0)
        if not expires:
            count = entry.get('number') if isinstance(entry, dict) else getattr(entry, 'number', 1)
            permanent.append((uuid, int(count or 1)))
    delta = int(expected) - sum(count for uuid, count in permanent)
    if delta > 0:
        _push_one_item(player, item_id, delta, 0, package='appearance')
    elif delta < 0:
        for uuid, count in reversed(permanent):
            take = min(count, -delta)
            if take == count:
                player.onDelDtsAppearanceItem(item_id, uuid)
            else:
                player.onUpdateDtsAppearanceItemNumber(item_id, uuid, count - take)
            delta += take
            if not delta:
                break


def _dh_apply_cultivate_reply(player, target_id, reply, counts):
    effective_src = next(int(item) for item in counts if int(item) != target_id)
    try:
        for item_id, count in counts.items():
            _dh_sync_workshop_count(player, int(item_id), count)
        _items_cache.update(gid=None, items=None)
        apply_server_props(player, reply.get('props'))
        log('local-workshop-counts-synced', counts=counts)
    except Exception:
        log_error('local-workshop-count-sync-error', target_id=target_id)

    # Equip the upgrade if its source was equipped.
    try:
        for prop in ('dtsVehicleAppearanceList', 'dtsWeaponAppearanceList', 'dtsBodyAppearanceList', 'dtsWearableAppearanceList'):
            lst = getattr(player, prop, None)
            matched_old = None
            if isinstance(lst, (list, tuple)):
                if effective_src in lst:
                    matched_old = effective_src
            if matched_old is not None:
                new_lst = [target_id if x == matched_old else x for x in lst]
                setattr(player, prop, new_lst)
                cb_name = 'onUpdate' + prop[0].upper() + prop[1:]
                cb = getattr(player, cb_name, None)
                if callable(cb):
                    try:
                        cb(new_lst)
                    except Exception:
                        pass
                shown_prop = 'dtsShow' + prop[3:] if prop.startswith('dts') else None
                if shown_prop and hasattr(player, shown_prop):
                    setattr(player, shown_prop, new_lst)
                try:
                    save_appearance(player)
                except Exception:
                    pass
    except Exception:
        log_error('local-cultivate-equip-update-error')

    # Deliver the Workshop callback after the backend confirms the upgrade.
    cb = getattr(player, 'onAppearanceCultivateCompound', None)
    if callable(cb):
        try:
            call_later(0.15, _dh_finish_workshop_upgrade, cb, target_id)
        except Exception:
            log_error('local-cultivate-cb-error', target_id=target_id)

    # 8. Refresh appearance UIs
    try:
        import Globals
        ui_mgr = getattr(Globals, 'uiMgr', None)
        if ui_mgr:
            for ui_name in ('UIDtsAppearanceVehicle', 'UIDtsAppearanceVehicleCultivate2', 'UIDtsAppearance'):
                scr = getattr(ui_mgr, ui_name, None)
                if scr and getattr(scr, 'is_enter', False):
                    for mname in ('refreshAppearanceList', 'refresh', 'refreshView'):
                        fn = getattr(scr, mname, None)
                        if callable(fn):
                            try:
                                fn()
                                break
                            except Exception:
                                pass
    except Exception:
        pass

    return True

try:
    RPC_HANDLERS['appearanceCultivateCompound'] = _dh_rpc_appearance_cultivate_compound
except Exception:
    pass


# ==========================================================================
# UNIVERSAL STORE PACK PITY (100x / N-x GUARANTEE) & BUY-AGAIN CONTINUATION
# ==========================================================================

_dh_pity_cache = {
    'loaded': False,
    'state': {},
    'supp_gl': None,
    'box_rules': {},
    'prob_parent_map': None
}


def _dh_pity_state_path():
    try:
        import os as _os
        base_dir = _os.path.dirname(CATALOG_PATH) if 'CATALOG_PATH' in globals() and CATALOG_PATH else 'local_update/logs'
        return _os.path.join(base_dir, 'pack_pity_state.json')
    except Exception:
        return 'local_update/logs/pack_pity_state.json'


def _dh_load_pity_state():
    if _dh_pity_cache['loaded']:
        return _dh_pity_cache['state']
    _dh_pity_cache['loaded'] = True
    try:
        import BigWorld
        mem = getattr(BigWorld, '_dh_pack_pity_state', None)
        if isinstance(mem, dict) and mem:
            _dh_pity_cache['state'] = mem
            return mem
    except Exception:
        pass
    try:
        import json as _json, os as _os
        p = _dh_pity_state_path()
        if _os.path.exists(p):
            with open(p, 'r') as f:
                data = _json.load(f)
            if isinstance(data, dict):
                _dh_pity_cache['state'] = data
    except Exception:
        pass
    try:
        import BigWorld
        BigWorld._dh_pack_pity_state = _dh_pity_cache['state']
    except Exception:
        pass
    return _dh_pity_cache['state']


def _dh_save_pity_state():
    try:
        import BigWorld
        BigWorld._dh_pack_pity_state = _dh_pity_cache['state']
    except Exception:
        pass
    try:
        import json as _json
        p = _dh_pity_state_path()
        with open(p, 'w') as f:
            _json.dump(_dh_pity_cache['state'], f)
    except Exception:
        pass


def _dh_extract_guarantee_rules(gl_obj):
    rules = []
    if not gl_obj:
        return rules
    for g in list(gl_obj):
        try:
            if isinstance(g, dict):
                gtype = str(g.get('__type__') or 'PropIDsGuarantee')
                gid = int(g.get('GUARANTEE_PROP_ID') or 0)
                cnt = int(g.get('PROP_GET_CNT') or 99)
                cset = [int(x) for x in (g.get('CHECK_PROP_SET') or []) if x]
                qual = int(g.get('QUALITY_CONDITION') or 0)
            else:
                gtype = str(getattr(g, '__type__', None) or type(g).__name__ or 'PropIDsGuarantee')
                gid = int(getattr(g, 'GUARANTEE_PROP_ID', 0) or 0)
                cnt = int(getattr(g, 'PROP_GET_CNT', 99) or 99)
                raw_cset = getattr(g, 'CHECK_PROP_SET', None) or []
                cset = [int(x) for x in list(raw_cset) if x]
                qual = int(getattr(g, 'QUALITY_CONDITION', 0) or 0)
            if gid > 0:
                if qual > 0 and 'Quality' not in gtype:
                    gtype = 'QualityGuarantee'
                rules.append({
                    'type': gtype,
                    'check_set': cset,
                    'guarantee_id': gid,
                    'cnt': max(1, cnt),
                    'quality': qual
                })
        except Exception:
            continue
    return rules


def _dh_get_supplement_gl_map(legacy):
    if _dh_pity_cache['supp_gl'] is not None:
        return _dh_pity_cache['supp_gl']
    smap = {}
    try:
        for _sid, srow in legacy.iterSupplementData():
            try:
                gl = _dh_extract_guarantee_rules(getattr(srow, 'GUARANTEE_LIST', None))
                if not gl:
                    continue
                for sl_entry in list(getattr(srow, 'SUPPLEMENT_LIST', None) or []):
                    pid = int(getattr(sl_entry, 'PROP_ID', 0) or 0)
                    if pid > 0 and pid not in smap:
                        smap[pid] = gl
            except Exception:
                continue
    except Exception:
        pass
    _dh_pity_cache['supp_gl'] = smap
    return smap


def _dh_get_prob_parent_map(legacy):
    if _dh_pity_cache['prob_parent_map'] is not None:
        return _dh_pity_cache['prob_parent_map']
    pmap = {}
    try:
        iter_fn = getattr(legacy, 'iterHallPropShowProbabilityData', None)
        if callable(iter_fn):
            for k, _row in iter_fn():
                try:
                    pk = int(k)
                    prow = legacy.getDtsHallPropData(pk)
                    pl = list(getattr( getattr(prow, 'PROP_TYPE', None), 'PROP_LIST', None) or [])
                    if pl and not hasattr(pl[0], 'PROBABILITY'):
                        child_id = int(pl[0])
                        pmap.setdefault(child_id, []).append(pk)
                except Exception:
                    continue
    except Exception:
        pass
    _dh_pity_cache['prob_parent_map'] = pmap
    return pmap


def _dh_get_prop_list_ids(legacy, prop_id):
    out = set()
    try:
        pt = getattr(legacy.getDtsHallPropData(int(prop_id)), 'PROP_TYPE', None)
        for entry in list(getattr(pt, 'PROP_LIST', None) or []):
            pid = getattr(entry, 'PROP_ID', None)
            if pid is not None:
                out.add(int(pid))
            elif isinstance(entry, (int, long)):
                out.add(int(entry))
    except Exception:
        pass
    return out


def _dh_get_display_model_ids(legacy, prop_id):
    out = []
    if not prop_id:
        return out
    try:
        pt = getattr(legacy.getDtsHallPropData(int(prop_id)), 'PROP_TYPE', None)
        for d in list(getattr(pt, 'DISPLAY_IN_MODEL', None) or []):
            for x in list(getattr(d, 'DISPLAY_PROP_LIST', None) or []):
                ix = int(x or 0)
                if ix > 0 and ix not in out:
                    out.append(ix)
    except Exception:
        pass
    return out


def _dh_get_box_guarantee_rules(box_id, parent_id, utils, legacy):
    box_id = int(box_id)
    parent_id = int(parent_id or 0)
    ckey = (box_id, parent_id)
    if ckey in _dh_pity_cache['box_rules']:
        return _dh_pity_cache['box_rules'][ckey]

    rules = []
    try:
        # 1. Direct GUARANTEE_LIST on box_id in DtsHallProp
        pt = getattr(legacy.getDtsHallPropData(box_id), 'PROP_TYPE', None)
        rules = _dh_extract_guarantee_rules(getattr(pt, 'GUARANTEE_LIST', None))

        # 2. Direct GUARANTEE_LIST on box_id in Supplement table
        supp_map = _dh_get_supplement_gl_map(legacy)
        if not rules and box_id in supp_map:
            rules = list(supp_map[box_id])

        # 3. Neighbor (box_id + 1 or box_id - 1) in DtsHallProp or Supplement matching PROP_LIST or DISPLAY_PROP_LIST
        if not rules:
            box_pids = _dh_get_prop_list_ids(legacy, box_id)
            disp_ids = set(_dh_get_display_model_ids(legacy, parent_id) + _dh_get_display_model_ids(legacy, box_id))
            for cand in (box_id + 1, box_id - 1):
                cand_rules = supp_map.get(cand)
                if not cand_rules:
                    cpt = getattr(legacy.getDtsHallPropData(cand), 'PROP_TYPE', None)
                    cand_rules = _dh_extract_guarantee_rules(getattr(cpt, 'GUARANTEE_LIST', None))
                if not cand_rules:
                    continue
                cand_pids = _dh_get_prop_list_ids(legacy, cand)
                rule_ids = set()
                for r in cand_rules:
                    rule_ids.update(r.get('check_set') or [])
                    if r.get('guarantee_id'):
                        rule_ids.add(int(r['guarantee_id']))
                if (box_pids and cand_pids and box_pids == cand_pids) or (disp_ids and (rule_ids & disp_ids)) or (box_pids and (rule_ids & box_pids)):
                    rules = list(cand_rules)
                    break
            if not rules:
                for cand in (box_id + 1, box_id - 1):
                    if cand in supp_map:
                        rules = list(supp_map[cand])
                        break

        # 4. Universal fallback synthesis from HallPropShowProbability DESC + DISPLAY_IN_MODEL + PROP_LIST
        if not rules:
            desc = ''
            prob_getter = getattr(legacy, 'getHallPropShowProbabilityData', None)
            cand_parents = [parent_id, box_id] if parent_id else [box_id]
            for extra_p in _dh_get_prob_parent_map(legacy).get(box_id, []):
                if extra_p not in cand_parents:
                    cand_parents.append(extra_p)
            if callable(prob_getter):
                for pid_cand in cand_parents:
                    if not pid_cand:
                        continue
                    try:
                        p_row = prob_getter(int(pid_cand))
                        if p_row is not None and getattr(p_row, 'DESC', None):
                            desc = str(getattr(p_row, 'DESC'))
                            break
                    except Exception:
                        continue
            import re as _re
            m = _re.findall(r'(?:draw|open)\s*[x\xd7]?\s*(\d+)\s*[x\xd7]?', desc, _re.I)
            thresh = int(m[-1]) if m else 100
            if thresh <= 1:
                thresh = 100

            featured = []
            for p_cand in cand_parents:
                for did in _dh_get_display_model_ids(legacy, p_cand):
                    if did not in featured:
                        featured.append(did)

            pl = list(getattr(pt, 'PROP_LIST', None) or [])
            total_w = 0
            weighted_entries = []
            for entry in pl:
                try:
                    epid = int(getattr(entry, 'PROP_ID', 0) or 0)
                    ew = max(0, int(getattr(entry, 'PROBABILITY', 0) or 0))
                    if epid > 0:
                        total_w += ew
                        weighted_entries.append((epid, ew))
                except Exception:
                    continue

            rare_from_pool = []
            for epid, ew in weighted_entries:
                if (290000 <= epid < 300000) or epid in (360000, 300001, 300002, 300012):
                    continue
                is_curr = False
                try:
                    is_curr = bool(utils.isDtsHallCurrency(epid))
                except Exception:
                    pass
                if is_curr:
                    continue
                qual = 0
                try:
                    qual = int(utils.getDtsHallPropQuality(epid) or 0)
                except Exception:
                    pass
                if (total_w > 0 and ew * 100 <= 15 * total_w) or qual >= 4:
                    if epid not in rare_from_pool:
                        rare_from_pool.append(epid)

            target_ids = rare_from_pool if rare_from_pool else featured
            for tid in target_ids:
                rules.append({
                    'type': 'PropIDsGuarantee',
                    'check_set': [int(tid)],
                    'guarantee_id': int(tid),
                    'cnt': max(1, thresh - 1),
                    'quality': 0
                })
    except Exception:
        log_error('local-pack-pity-rules-error', box_id=box_id)

    _dh_pity_cache['box_rules'][ckey] = rules
    return rules


def _dh_open_hall_prop_with_pity(prop_id, depth=0, rand=None, parent_id=None, prefer_unpulled=None):
    """Universal replacement for open_hall_prop with full Guarantee / Pity tracking across all Store Packs."""
    utils, legacy = hall_prop_tables()
    if utils is None or depth >= HALL_PROP_DEPTH:
        return [prop_id]
    try:
        prop_id = int(prop_id)
        kind = utils.getDtsHallPropType(prop_id)
        contents = list(legacy.getDtsHallPropData(prop_id).PROP_TYPE.PROP_LIST)
    except Exception:
        return [prop_id]

    if kind == 'GiftBag':
        opened = []
        for content in contents:
            opened.extend(_dh_open_hall_prop_with_pity(int(content), depth + 1, rand, parent_id=prop_id))
        if depth == 0:
            _dh_save_pity_state()
        return opened

    if kind == 'RandomItem':
        # If this is a guarantee sub-box ('打包') and the caller specified unpulled items, filter to them first
        if prefer_unpulled:
            filtered = []
            for entry in contents:
                try:
                    if int(entry.PROP_ID) in prefer_unpulled:
                        filtered.append(entry)
                except Exception:
                    continue
            if filtered:
                contents = filtered

        rules = _dh_get_box_guarantee_rules(prop_id, parent_id, utils, legacy) if not prefer_unpulled else []
        if not rules:
            rolled = roll_random_item(contents, rand)
            return _dh_open_hall_prop_with_pity(rolled, depth + 1, rand, parent_id=prop_id) if rolled is not None else []

        pstate = _dh_load_pity_state()
        bkey = str(prop_id)
        bstate = pstate.get(bkey)
        if not isinstance(bstate, dict) or not isinstance(bstate.get('misses'), list) or len(bstate['misses']) != len(rules):
            bstate = {'misses': [0] * len(rules), 'total': 0}
            pstate[bkey] = bstate

        misses = bstate['misses']
        bstate['total'] = int(bstate.get('total') or 0) + 1

        # Count how many single-item rules sharing the same cnt are currently unobtained (misses > 0)
        same_cnt_unobtained = {}
        unpulled_items = set()
        for idx, r in enumerate(rules):
            cset = r.get('check_set') or []
            if len(cset) == 1 and misses[idx] > 0:
                rcnt = int(r.get('cnt') or 99)
                same_cnt_unobtained[rcnt] = same_cnt_unobtained.get(rcnt, 0) + 1
                unpulled_items.add(int(cset[0]))

        triggered_idx = None
        best_priority = None
        for idx, r in enumerate(rules):
            rcnt = int(r.get('cnt') or 99)
            cset = r.get('check_set') or []
            stagger = max(0, same_cnt_unobtained.get(rcnt, 1) - 1) if len(cset) == 1 else 0
            if misses[idx] + stagger >= rcnt:
                # Prefer more specific rules (smaller check_set) and higher threshold rules first
                prio = (-len(cset) if cset else 0, rcnt, misses[idx])
                if best_priority is None or prio > best_priority:
                    best_priority = prio
                    triggered_idx = idx

        if triggered_idx is not None:
            tr = rules[triggered_idx]
            rolled = int(tr['guarantee_id'])
            leaf_ids = _dh_open_hall_prop_with_pity(
                rolled, depth + 1, rand, parent_id=prop_id,
                prefer_unpulled=unpulled_items if unpulled_items else None
            )
            log('local-pack-pity-triggered', box_id=prop_id, parent_id=parent_id,
                guarantee_id=rolled, leaf_ids=leaf_ids, misses=misses[triggered_idx],
                threshold=int(tr.get('cnt') or 99) + 1, total_draws=bstate['total'])
        else:
            rolled = roll_random_item(contents, rand)
            leaf_ids = _dh_open_hall_prop_with_pity(rolled, depth + 1, rand, parent_id=prop_id) if rolled is not None else []

        obtained = set([int(rolled)] if rolled is not None else [])
        for lid in leaf_ids:
            try:
                obtained.add(int(lid))
            except Exception:
                pass

        for idx, r in enumerate(rules):
            rtype = str(r.get('type') or 'PropIDsGuarantee')
            gid = int(r.get('guarantee_id') or 0)
            hit = False
            if 'Quality' in rtype and int(r.get('quality') or 0) > 0:
                min_q = int(r['quality'])
                if gid in obtained:
                    hit = True
                else:
                    for lid in leaf_ids:
                        try:
                            if int(utils.getDtsHallPropQuality(int(lid)) or 0) >= min_q:
                                hit = True
                                break
                        except Exception:
                            continue
            else:
                cset = set(int(x) for x in (r.get('check_set') or []))
                if gid > 0:
                    cset.add(gid)
                if obtained & cset:
                    hit = True
            if hit:
                misses[idx] = 0
            else:
                misses[idx] = int(misses[idx]) + 1

        if depth == 0:
            _dh_save_pity_state()
        return leaf_ids

    return [prop_id]


open_hall_prop = _dh_open_hall_prop_with_pity


