# --- m73: ROS Redemption seasons (server_ext/season.py).  The server sends rlSeason {id, name, starts, ends, client, offset}:
# our Season N runs in the game's season slot N + offset (its tier tables end at its season 17), so the ladder is
# pointed at that slot, its "Season 17" labels read "Season 1", and the official seasons before ours are hidden.
_DH_DEFAULT_SEASON = {'id': 1, 'name': 'Season 1', 'client': 17, 'offset': 16, 'starts': 0, 'ends': 0}
_dh_season = {'info': dict(_DH_DEFAULT_SEASON)}
_DH_SEASON_LABEL = __import__('re').compile(r'\bSeason\s*(\d+)\b', __import__('re').I)


def _dh_ladder_module():
    module = _dh_sys.modules.get('ui.UIRankLadder')
    if module is None:
        try:
            module = __import__('ui.UIRankLadder', fromlist=['RankInfoHolder'])
        except Exception:
            return None
    return module


def _dh_point_ladder():
    info = _dh_season['info']
    module = _dh_ladder_module()
    if not info or module is None:
        return False
    client, offset = int(info['client']), int(info['offset'])
    holder = module.RankInfoHolder()
    if int(getattr(holder, 'cur_season_id', 0) or 0) != client:
        holder.set_cur_season(client)
        holder.cur_select_season = client
    holder.set_max_season(client)
    holder.set_min_season(offset + 1)
    try:
        module.CelebrityHolder().set_max_season(client)
    except Exception:
        pass
    return True


def _dh_patch_season_id():
    try:
        import utils
        utils.getCurrentSeasonID = lambda *a, **k: 1
    except Exception:
        pass
    try:
        import rank_utils
        if hasattr(rank_utils, 'getCurrentSeasonID'):
            rank_utils.getCurrentSeasonID = lambda *a, **k: 1
    except Exception:
        pass


def _dh_fix_record_panel(rec):
    if rec is None:
        return
    try:
        btn = getattr(rec, 'showModeSecondary', None)
        if btn is not None:
            for s_name in ('setTitleText', 'setString', 'setText'):
                if hasattr(btn, s_name):
                    try: getattr(btn, s_name)('Season 1')
                    except Exception: pass
            if hasattr(btn, 'getTitleRenderer'):
                try:
                    tr = btn.getTitleRenderer()
                    if tr is not None and hasattr(tr, 'setString'):
                        tr.setString('Season 1')
                except Exception:
                    pass
            if hasattr(btn, 'getChildren'):
                try:
                    for ch in list(btn.getChildren() or []):
                        for s_name in ('setTitleText', 'setString', 'setText'):
                            if hasattr(ch, s_name):
                                try: getattr(ch, s_name)('Season 1')
                                except Exception: pass
                except Exception:
                    pass

        choose = getattr(rec, 'modeChooseSecondary', None)
        if choose is not None:
            if hasattr(choose, 'getChildren'):
                try:
                    items = list(choose.getChildren() or [])
                    for idx, item in enumerate(items):
                        if idx == 0:
                            for s_name in ('setTitleText', 'setString', 'setText'):
                                if hasattr(item, s_name):
                                    try: getattr(item, s_name)('Season 1')
                                    except Exception: pass
                            if hasattr(item, 'getTitleRenderer'):
                                try:
                                    tr = item.getTitleRenderer()
                                    if tr is not None and hasattr(tr, 'setString'):
                                        tr.setString('Season 1')
                                except Exception:
                                    pass
                        for g in ('getTitleText', 'getString', 'getText', 'getStringValue'):
                            if hasattr(item, g):
                                try:
                                    t = getattr(item, g)()
                                    if t and '17' in str(t):
                                        for s_name in ('setTitleText', 'setString', 'setText'):
                                            if hasattr(item, s_name):
                                                try: getattr(item, s_name)('Season 1')
                                                except Exception: pass
                                        if hasattr(item, 'getTitleRenderer'):
                                            try:
                                                tr = item.getTitleRenderer()
                                                if tr is not None and hasattr(tr, 'setString'):
                                                    tr.setString('Season 1')
                                            except Exception:
                                                pass
                                except Exception:
                                    pass
                        if hasattr(item, 'getChildren'):
                            try:
                                for ch in list(item.getChildren() or []):
                                    for g in ('getTitleText', 'getString', 'getText'):
                                        if hasattr(ch, g):
                                            try:
                                                t = getattr(ch, g)()
                                                if t and '17' in str(t):
                                                    for s_name in ('setTitleText', 'setString', 'setText'):
                                                        if hasattr(ch, s_name):
                                                            try: getattr(ch, s_name)('Season 1')
                                                            except Exception: pass
                                            except Exception:
                                                pass
                            except Exception:
                                pass
                except Exception:
                    pass
    except Exception:
        pass


def _dh_relabel_seasons(ui):
    """'Season 17' -> 'Season 1' on ladder, stats, and profile screens; older official seasons are hidden."""
    if ui is None:
        return 0
    _dh_patch_season_id()
    import re

    def _fix_node_text_safe(curr):
        if curr is None:
            return False
        changed = False
        targets = []
        for g_name, s_name in (('getTitleText', 'setTitleText'),
                               ('getString', 'setString'),
                               ('getText', 'setText'),
                               ('getStringValue', 'setStringValue')):
            if hasattr(curr, g_name) and hasattr(curr, s_name):
                try:
                    val = getattr(curr, g_name)()
                    if val:
                        targets.append((getattr(curr, g_name), getattr(curr, s_name)))
                except Exception:
                    pass

        if hasattr(curr, 'getTitleRenderer'):
            try:
                tr = curr.getTitleRenderer()
                if tr is not None:
                    for g_name, s_name in (('getString', 'setString'), ('getText', 'setText')):
                        if hasattr(tr, g_name) and hasattr(tr, s_name):
                            try:
                                val = getattr(tr, g_name)()
                                if val:
                                    targets.append((getattr(tr, g_name), getattr(tr, s_name)))
                            except Exception:
                                pass
            except Exception:
                pass

        for getter, setter in targets:
            try:
                raw = getter()
                if raw is not None:
                    is_uni = isinstance(raw, unicode)
                    s = raw if is_uni else str(raw).decode('utf-8', 'ignore')
                    if '17' in s:
                        s2 = re.sub(r'\bSeason\s*17\b', u'Season 1', s)
                        s2 = re.sub(r'Season17', u'Season 1', s2)
                        s2 = re.sub(r'\bS17\b', u'S1', s2)
                        if u'17' in s2 and (u'Season' in s2 or u'S' in s2):
                            s2 = s2.replace(u'17', u'1')
                        val_str = s2.encode('utf-8')
                        try:
                            setter(val_str)
                        except Exception:
                            try:
                                setter(s2)
                            except Exception:
                                pass
                        changed = True
                    elif re.search(r'\bSeason\s*(1[0-6]|[2-9])\b', s):
                        parent = curr.getParent() if hasattr(curr, 'getParent') else None
                        if parent is not None and hasattr(parent, 'getChildren') and len(list(parent.getChildren())) <= 4:
                            parent.setVisible(False)
                        elif hasattr(curr, 'setVisible'):
                            curr.setVisible(False)
                        changed = True
            except Exception:
                pass
        return changed

    def _sweep_node(root_node):
        if root_node is None:
            return
        stk = [root_node]
        sn = set()
        while stk:
            c = stk.pop()
            if c is None:
                continue
            cid = id(c)
            if cid in sn:
                continue
            sn.add(cid)
            if hasattr(c, 'getChildren'):
                try:
                    for ch in list(c.getChildren() or []):
                        stk.append(ch)
                except Exception:
                    pass
            if hasattr(c, 'getTitleRenderer'):
                try:
                    tr = c.getTitleRenderer()
                    if tr:
                        stk.append(tr)
                except Exception:
                    pass
            _fix_node_text_safe(c)

    # Fast-path for UIMeetMainPage
    try:
        mt = getattr(ui, '_mainTab', None) or ui
        rec = None
        if hasattr(mt, 'getTabPanel'):
            rec = mt.getTabPanel('record')
        if rec is None:
            for attr in ('battleGroundRecordPanel', 'recordPanel', '_battleGroundRecordPanel'):
                rec = getattr(ui, attr, None)
                if rec is not None:
                    break
        if rec is not None:
            _dh_fix_record_panel(rec)
    except Exception:
        pass

    changed = 0
    seen = set()
    stack = [ui]
    limit = 500
    while stack and len(seen) < limit:
        curr = stack.pop()
        if curr is None:
            continue
        cid = id(curr)
        if cid in seen:
            continue
        seen.add(cid)

        # 1. Traverse Cocos2d-x children
        if hasattr(curr, 'getChildren'):
            try:
                ch = curr.getChildren()
                if ch:
                    stack.extend(list(ch))
            except Exception:
                pass

        # 2. Check title renderer
        if hasattr(curr, 'getTitleRenderer'):
            try:
                tr = curr.getTitleRenderer()
                if tr:
                    stack.append(tr)
            except Exception:
                pass

        # 3. Traverse Python wrapper attributes
        if hasattr(curr, '__dict__'):
            try:
                for k, v in curr.__dict__.items():
                    if v is not None:
                        if hasattr(v, 'getChildren') or hasattr(v, '__dict__'):
                            stack.append(v)
                        elif isinstance(v, (list, tuple)):
                            stack.extend(list(v))
                        elif isinstance(v, dict):
                            stack.extend(list(v.values()))
            except Exception:
                pass

        # 4. Traverse UITabView panels if present
        if hasattr(curr, 'getTabPanel'):
            for tab in ('record', 'mainpage', 'peiwan', 'intimate', 'credit', 'vip', 'marriage'):
                try:
                    p = curr.getTabPanel(tab)
                    if p is not None:
                        stack.append(p)
                except Exception:
                    pass

        # 5. Check text modification on current node
        if _fix_node_text_safe(curr):
            changed += 1

    return changed


def _dh_install_season_screens():
    module = _dh_ladder_module()
    done = []
    if module is not None:
        targets = {'UILadder': ('on_enter', '_update_season_panel', '_update_season_id', 'OnChoseSeason',
                                'onSeasonPanelSelect', '_update_self_ladder', 'set_right_panel'),
                   'UIRankLadder': ('on_enter', '_update_season_num', 'onChoseSeasonEvent', '_update_rank_list')}
        for cls_name, methods in targets.items():
            cls = getattr(module, cls_name, None)
            if cls is None:
                continue
            for name in methods:
                inner = cls.__dict__.get(name)
                if inner is None or getattr(inner, '_dh_season', False):
                    continue

                def make(inner, name):
                    def wrapped(self, *args, **kwargs):
                        if name == 'on_enter':
                            try:
                                _dh_point_ladder()
                            except Exception:
                                log_error('local-season-point-error')
                        result = inner(self, *args, **kwargs)
                        try:
                            _dh_relabel_seasons(self)
                        except Exception:
                            log_error('local-season-label-error', method=name)
                        return result
                    wrapped._dh_season = True
                    wrapped._dh_inner = inner
                    return wrapped
                setattr(cls, name, make(inner, name))
                done.append('%s.%s' % (cls_name, name))

    # Hook UIBattleGroundRecordPanel directly
    try:
        meet_mod = _dh_sys.modules.get('ui.UIMeetMainPage')
        if meet_mod is None:
            try:
                meet_mod = __import__('ui.UIMeetMainPage', fromlist=['UIBattleGroundRecordPanel', 'UIMeetMainPage'])
            except Exception:
                meet_mod = None
        if meet_mod is not None:
            bgrp = getattr(meet_mod, 'UIBattleGroundRecordPanel', None)
            if bgrp is not None and not getattr(bgrp, '_dh_season_hooked', False):
                bgrp._dh_season_hooked = True

                for method_name in ('on_enter', '_get_ui', 'onShowModeSecondaryClick',
                                    '_setModeSecondaryChoose', 'onGameModeSecondaryClick',
                                    'onGetRecordData', 'onGetBaseInfo', 'responseToClickGameMode'):
                    orig_fn = getattr(bgrp, method_name, None)
                    if orig_fn:
                        def make_bgrp_wrapper(inner, m_name):
                            def _wrapped_bgrp(self, *args, **kwargs):
                                res = inner(self, *args, **kwargs)
                                try:
                                    _dh_fix_record_panel(self)
                                    _dh_relabel_seasons(self)
                                except Exception:
                                    pass
                                return res
                            return _wrapped_bgrp
                        setattr(bgrp, method_name, make_bgrp_wrapper(orig_fn, method_name))
                done.append('UIBattleGroundRecordPanel')
    except Exception:
        pass

    return done


try:
    _dh_install_season_screens()
except Exception:
    pass


