# --- m83: the Ranked card on Modes (UIModesList) is the picture SubmodeDescData[4].SHOW_IMG
# (ui/images/advertiseimages/img_paiweisai.png, ui.npk entry 272x415) with the game's season painted in: "S17",
# "Season 17 in Progress".  The patch carries one card per ROS Redemption season (hot/brand/dh_rank_s<N>.jpg, N = 1..30,
# made by hot/brand_tools/rank_cards.py from the game's own card) and points the row at the current season's card
# whenever rlSeason arrives, so a season rollover changes the card by itself.  A season without a card, or an
# engine that cannot see the file, keeps the game's own picture.
_DH_RANK_CARD_ROWS = (4,)
_DH_RANK_CARD_MAX = 30
_dh_rank_card = globals().get('_dh_rank_card') or {'original': {}, 'shown': None}


def _dh_mode_desc_rows():
    from shared.lib.gametoolslib import properties
    rows = {}
    for key, row in properties.iterSubmodeDescData():
        if key in _DH_RANK_CARD_ROWS:
            rows[key] = row
    return rows


def _dh_apply_rank_card(info, attempt):
    season = int((info or {}).get('id') or 0)
    name = 'dh_rank_s%d.jpg' % season
    target = None
    if 1 <= season <= _DH_RANK_CARD_MAX:
        # at load this runs before _DH_BRAND_ASSETS (the end of the patch) exists and before the files are written
        target = _dh_art_file(name)
        if target is None and attempt < 8 and _dh_art['errors'] <= 6:
            call_later(2.0, _dh_apply_rank_card, info, attempt + 1)
            return None
    changed = []
    for key, row in _dh_mode_desc_rows().items():
        original = _dh_rank_card['original'].setdefault(key, getattr(row, 'SHOW_IMG', None))
        wanted = target or original
        if wanted and getattr(row, 'SHOW_IMG', None) != wanted:
            setattr(row, 'SHOW_IMG', wanted)
            changed.append(key)
    _dh_rank_card['shown'] = target
    refreshed = _dh_refresh_mode_cards() if changed else None
    log('local-rank-card', season=season, card=target, changed=changed, attempt=attempt, refreshed=refreshed)
    return target


def _dh_refresh_mode_cards():
    """Modes keeps its cards once built: redraw them with the game's own UIModesList.__reorderTypePanels()
    (checked live on 2026-10-20: the cached panel shows the new card at once)."""
    try:
        import Globals
        ui = (getattr(Globals.uiMgr, '____all_ui__', {}) or {}).get('UISubModesEnter')
        panel = (getattr(ui, 'panels', {}) or {}).get('types') if ui is not None else None
        method = getattr(panel, '_UIModesList__reorderTypePanels', None) if panel is not None else None
        if method is None:
            return False
        method()
        return True
    except Exception:
        log_error('local-rank-card-refresh-error')
        return False


_dh_season_props_inner = apply_server_props


# --- m78: game texts from the server (server_ext/client_texts.py, console -> Texts).  rlTexts = {version, rules:
# [{find, replace, regex}], season: {game, ours}}: every English text of the translation table and the shop's names /
# descriptions is rewritten by the rules ('S17' -> 'S1' follows the season by itself).  Applied when the version
# changes; the original of each changed text is kept, so a rule taken away puts the old text back.
_dh_texts = {'version': None, 'trans': {}, 'mall': {}}


def _dh_text_subs(body):
    import re
    subs = []
    season = body.get('season') if isinstance(body.get('season'), dict) else None
    if season and int(season.get('game') or 0) and int(season.get('game')) != int(season.get('ours') or 0):
        game, ours = int(season['game']), int(season['ours'])
        subs.append((re.compile(r'\bS ?%d\b' % game), u'S%d' % ours))
        subs.append((re.compile(r'\bSeason ?%d\b' % game), u'Season %d' % ours))
    def text(value):
        # the props arrive as UTF-8 bytes on this Python 2 client: a full-width bracket must be one character
        return value.decode('utf-8') if isinstance(value, str) else (value or u'')
    for rule in body.get('rules') or []:
        try:
            find = text(rule.get('find'))
            pattern = re.compile(find if rule.get('regex') else u'(?<!\\w)%s(?!\\w)' % re.escape(find))
            subs.append((pattern, text(rule.get('replace'))))
        except Exception:
            log_error('local-texts-rule-error', find=safe(rule.get('find')))
    return subs


_DH_CJK = __import__('re').compile(u'[\u3040-\u30ff\u3400-\u9fff]')


def _dh_rewrite(text, subs):
    raw = isinstance(text, str)
    try:
        value = text.decode('utf-8') if raw else text
    except Exception:
        return text
    if _DH_CJK.search(value):
        return text         # m79: a Chinese / Japanese text is a lookup key (internal names): never rewritten
    new = value
    for pattern, repl in subs:
        new = pattern.sub(repl, new)
    if new == value:
        return text
    return new.encode('utf-8') if raw else new


def _dh_apply_texts(body):
    if not isinstance(body, dict) or body.get('version') == _dh_texts['version']:
        return None
    mod = _dh_sys.modules.get('international_data.translate_properties.translate_properties_en')
    table = getattr(mod, 'translate_info', None)
    lp = _dh_sys.modules.get('shared.lib.gametoolslib.properties')
    # put back what the last rules changed
    if isinstance(table, dict):
        for key, value in _dh_texts['trans'].items():
            table[key] = value
    for (row, attr), value in _dh_texts['mall'].items():
        try:
            setattr(row, attr, value)
        except Exception:
            pass
    _dh_texts['trans'], _dh_texts['mall'] = {}, {}
    subs = _dh_text_subs(body)
    changed = 0
    if subs and isinstance(table, dict):
        for key, value in table.items():
            if isinstance(value, basestring):
                new = _dh_rewrite(value, subs)
                if new is not value:
                    _dh_texts['trans'][key] = value
                    table[key] = new
                    changed += 1
    mall = 0
    rows = []
    if subs and lp is not None:
        # the shop's goods and the items themselves (DtsHallPropData NAME holds English: 'S17 Store - Champion Display')
        for table_name in ('iterMallData', 'iterDtsHallPropData'):
            try:
                rows.extend(getattr(lp, table_name)())
            except Exception:
                log_error('local-texts-table-error', table=table_name)
        for entry in rows:
            row = entry[1] if isinstance(entry, tuple) and len(entry) == 2 else entry
            for attr in ('NAME', 'DESC'):
                value = getattr(row, attr, None)
                if isinstance(value, basestring):
                    new = _dh_rewrite(value, subs)
                    if new is not value:
                        try:
                            setattr(row, attr, new)
                            _dh_texts['mall'][(row, attr)] = value
                            mall += 1
                        except Exception:
                            pass
    _dh_texts['version'] = body.get('version')
    log('local-texts', version=body.get('version'), rules=len(body.get('rules') or []), texts=changed, shop=mall)
    return changed + mall


# --- m82: the Exchange dialog's rates come from the server (server_ext/currency_exchange.py, console -> Currencies):
# rlExchange = {rates: {currency id: units per diamond}}.  They replace the game's own diamond row
# (currency_utils.exchangeRateDict[2]), so the dialog shows what the server charges, and a currency the server
# switches on becomes exchangeable; one it switches off is no longer offered.
_DH_DIAMOND = 2


def _dh_apply_exchange(body):
    cu = _dh_sys.modules.get('currency_utils')
    rates = body.get('rates') if isinstance(body, dict) else None
    if cu is None or not isinstance(rates, dict):
        return False
    try:
        cu.getCurrencyExchangeRateDict(_DH_DIAMOND)          # builds the table once
    except Exception:
        pass
    table = getattr(cu, 'exchangeRateDict', None)
    if not isinstance(table, dict):
        return False
    row = {}
    for key, value in rates.items():
        try:
            row[int(key)] = float(value)
        except Exception:
            continue
    table[_DH_DIAMOND] = row
    log('local-exchange-rates', rates=dict((str(k), v) for k, v in row.items()))
    apply_gold = globals().get('_dh_g2d_apply')
    if callable(apply_gold):
        apply_gold(body)
    return True


def _dh_apply_carnival(player, data):
    """m75 Lucky Carnival (server_ext/lucky_carnival.py): the wheel's state into the game's own props
    (iLuckyCarnival.refreshLuckyCarnivalData also builds the prize value map), so the closed-carnival gate opens."""
    if not isinstance(data, dict) or 'luckyRoundState' not in data:
        return False
    if not hasattr(player, 'refreshLuckyCarnivalData'):
        return False        # m121: the season props also reach the battle avatar, which has no carnival (log audit)
    import Globals
    for name in ('UILuckyCarnivalAdvance', 'UILuckyCarnivalSuper', 'UILuckyCarnival'):
        screen = getattr(Globals.uiMgr, name, None)
        if screen is not None and getattr(screen, 'is_enter', False):
            return False        # open: its own draw answers move the wheel (a refresh here broke the draw's animation)
    player.refreshLuckyCarnivalData(dict(data))
    log('local-carnival', state=data.get('luckyRoundState'), round=data.get('luckyRoundNo'),
        prizes=len(data.get('luckyRoundGift') or []), won=len(data.get('luckyRoundGotIndex') or []))
    return True


_dh_carnival_prize_seen = globals().get('_dh_carnival_prize_seen') or {}


def _dh_apply_carnival_prize(player, info):
    """m131 (2026-11-06): a Lucky Carnival draw grants its hall prop server-side (server_ext/lucky_carnival.py); the
    draw's wheel reply carried no depot delta, so a won skin only showed after relog.  The reply now sends
    rlCarnivalPrize {id, count, draw}; push that one prop into the depot store live with the game's own
    _push_one_item (m119-guarded: a PC-unknown id is skipped, matching the server's add_item skip, so the two stay in
    step).  Fail-safe: a bad id, a missing push function, the battle avatar (no depot), or any error degrades to the
    old behaviour - the authoritative depot still arrives at the next lobby entry, so the item is never lost and the
    push can never show one the player does not own."""
    if not isinstance(info, dict):
        return False
    try:
        item_id = int(info.get('id') or 0)
    except Exception:
        return False
    if item_id <= 0:
        return False
    if not hasattr(player, 'refreshLuckyCarnivalData'):
        return False        # m121: reply props can also land on the battle avatar, which has no depot
    draw_no = info.get('draw')
    if draw_no is not None and _dh_carnival_prize_seen.get('draw') == draw_no \
            and _dh_carnival_prize_seen.get('id') == item_id:
        return False        # the same draw reply re-applied: push the prize once
    _dh_carnival_prize_seen['draw'] = draw_no
    _dh_carnival_prize_seen['id'] = item_id
    push = globals().get('_push_one_item')
    if not callable(push):
        return False
    try:
        count = int(info.get('count') or 1)
    except Exception:
        count = 1
    try:
        push(player, item_id, count, 0)          # expires 0: the server granted it with days=0 (permanent)
        log('local-carnival-prize-push', item=item_id, count=count)
        return True
    except Exception:
        log_error('local-carnival-prize-push-error', item=item_id)
        return False


def _dh_apply_season_props(player, props, refresh=True):
    result = _dh_season_props_inner(player, props, refresh)
    try:
        if isinstance(props, dict) and isinstance(props.get('rlSeason'), dict):
            _dh_apply_season(player, props['rlSeason'])
    except Exception:
        log_error('local-season-apply-error')
    try:
        if isinstance(props, dict) and isinstance(props.get('rlCarnival'), dict):
            _dh_apply_carnival(player, props['rlCarnival'])
    except Exception:
        log_error('local-carnival-apply-error')
    try:
        if isinstance(props, dict) and isinstance(props.get('rlCarnivalPrize'), dict):
            _dh_apply_carnival_prize(player, props['rlCarnivalPrize'])
    except Exception:
        log_error('local-carnival-prize-apply-error')
    try:
        if isinstance(props, dict) and isinstance(props.get('rlTexts'), dict):
            _dh_apply_texts(props['rlTexts'])
    except Exception:
        log_error('local-texts-apply-error')
    try:
        if isinstance(props, dict) and isinstance(props.get('rlExchange'), dict):
            _dh_apply_exchange(props['rlExchange'])
    except Exception:
        log_error('local-exchange-apply-error')
    return result


