# --- m81: Lucky Carnival screen without what this server does not run: the diamond jackpot (the "POT", its winners
# ticker with the official game's placeholder name, the pot buff's explanation) and the "first draw free for
# weekly/monthly pass holders" banner (no passes are sold).  The wheel, draws and weekly rewards stay.
_DH_CARNIVAL_HIDE = ('/Panel_list', '/Panel_list_pop', '/Panel_bonus', '/Panel_dice05', '/Image_card')


def _dh_carnival_hide(ui):
    hidden = 0
    getter = getattr(ui, 'get_widget_by_path', None)
    if callable(getter):
        # reached by path, not an attribute: the pass-holder banner with its glow / particles, and the pot's lights
        for name in ('Image_card', 'card_add', 'card_lizi', 'card_fx01', 'card_fx02',
                     'bonus_light', 'bonus_light_0', 'zuanshi_node'):
            try:
                node = getter('content/' + name)
                if node is not None and node.isVisible():
                    node.setVisible(False)
                    hidden += 1
            except Exception:
                pass
    for path, node in walk_ui_nodes(ui, limit=4000):
        if path.endswith(_DH_CARNIVAL_HIDE):
            try:
                if node.isVisible():
                    node.setVisible(False)
                    hidden += 1
            except Exception:
                pass
    return hidden


def _dh_install_carnival_screens():
    done = []
    for modname in ('ui.UILuckyCarnivalAdvance', 'ui.UILuckyCarnivalSuper'):
        module = _dh_sys.modules.get(modname)
        if module is None:
            try:
                module = __import__(modname, fromlist=['x'])
            except Exception:
                continue
        cls = getattr(module, modname.split('.')[-1], None)
        for name in ('on_enter', 'refreshLuckyCarnivaPanel', 'updateDiamondPrize', 'updateDiamondPrizeRecord'):
            inner = cls.__dict__.get(name) if cls is not None else None
            if inner is None or getattr(inner, '_dh_carnival', False):
                continue

            def make(inner, name):
                def wrapped(self, *args, **kwargs):
                    result = inner(self, *args, **kwargs)
                    try:
                        _dh_carnival_hide(self)
                        # the entry animation and the ticker's scroll show their panels again a moment later
                        for delay in (0.3, 1.5, 3.0):
                            call_later(delay, _dh_carnival_hide, self)
                    except Exception:
                        log_error('local-carnival-hide-error', method=name)
                    return result
                wrapped._dh_carnival = True
                wrapped._dh_inner = inner
                return wrapped
            setattr(cls, name, make(inner, name))
            done.append('%s.%s' % (cls.__name__, name))
    return done


