# --- m84: the server list of a second game window (the launcher's "Open second window" starts x64\ros64.exe
# without the first window's update mirror, so the login screen's own download of /server_list_pc.txt reaches an
# outside host and lists its servers - "PC-Asia / PC-Europe / PC-America" - while the hook logs in to ours).
# UILogin.initServerInfo(content) gets that downloaded text; when it lists none of the launcher's servers, the
# launcher's own list (<LOCALAPPDATA>\ROS RedemptionROSHook\remote-servers.json, written at sign-in) is used instead, in
# the same line format (UILogin.parseOneServerInfo):
#   <zone> <load> <net> <status> <label> <name> <tel ip:port> <cnc ip:port> <edu ip:port> <groupId> <udp ip:port>
def _dh_launcher_server_text():
    import json as _json
    base = _dh_os.environ.get('LOCALAPPDATA') or ''
    for folder in ('DieHardROSHook', 'ROS RedemptionROSHook'):
        path = _dh_os.path.join(base, folder, 'remote-servers.json')
        if base and _dh_os.path.isfile(path):
            break
    else:
        return 'ROS-Redemption 1 0 2 X ROS-Redemption-Official 127.0.0.1:19000 127.0.0.1:19000 127.0.0.1:19000 10501 127.0.0.1:19000'
    with open(path, 'rb') as handle:
        data = _json.loads(handle.read().decode('utf-8-sig'))
    lines = []
    for server in (data.get('servers') or []):
        if server.get('enabled') is False:
            continue
        address = '%s:%d' % (str(server['host']), int(server['port']))
        name = str(server.get('name') or server['id']).replace(' ', '-')
        lines.append(' '.join([str(server.get('zone') or 'PC'), str(int(server.get('load', 1))),
                               str(int(server.get('net', 0))), str(int(server.get('status', 2))),
                               str(server.get('label') or 'X'), name, address, address, address,
                               str(int(server['id'])), address]))
    return '\n'.join(lines) or None


def _dh_server_text_hosts(text):
    """The game-server hosts of a list text (the <tel ip:port> column)."""
    hosts = set()
    for line in (text or '').splitlines():
        parts = line.split()
        if len(parts) >= 10 and ':' in parts[6]:
            hosts.add(parts[6].rsplit(':', 1)[0])
    return hosts


# a list on these hosts is a local / LAN game's own list and is kept
_DH_LOCAL_HOST_PREFIXES = ('127.', '10.', '192.168.', 'localhost')


def _dh_install_server_list():
    module = _dh_sys.modules.get('ui.UILogin')
    cls = getattr(module, 'UILogin', None) if module is not None else None
    inner = cls.__dict__.get('initServerInfo') if cls is not None else None
    if inner is None or getattr(inner, '_dh_servers', False):
        return False

    def initServerInfo(self, content, *args, **kwargs):
        try:
            # NetEase's own list (h45na.update.easebar.com) reuses our group ids (its PC-America is 10501 too),
            # so the servers' hosts decide: any host that is neither ours nor local means an outside list
            ours = _dh_launcher_server_text()
            mine = _dh_server_text_hosts(ours)
            got = _dh_server_text_hosts(content if isinstance(content, basestring) else '')
            outside = [h for h in got if h not in mine and not h.startswith(_DH_LOCAL_HOST_PREFIXES)]
            if mine and outside:
                log('local-server-list-replaced', downloaded=sorted(got)[:8], used=sorted(mine))
                content = ours
        except Exception:
            log_error('local-server-list-replace-error')
        return inner(self, content, *args, **kwargs)
    initServerInfo._dh_servers = True
    initServerInfo._dh_inner = inner
    cls.initServerInfo = initServerInfo
    return True


try:
    log('local-server-list-guard', installed=_dh_install_server_list())
except Exception:
    log_error('local-server-list-guard-error')
log('local-art-installed', version='m84')


# --- m85: notices from our server (server_ext/notices.py, console -> Notices).  The login screen's notice window
# (UIUserAgreement: NOTICE / EVENTS / CONTACT) shows the text the game downloads from NetEase's old update host -
# its 2022 shutdown notices.  Our server serves the same file, http://<our host>/notice_pc_hw.txt, written in the
# console; it is loaded once at start-up (a background thread, never on the game's thread) and
# UIUASysPanel.filterContent - the game's own splitter of that file - is given our text instead.
_DH_NOTICE_FALLBACK = (u'#cFF9900Welcome to ROS Redemption#n\n\nThe latest news could not be loaded. '
                       u'Visit #cFF9900https://ROS REDEMPTION#n for announcements.\n\n$SED$\n\n$AED$\n\n'
                       u'Official website:  #cFF9900https://ROS REDEMPTION#n\n')
_dh_notice = globals().get('_dh_notice') or {'text': None, 'state': 'idle', 'host': None}
_DH_NOTICE_SITE = 'ROS REDEMPTION'


def _dh_notice_host():
    import json as _json
    base = _dh_os.environ.get('LOCALAPPDATA') or ''
    path = _dh_os.path.join(base, 'ROS RedemptionROSHook', 'remote-servers.json')
    if not base or not _dh_os.path.isfile(path):
        return None
    with open(path, 'rb') as handle:
        data = _json.loads(handle.read().decode('utf-8-sig'))
    for server in (data.get('servers') or []):
        host = str(server.get('host') or '')
        if host and not host.startswith(_DH_LOCAL_HOST_PREFIXES):
            return host
    return None


def _dh_notice_fetch():
    import urllib2
    try:
        host = _dh_notice_host()
    except Exception:
        host = None
    _dh_notice['host'] = host
    if not host:
        _dh_notice['state'] = 'no-host'
        log('local-notice-loaded', state='no-host')
        return
    # three tries: two game windows on one PC start together, and the website limits requests per address
    for attempt, pause in enumerate((0, 4, 12)):
        if pause:
            _dh_time.sleep(pause)
        try:
            # the server's notice port first (server_ext/notices.py GAME_PORT): a launcher-started game's own
            # port 80 / 443 traffic reaches the launcher's local mirror (a 404 for this file); the website after
            raw = None
            for url in ('http://%s:19019/notice_pc_hw.txt' % host, 'https://%s/notice_pc_hw.txt' % _DH_NOTICE_SITE,
                        'http://%s/notice_pc_hw.txt' % host):
                try:
                    handlers = [urllib2.ProxyHandler({})]
                    if url.startswith('https'):
                        import ssl as _ssl
                        maker = getattr(_ssl, '_create_unverified_context', None)
                        if maker is not None:
                            handlers.append(urllib2.HTTPSHandler(context=maker()))
                    raw = urllib2.build_opener(*handlers).open(url, timeout=8).read()
                    break
                except Exception as error:
                    _dh_notice['last_error'] = '%s %s' % (type(error).__name__, getattr(error, 'code', '') or error)
            if raw is None:
                raise IOError(_dh_notice.get('last_error') or 'no answer')
            text = raw.decode('utf-8')
            if '$SED$' in text:
                _dh_notice['text'] = text
                _dh_notice['state'] = 'ready'
                break
            _dh_notice['state'] = 'bad-file'
        except Exception as error:
            _dh_notice['state'] = 'failed: %s %s' % (type(error).__name__, getattr(error, 'code', '') or error)
    log('local-notice-loaded', state=_dh_notice['state'], host=host, attempt=attempt,
        size=len(_dh_notice['text'] or u''))


def _dh_install_notice():
    try:
        module = _dh_sys.modules.get('ui.UIUserAgreement') or __import__('ui.UIUserAgreement', fromlist=['UIUASysPanel'])
    except Exception:
        return None
    cls = getattr(module, 'UIUASysPanel', None)
    inner = cls.__dict__.get('filterContent') if cls is not None else None
    if inner is None or getattr(inner, '_dh_notice', False):
        return False

    def filterContent(self, content, *args, **kwargs):
        try:
            if _dh_notice['host']:      # an online ROS Redemption client: never NetEase's notices
                ours = _dh_notice['text'] or _DH_NOTICE_FALLBACK
                if isinstance(content, str) and isinstance(ours, unicode):
                    ours = ours.encode('utf-8')
                content = ours
        except Exception:
            log_error('local-notice-swap-error')
        return inner(self, content, *args, **kwargs)
    filterContent._dh_notice = True
    filterContent._dh_inner = inner
    cls.filterContent = filterContent
    return True


try:
    if _dh_notice['state'] in ('idle',) or str(_dh_notice['state']).startswith('failed'):
        _dh_notice['state'] = 'loading'
        import threading as _dh_threading
        _dh_notice_thread = _dh_threading.Thread(target=_dh_notice_fetch, name='dh-notice')
        _dh_notice_thread.daemon = True
        _dh_notice_thread.start()
    log('local-notice-guard', installed=_dh_install_notice())
except Exception:
    log_error('local-notice-guard-error')
log('local-art-installed', version='m85')


# --- m86: (1) the second window's server list is downloaded before this patch loads (its login screen starts at
# once), so m84's initServerInfo guard came too late there.  The login screen's own data (UILogin.saServerList /
# serverInfoList, 'PC-Asia / PC-America / PC-Europe') is corrected after the fact: our list parsed by the game's own
# updateServerList, our server selected by its own setDefaultServerInfo.  Checked when the patch loads, after
# initServerList, before the Select Server screen opens, and every 2 s while the login screen is open (1 minute).
# (2) The first window's own notice download reaches the launcher's local mirror (404), so the game never opened its
# notice window.  The Notice button now opens it with our text (the game's own enter_ui('UIUserAgreement', text)),
# and a new notice version opens once by itself at the login screen.
def _dh_list_hosts(server_lists):
    hosts = set()
    for value in (server_lists or {}).values() if isinstance(server_lists, dict) else []:
        for info in value or []:
            if isinstance(info, dict) and info.get('ip'):
                hosts.add(str(info.get('ip')))
    return hosts


def _dh_fix_login_servers(ui, reason):
    if ui is None:
        return False
    ours = _dh_launcher_server_text()
    mine = _dh_server_text_hosts(ours)
    if not mine:
        return False
    got = _dh_list_hosts(getattr(ui, 'saServerList', None)) | _dh_list_hosts(getattr(ui, 'serverInfoList', None))
    outside = [h for h in got if h not in mine and not h.startswith(_DH_LOCAL_HOST_PREFIXES)]
    if not outside:
        return False
    cls = type(ui)
    parse = cls.__dict__.get('updateServerList')
    while getattr(parse, '_dh_inner', None) is not None:
        parse = parse._dh_inner
    temp = cls.__new__(cls)
    temp.__dict__['saServerList'] = {}
    parse(temp, ours)
    parsed = temp.__dict__.get('saServerList') or {}
    if not parsed:
        return False
    import copy as _copy
    ui.saServerList = parsed
    ui.serverInfoList = _copy.deepcopy(parsed)
    servers = [info for zone in parsed.values() for info in zone]
    wanted = str(getattr(ui, 'defaultGroupId', '') or '')
    chosen = next((info for info in servers if str(info.get('groupid')) == wanted), servers[0])
    try:
        ui.setDefaultServerInfo(chosen)
    except Exception:
        log_error('local-server-list-default-error')
    # an already open Select Server keeps its rows until it is opened again (redrawing it in place broke it)
    log('local-server-list-fixed', reason=reason, removed=sorted(outside)[:6], servers=[s.get('name') for s in servers],
        selected=chosen.get('name'))
    return True


def _dh_open_login():
    try:
        import Globals
        # hidden (not is_enter) while Select Server is on top of it - still the screen whose data is shown
        return (getattr(Globals.uiMgr, '____all_ui__', {}) or {}).get('UILogin')
    except Exception:
        return None


def _dh_server_list_watch(left):
    try:
        ui = _dh_open_login()
        if ui is not None:
            _dh_fix_login_servers(ui, 'watch')
    except Exception:
        log_error('local-server-list-watch-error')
    if left > 0 and not _dh_in_lobby():
        call_later(2.0, _dh_server_list_watch, left - 1)


def _dh_notice_text_for_game():
    text = _dh_notice['text'] if _dh_notice['host'] else None
    if text is None:
        return None
    return text.encode('utf-8') if isinstance(text, unicode) else text


def _dh_notice_seen_path():
    return _dh_os.path.join(_dh_os.environ.get('LOCALAPPDATA') or '', 'ROS RedemptionROSHook', 'notice-seen.txt')


def _dh_install_login_fixes():
    module = _dh_sys.modules.get('ui.UILogin')
    cls = getattr(module, 'UILogin', None) if module is not None else None
    done = []
    if cls is None:
        return done
    inner = cls.__dict__.get('initServerList')
    if inner is not None and not getattr(inner, '_dh_login_fix', False):
        def initServerList(self, *args, **kwargs):
            result = inner(self, *args, **kwargs)
            try:
                _dh_fix_login_servers(self, 'initServerList')
            except Exception:
                log_error('local-server-list-fix-error')
            return result
        initServerList._dh_login_fix = True
        initServerList._dh_inner = inner
        cls.initServerList = initServerList
        done.append('initServerList')
    # m93: onSelectServerBtnTouch is a libclaudia message handler (UILogin.____messageHandlers__); GameObject.SendMessage
    # calls a handler by its declared argument count, so the (self, *args, **kwargs) wrapper m86 put here was never
    # callable - "Select Server" (and nothing else) did nothing from 2026-10-21 until 2026-10-22.  The list is fixed
    # by initServerList and the watch above; the click needs no wrapper.  A wrapper left by an older patch (hot
    # reload) is taken off again.
    current = cls.__dict__.get('onSelectServerBtnTouch')
    if current is not None and getattr(current, '_dh_login_fix', False):
        original = current
        while getattr(original, '_dh_inner', None) is not None:
            original = original._dh_inner
        cls.onSelectServerBtnTouch = original
        done.append('onSelectServerBtnTouch-unwrapped')
    # the Notice button: our notices, whatever the game's own download did
    inner_notice = getattr(cls, 'requestSysNotice', None)
    if inner_notice is not None and not getattr(inner_notice, '_dh_login_fix', False):
        inner_notice = getattr(inner_notice, '__func__', inner_notice)

        def requestSysNotice(self, *args, **kwargs):
            text = _dh_notice_text_for_game()
            if text:
                try:
                    import Globals
                    Globals.uiMgr.enter_ui('UIUserAgreement', text)
                    self.sysnoticeopen = True
                    log('local-notice-opened', by='button')
                    return None
                except Exception:
                    log_error('local-notice-open-error')
            return inner_notice(self, *args, **kwargs)
        requestSysNotice._dh_login_fix = True
        requestSysNotice._dh_inner = inner_notice
        cls.requestSysNotice = requestSysNotice
        done.append('requestSysNotice')
    # the login screen's own pop-up: once for each new notice version
    inner_auto = getattr(cls, 'requestSysNotice_Auto', None)
    if inner_auto is not None and not getattr(inner_auto, '_dh_login_fix', False):
        inner_auto = getattr(inner_auto, '__func__', inner_auto)

        def requestSysNotice_Auto(self, *args, **kwargs):
            text = _dh_notice_text_for_game()
            if not text:
                return inner_auto(self, *args, **kwargs)
            try:
                import hashlib as _hashlib
                version = _hashlib.md5(text).hexdigest()
                path = _dh_notice_seen_path()
                seen = open(path).read().strip() if _dh_os.path.isfile(path) else ''
                self.sysNoticeContent = text
                if seen != version:
                    self.canOpenSysNoticeAuto = True
                    with open(path, 'w') as handle:
                        handle.write(version)
                log('local-notice-auto', new=seen != version)
            except Exception:
                log_error('local-notice-auto-error')
            return None
        requestSysNotice_Auto._dh_login_fix = True
        requestSysNotice_Auto._dh_inner = inner_auto
        cls.requestSysNotice_Auto = requestSysNotice_Auto
        done.append('requestSysNotice_Auto')
    return done


try:
    log('local-login-fixes', wrapped=_dh_install_login_fixes())
    _dh_fix_login_servers(_dh_open_login(), 'load')
    call_later(2.0, _dh_server_list_watch, 30)
except Exception:
    log_error('local-login-fixes-error')
