# --- m87: custom room entries.  The game reads a room both ways - iDtsCustomGame.onRequestRoomListInfo sorts the
# list by room['isOfficial'], tryJoinDtsCustomGame compares room.creatorGID / room.hostID - so its own entries were
# objects with both; the server's are plain dicts ("'dict' object has no attribute 'creatorGID'": joining a room did
# nothing).  The entries are turned into a dict that also answers attribute reads, before the game's code runs.
class _DhRoomInfo(dict):
    def __getattr__(self, name):
        try:
            return self[name]
        except KeyError:
            if name == 'hostID':            # a server without it: the player's own (the game compares the two)
                try:
                    import BigWorld
                    return getattr(BigWorld.player(), 'hostID', 0)
                except Exception:
                    return 0
            raise AttributeError(name)


def _dh_room_infos(value):
    if isinstance(value, (list, tuple)):
        return [_DhRoomInfo(v) if isinstance(v, dict) and not isinstance(v, _DhRoomInfo) else v for v in value]
    return value


def _dh_install_room_infos():
    module = _dh_sys.modules.get('iDtsCustomGame')
    cls = getattr(module, 'iDtsCustomGame', None) if module is not None else None
    if cls is None:
        return None
    done = []
    inner_list = cls.__dict__.get('onRequestRoomListInfo')
    if inner_list is not None and not getattr(inner_list, '_dh_rooms', False):
        def onRequestRoomListInfo(self, roomListInfo, *args, **kwargs):
            return inner_list(self, _dh_room_infos(roomListInfo), *args, **kwargs)
        onRequestRoomListInfo._dh_rooms = True
        onRequestRoomListInfo._dh_inner = inner_list
        cls.onRequestRoomListInfo = onRequestRoomListInfo
        done.append('onRequestRoomListInfo')
    inner_join = cls.__dict__.get('tryJoinDtsCustomGame')
    if inner_join is not None and not getattr(inner_join, '_dh_rooms', False):
        def tryJoinDtsCustomGame(self, *args, **kwargs):
            try:
                self.roomListInfo = _dh_room_infos(getattr(self, 'roomListInfo', None))
            except Exception:
                log_error('local-room-infos-error')
            return inner_join(self, *args, **kwargs)
        tryJoinDtsCustomGame._dh_rooms = True
        tryJoinDtsCustomGame._dh_inner = inner_join
        cls.tryJoinDtsCustomGame = tryJoinDtsCustomGame
        done.append('tryJoinDtsCustomGame')
    return done


try:
    log('local-room-infos', wrapped=_dh_install_room_infos())
except Exception:
    log_error('local-room-infos-install-error')
