# --- m88: expansion maps the client already has (server_ext/dlc_maps.py).  Documents/res holds dlc8k.npk (The Fiord)
# and dlcfps.npk, but the game counts a DLC as ready (Globals.DLCTypesDone) only after its own NetEase patcher
# downloaded it - Modes showed The Fiord with a download icon.  A DLC whose files the game's own check finds
# (BigMapDownloader.checkDLCNpk) is marked ready, as HallDLCManager.callBackOnDownloadSuccess would after a download.
# Next-gen (needs the next-gen engine) and Train (no dlctrain.npk) are left alone.
_DH_DLC_READY_TYPES = ('BIG_MAP', 'FPS_MODE')


def _dh_mark_dlc_ready(reason):
    try:
        import Globals
        import const
        downloader = _dh_sys.modules.get('BigMapDownloader') or __import__('BigMapDownloader')
    except Exception:
        return None
    done = getattr(Globals, 'DLCTypesDone', None)
    if done is None:
        return None
    added = []
    for name in _DH_DLC_READY_TYPES:
        dlc_type = getattr(const.DLCType, name, None)
        if dlc_type is None or dlc_type in done:
            continue
        try:
            ready = bool(downloader.checkDLCNpk(dlc_type))
        except Exception:
            ready = False
        if ready:
            done.add(dlc_type)
            added.append(name)
    if added:
        try:
            import BigWorld
            player = BigWorld.player()
            if 'BIG_MAP' in added and hasattr(player, 'base'):
                player.base.requestChangeEnterBigMapState(True)
        except Exception:
            log_error('local-dlc-ready-rpc-error')
    log('local-dlc-ready', reason=reason, added=added, done=sorted(done))
    return added


def _dh_install_dlc_watchers():
    """The map cards' download badge (ui.main.UIModes.DLCModeWatcher) follows the patcher's status, never
    DLCTypesDone: a watcher of a ready DLC shows 'done' (the game's own STATUS_DONE look: no download button)."""
    module = _dh_sys.modules.get('ui.main.UIModes')
    cls = getattr(module, 'DLCModeWatcher', None) if module is not None else None
    inner = cls.__dict__.get('setDownloadState') if cls is not None else None
    if inner is None or getattr(inner, '_dh_dlc', 0) >= 2:
        return False
    while getattr(inner, '_dh_inner', None) is not None:     # an older version of this wrapper
        inner = inner._dh_inner
    status_cls = getattr(inner, 'func_globals', {}).get('PatcherStatus')
    if status_cls is None:
        return False

    def setDownloadState(self, status, *args, **kwargs):
        ready = False
        try:
            import Globals
            ready = getattr(self, 'dlcType', None) in (getattr(Globals, 'DLCTypesDone', None) or ())
            if ready:
                status = status_cls.STATUS_DONE
        except Exception:
            log_error('local-dlc-watcher-error')
        result = inner(self, status, *args, **kwargs)
        if ready:
            try:                            # the card's download overlay (it also caught the card's clicks)
                self.widget.setVisible(False)
            except Exception:
                log_error('local-dlc-watcher-hide-error')
        return result
    setDownloadState._dh_dlc = 2
    setDownloadState._dh_inner = inner
    cls.setDownloadState = setDownloadState
    return True


def _dh_refresh_dlc_watchers():
    """Watchers already on screen (registered with UIMain's Hall*DLCManager components) are told again."""
    refreshed = 0
    try:
        import Globals
        components = []
        for ui in list((getattr(Globals.uiMgr, '____all_ui__', {}) or {}).values()):
            try:
                components.extend(getattr(ui.gameObject, '____components__', None) or [])
            except Exception:
                continue
        for component in components:
            if type(component).__name__ == 'DLCModeWatcher':
                component.setDownloadState(None)
                refreshed += 1
                continue
            watchers = getattr(component, 'watchers', None)
            values = list(watchers.values()) if isinstance(watchers, dict) else list(watchers or [])
            for value in values:
                for watcher in (list(value.values()) if isinstance(value, dict) else [value]):
                    if hasattr(watcher, 'setDownloadState'):
                        watcher.setDownloadState(None)
                        refreshed += 1
    except Exception:
        log_error('local-dlc-watcher-refresh-error')
    return refreshed


def _dh_dlc_pass(reason):
    added = _dh_mark_dlc_ready(reason)
    wrapped = _dh_install_dlc_watchers()
    refreshed = _dh_refresh_dlc_watchers()
    log('local-dlc-watchers', reason=reason, wrapped=wrapped, refreshed=refreshed, added=added)


