# ---- m99: the lobby nameplate (your own team slot under the character: name, rank badge, flag) always shows.
# Cause (laptop hook log + widget-tree probes, 2026-10-24): two cleaners hid it.  (1) lobby_hook.clean_lobby_ui
# hides FOUR levels above any "haven't paid" / "additional 20%" text: Text_payment_state -> payment_state ->
# player-info -> member-N -> team/anchor-center, i.e. the whole team panel, your own slot (member-1) included.
# (2) The runtime's brand sweeper (_dh_slot_sweep) matched the same stock texts and hid each slot's player-info.
# A screen change rebuilt the panel, which is why the plate came back after visiting Supply.  Now: _hide_ancestor
# never climbs onto a team structural node (anchor-center / member-N / player-info) - it hides the stock badge
# itself; the sweep hides only the matched text node inside a slot; a team anchor hidden before this patch loaded
# is shown again once; the slot carries own_flag() (local_team_member hard-coded '' = the globe) and a flag
# change (rlOwnFlag) re-syncs the team and redraws.  No extra timers: the existing brand tick calls the sweep.
_dh_plate = globals().get('_dh_plate') or {}
for _dh_k in ('redraws', 'restored', 'load_tries'):
    _dh_plate.setdefault(_dh_k, 0)


_DH_TEAM_STRUCTURAL = ('anchor-center', 'player-info', 'team')


def _dh_is_team_structural(node):
    try:
        name = str(node.getName() or '')
    except Exception:
        return False
    return name in _DH_TEAM_STRUCTURAL or name.startswith('member-')


def _dh_hide_ancestor_m99(node, levels):
    """lobby_hook._hide_ancestor, stopped below the team panel's structural nodes."""
    target = node
    for _index in range(int(levels or 0)):
        try:
            parent = target.getParent()
        except Exception:
            parent = None
        if parent is None or _dh_is_team_structural(parent):
            break
        target = parent
    if _dh_is_team_structural(target):
        return False
    try:
        target.setVisible(False)
        if target is not node and _dh_plate.get('clamped', 0) < 3:
            _dh_plate['clamped'] = _dh_plate.get('clamped', 0) + 1
        return True
    except Exception:
        return False


def _dh_local_team_member_flag(lobby_player, *args, **kwargs):
    member = _dh_local_team_member_flag._dh_inner(lobby_player, *args, **kwargs)
    try:
        member['nationalFlag'] = own_flag() or 'UN'
    except Exception:
        pass
    return member


def _dh_redraw_plate(why):
    try:
        import BigWorld
        import Globals
        player = BigWorld.player()
        main_ui = getattr(Globals.uiMgr, 'UIMain', None)
        if player is None or main_ui is None or not _lobby.get('entered'):
            return False
        sync_local_team(player)
        refresh = getattr(main_ui, 'onFormTeam', None)
        if callable(refresh):
            try:
                refresh(False)
            except Exception:
                pass
        _dh_plate['redraws'] += 1
        log('local-plate-redraw', why=why, count=_dh_plate['redraws'], flag=own_flag() or 'UN')
        return True
    except Exception:
        return False


def _dh_plate_load_tick():
    # one redraw once the lobby is entered (the first sync may have run while the slot was hidden)
    _dh_plate['load_tries'] += 1
    if _dh_redraw_plate('load') or _dh_plate['load_tries'] >= 30:
        return
    call_later(5.0, _dh_plate_load_tick)


def _dh_slot_sweep_m99():
    """The runtime's _dh_slot_sweep, with team slots handled per text node."""
    try:
        import Globals
        main_ui = getattr(Globals.uiMgr, 'UIMain', None)
        if main_ui is None:
            return
        brand = globals().get('_dh_brand')
        needles = globals().get('DH_SLOT_NEEDLES') or ()
        text_of = globals().get('_node_text')
        lower = globals().get('_dh_lower') or (lambda t: t.lower())
        if brand is None or text_of is None or not needles:
            return
        done = brand.setdefault('done_paths', set())
        nodes = walk_ui_nodes(main_ui, limit=4000)
        by_path = dict(nodes)
        restored = []
        if not _dh_plate.get('anchor_restored'):
            # the team panel hidden by clean_lobby_ui before this patch loaded: shown again, once per load
            for path, node in nodes:
                if path == 'team/anchor-center':
                    _dh_plate['anchor_restored'] = True
                    try:
                        if not node.isVisible():
                            node.setVisible(True)
                            restored.append(path)
                    except Exception:
                        pass
        hits = [path for path, node in nodes if any(n in lower(text_of(node) or '') for n in needles)]
        hidden = []
        for path in hits:
            parts = path.split('/')
            if path.startswith('team/'):
                # inside a team slot: only the stock text itself, never the name or the whole plate
                target = None if parts[-1] == 'name' else path
            else:
                target = None
                for depth in range(len(parts) - 1, 1, -1):
                    name = parts[depth - 1].lower()
                    if any(k in name for k in ('slot', 'member', 'team', 'mate', 'player')):
                        target = '/'.join(parts[:depth])
                        break
                if target is None and len(parts) > 3:
                    target = '/'.join(parts[:-2])
            node = by_path.get(target) if target else None
            if node is not None and target not in done:
                try:
                    node.setVisible(False)
                    hidden.append(target)
                    done.add(target)
                except Exception:
                    pass
        if restored:
            _dh_plate['restored'] += len(restored)
            log('local-plate-restored', paths=restored[:8])
        if hidden:
            log('local-slot-sweep', hits=hits[:20], hidden=hidden[:20], version='m99')
    except Exception:
        log_error('local-slot-sweep-error')


def _dh_own_flag_redraw(player, code, *args, **kwargs):
    result = _dh_own_flag_redraw._dh_inner(player, code, *args, **kwargs)
    try:
        call_later(0.5, _dh_redraw_plate, 'flag-changed')
    except Exception:
        pass
    return result


def _dh_install_plate():
    inner = globals().get('local_team_member')
    if inner is not None:
        while getattr(inner, '_dh_m99', False) and getattr(inner, '_dh_inner', None) is not None:
            inner = inner._dh_inner
        _dh_local_team_member_flag._dh_inner = inner
        _dh_local_team_member_flag._dh_m99 = True
        globals()['local_team_member'] = _dh_local_team_member_flag
    flag_cb = LOCAL_CALLBACKS.get('rlOwnFlag')
