# ---- m101: the stock NetEase anti-cheat SDK calls stopped.  Every player logged a traceback every 3-8 minutes since
# launch: iGMAdmin.antiCheatSDKCheck(logReason) calls the native game3d.anti_cheat_check with no arguments (the
# native SDK is not in our client: "takes exactly 2 arguments (0 given)"), and the iAntiCheating.heartBeatCheck
# coroutine imports Crypto.Cipher.ARC4, whose native _ARC4 is missing.  Our own Cheat Guard (server rules +
# launcher scan + dhGuardReport) replaces them.  Same signatures as the originals (handler-signature rule).
def _dh_ac_sdk_check(self, logReason):
    return None


def _dh_ac_heartbeat(self):
    return
    yield None   # a coroutine that ends at once (the scheduler expects a generator)


_dh_ac_sdk_check._dh_m101 = True
_dh_ac_heartbeat._dh_m101 = True
_dh_ac_state = globals().get('_dh_ac_state') or {'tries': 0, 'done': set()}


def _dh_stop_ac_sdk():
    import sys
    for mod_name, cls_name, attr, replacement in (('iGMAdmin', 'iGMAdmin', 'antiCheatSDKCheck', _dh_ac_sdk_check),
                                                  ('iAntiCheating', 'iAntiCheating', 'heartBeatCheck', _dh_ac_heartbeat)):
        key = cls_name + '.' + attr
        if key in _dh_ac_state['done']:
            continue
        cls = getattr(sys.modules.get(mod_name), cls_name, None)
        current = getattr(cls, attr, None) if cls is not None else None
        if current is None:
            continue
        if not getattr(getattr(current, 'im_func', current), '_dh_m101', False):
            setattr(cls, attr, replacement)
        _dh_ac_state['done'].add(key)
    _dh_ac_state['tries'] += 1
    if len(_dh_ac_state['done']) < 2 and _dh_ac_state['tries'] < 60:
        call_later(10.0, _dh_stop_ac_sdk)
    else:
        log('local-ac-sdk-stopped', stopped=sorted(_dh_ac_state['done']), tries=_dh_ac_state['tries'])


try:
    _dh_ac_state['tries'] = 0
    _dh_stop_ac_sdk()
except Exception:
    log_error('local-ac-sdk-stop-error')
log('local-art-installed', version='m101')


# ---- m102: lobby emotes show above the character.  The emote panel (UIMainActionAndEmoji.onClickEmojiItem) calls
# player.hallScene.unbindEmoji / bindEmoji and then base.equipAppearance.  Our hallScene is the hook's LocalHallScene,
# whose unknown methods are no-ops, so the equip worked (dtsEmojiID set) but nothing was drawn.  These two methods draw
# the emote on the dressed lobby model (hallScene.model) with the game's own iDress.wearEmoji / takeoffEmoji (an sfx at
# the HP_top socket).  Emote ids are 980001-989999 (EmojiType in the hall-prop table).
_dh_emote_state = globals().get('_dh_emote_state') or {'shown': None, 'binds': 0, 'errors': 0}
_dh_emote_state['debug'] = 0


def _dh_emote_id(args, kwargs):
    for value in list(args) + list(kwargs.values()):
        try:
            number = int(value)
        except (TypeError, ValueError):
            continue
        if 980000 <= number <= 989999:
            return number
    return None


_dh_emote_where = globals().get('_dh_emote_where') or {'module': None, 'logged': False}
_dh_emote_where['logged'] = False


def _dh_emote_dress(name, load=False):
    """iDress.wearEmoji / takeoffEmoji.  m103: the module is not always loaded as player.appearance.iDress (a
    session after a restart had no such key and no emote was drawn): look through the loaded modules for the
    iDress class, remember where it was.  The game loads that module lazily (a session that never opened the
    outfit screens had none): with load=True (an emote click, never at start-up) import the game's own module."""
    import sys
    cls = None
    for key in filter(None, (_dh_emote_where['module'], 'player.appearance.iDress')):
        cls = getattr(sys.modules.get(key), 'iDress', None)
        if cls is not None:
            break
    if cls is None:
        for key, mod in list(sys.modules.items()):
            if mod is None or not key.endswith('iDress'):
                continue
            found = getattr(mod, 'iDress', None)
            if found is not None and 'wearEmoji' in getattr(found, '__dict__', {}):
                cls = found
                _dh_emote_where['module'] = key
                break
        if cls is None and load:
            try:
                cls = getattr(__import__('player.appearance.iDress', fromlist=['iDress']), 'iDress', None)
                if cls is not None:
                    _dh_emote_where['module'] = 'player.appearance.iDress'
            except Exception:
                log_error('local-lobby-emote-import-error')
        if load and not _dh_emote_where['logged']:
            _dh_emote_where['logged'] = True
            log('local-lobby-emote-dress', module=_dh_emote_where['module'],
                candidates=[k for k in sys.modules.keys() if 'ress' in k.lower()][:12])
    return cls.__dict__.get(name) if cls is not None else None


def _dh_bind_emoji(self, *args, **kwargs):
    try:
        emoji = _dh_emote_id(args, kwargs) or int(getattr(__import__('BigWorld').player(), 'dtsEmojiID', 0) or 0) or None
        model = getattr(self, 'model', None)
        wear = _dh_emote_dress('wearEmoji', load=True)
        if emoji is None or model is None or wear is None:
            return None
        if _dh_emote_state['shown'] and _dh_emote_state['shown'] != emoji:
            _dh_unbind_emoji(self, _dh_emote_state['shown'])
        result = wear(None, model, emoji)
        _dh_emote_state['shown'] = emoji
        _dh_emote_state['binds'] += 1
        _dh_emote_state['debug'] = _dh_emote_state.get('debug', 0) + 1
        if _dh_emote_state['debug'] <= 3 or _dh_emote_state['binds'] in (20, 200):
            shown = None
            try:
                import Globals
                main = getattr(Globals.uiMgr, 'UIMain', None)
                shown = dict((k, safe(v.get('model') if isinstance(v, dict) else v, 60)) for k, v in (getattr(main, 'models', None) or {}).items())
            except Exception:
                pass
            log('local-lobby-emote', emoji=emoji, binds=_dh_emote_state['binds'], model=safe(model, 60),
                visible=safe(getattr(model, 'visible', None), 10), lobby_models=shown, result=safe(result, 60))
    except Exception:
        _dh_emote_state['errors'] += 1
        if _dh_emote_state['errors'] <= 3:
            log_error('local-lobby-emote-error')
    return None


def _dh_unbind_emoji(self, *args, **kwargs):
    try:
        emoji = _dh_emote_id(args, kwargs) or _dh_emote_state['shown']
        model = getattr(self, 'model', None)
        takeoff = _dh_emote_dress('takeoffEmoji', load=True)
        if emoji is not None and model is not None and takeoff is not None:
            takeoff(None, model, emoji)
        if emoji == _dh_emote_state['shown']:
            _dh_emote_state['shown'] = None
    except Exception:
        _dh_emote_state['errors'] += 1
        if _dh_emote_state['errors'] <= 3:
            log_error('local-lobby-emote-unbind-error')
    return None


try:
    _dh_hall_cls = globals().get('LocalHallScene')
    if _dh_hall_cls is not None:
        _dh_hall_cls.bindEmoji = _dh_bind_emoji
        _dh_hall_cls.unbindEmoji = _dh_unbind_emoji
    log('local-lobby-emote-installed', hall=_dh_hall_cls is not None, dress=_dh_emote_dress('wearEmoji') is not None)
except Exception:
    log_error('local-lobby-emote-install-error')
# ---- m103: the lobby's mail button never showed the red "new mail" dot.  The game lights it from
# iChat.onMailUpdate (friendNoticeSub.onNewMail for unread rows), and that only ran when the mail window asked
# (requestMails); the official server pushed it at login.  Ask once each time the lobby screen opens and every
# MAIL_POLL seconds while it stays open (one small backend call): unread / unclaimed mails show the dot.
_DH_MAIL_POLL = 180.0
_dh_mail = globals().get('_dh_mail') or {'token': 0, 'in_lobby': False, 'asked_at': 0.0, 'asks': 0}
_dh_mail['token'] += 1


def _dh_mail_tick(token):
    if token != _dh_mail['token']:
        return                              # a newer copy of this patch took over
    try:
        import time as _t
        in_lobby = _dh_in_lobby()
        now = _t.time()
        if in_lobby and (not _dh_mail['in_lobby'] or now - _dh_mail['asked_at'] >= _DH_MAIL_POLL):
            import BigWorld
            player = BigWorld.player()
            base = getattr(player, 'base', None)
            if base is not None and hasattr(base, 'requestMails'):
                base.requestMails()
                _dh_mail['asked_at'] = now
                _dh_mail['asks'] += 1
                if _dh_mail['asks'] in (1, 2, 10, 100):
                    log('local-mail-dot-asked', asks=_dh_mail['asks'])
        _dh_mail['in_lobby'] = in_lobby
    except Exception:
        if not _dh_mail.get('error_logged'):
            _dh_mail['error_logged'] = True
            log_error('local-mail-dot-error')
    call_later(2.0, _dh_mail_tick, token)


call_later(3.0, _dh_mail_tick, _dh_mail['token'])
# ---- m104: the lobby character wore another outfit than the Depot's ticks (owner 2026-10-27: Ember Spirit - Red on
# the model, Neon Man ticked and worn in battle).  The hook keeps one outfit per gender (_rlGenderOutfits) and only
# refreshed it on a male / female switch; equipping clothes later left the CURRENT gender's kept outfit stale, and the
# model is dressed from it (outfit_for_gender).  Every save now also keeps the current gender's outfit = what is
# worn, and the stale entry is repaired once when this patch loads.
def _dh_current_gender(player):
    gender = int_arg(player.__dict__.get('dtsAppearanceGender')) or appearance_gender()
    if not gender:
        try:
            gender = character_gender(player.getCharacterType())
        except Exception:
            gender = 0
    return int(gender or 0)


def _dh_sync_gender_outfit(player):
    gender = _dh_current_gender(player)
    if not gender:
        return None
    outfits = dict(player.__dict__.get(GENDER_OUTFITS_ATTR) or {})
    worn = dict((prop, id_list(player.__dict__.get(prop)) or []) for prop in GENDERED_OUTFIT_PROPS)
    if outfits.get(str(gender)) == worn:
        return False
    outfits[str(gender)] = worn
    setattr(player, GENDER_OUTFITS_ATTR, outfits)
    return True


def _dh_save_appearance_wrapper(player, *args, **kwargs):
    try:
        if _dh_sync_gender_outfit(player) and _dh_outfit['logged'] < 5:
            _dh_outfit['logged'] += 1
            log('local-gender-outfit-synced', gender=_dh_current_gender(player))
    except Exception:
        if not _dh_outfit.get('error_logged'):
            _dh_outfit['error_logged'] = True
            log_error('local-gender-outfit-sync-error')
    return _dh_save_appearance_wrapper._dh_inner(player, *args, **kwargs)


_dh_outfit = globals().get('_dh_outfit') or {'logged': 0}
try:
    _dh_current_save = globals().get('save_appearance')
    while getattr(_dh_current_save, '_dh_outfit_sync', False):
        _dh_current_save = _dh_current_save._dh_inner
    if callable(_dh_current_save):
        _dh_save_appearance_wrapper._dh_inner = _dh_current_save
        _dh_save_appearance_wrapper._dh_outfit_sync = True
        save_appearance = _dh_save_appearance_wrapper
    log('local-gender-outfit-installed', wrapped=callable(_dh_current_save))
except Exception:
    log_error('local-gender-outfit-install-error')


def _dh_outfit_repair(tries=0):
    """Once the lobby player is up: repair a stale kept outfit of the current gender (retries for 5 minutes)."""
    try:
        import BigWorld as _dh_bw
        player = _dh_bw.player()
        if player is None or not hasattr(player, 'dtsWearableAppearanceList') or not _dh_in_lobby():
            if tries < 60:
                call_later(5.0, _dh_outfit_repair, tries + 1)
            return
        if _dh_sync_gender_outfit(player):
            _dh_save_appearance_wrapper._dh_inner(player)
            log('local-gender-outfit-repaired', gender=_dh_current_gender(player))
    except Exception:
        log_error('local-gender-outfit-repair-error')


try:
    call_later(5.0, _dh_outfit_repair, 0)
except Exception:
    log_error('local-gender-outfit-install-error')


# ---- m107: seasonal LOBBY THEME = the game's own lobby themes (owner 2026-10-28: no drawn art, no text - reuse what
# is in the game).  The lobby's 3D environment is the player's dtsHallThemeID (default 270000) and the game's own
# onUpdateDtsHallThemeID(new_id) switches it (probed: it takes the NEW id; all 9 "Lobby theme" hall props render).
# The /adm Seasons tab sends theme_mode (auto / off / <season>) and seasons {key: {window, enabled, lobby_theme}} in
# rlLobby; the active season's lobby_theme goes on, the default comes back when no season is on.  Only the default
# and the season themes are managed, so a lobby theme a player equipped of their own is left alone.
_DH_DEFAULT_LOBBY_THEME = 270000
_DH_SEASON_LOBBY = {          # built-in calendar, used until the console sends one
    'halloween': {'window': ('10-15', '11-02'), 'lobby_theme': 279009},   # Haunted Cabin
    'christmas': {'window': ('12-10', '01-05'), 'lobby_theme': 279007},   # Town Square
    'valentine': {'window': ('02-07', '02-20'), 'lobby_theme': 270004},   # Romantic Wedding
}
_dh_lobbytheme = globals().get('_dh_lobbytheme') or {'applied': None}


def _dh_server_monthday():
    try:
        stamp = None
        try:
            import client_utils
            stamp = client_utils.getServerSysTime()
        except Exception:
            stamp = None
        if not stamp:
            stamp = _dh_time.time()
        local = _dh_time.gmtime(float(stamp) + 8 * 3600)   # Philippine date (the server runs Asia/Manila)
        return (local.tm_mon, local.tm_mday)
    except Exception:
        return None


def _dh_in_window(month_day, window):
    try:
        # 'MM-DD' or the console's 'MM-DD HH:MM': the day is what counts
        start = tuple(int(x) for x in str(window[0]).split()[0].split('-'))
        end = tuple(int(x) for x in str(window[1]).split()[0].split('-'))
        now = (int(month_day[0]), int(month_day[1]))
        if start <= end:
            return start <= now <= end
        return now >= start or now <= end       # wraps the year end (e.g. 12-10 .. 01-06)
    except Exception:
        return False


def _dh_season_rows(config=None):
    seasons = (config if isinstance(config, dict) else _dh_lobby_config()).get('seasons')
    return seasons if isinstance(seasons, dict) and seasons else _DH_SEASON_LOBBY


def _dh_season_theme_of(key, config=None):
    row = _dh_season_rows(config).get(key)
    value = row.get('lobby_theme') if isinstance(row, dict) else None
    if value is None:
        value = (_DH_SEASON_LOBBY.get(key) or {}).get('lobby_theme', 0)
    try:
        return int(value or 0)
    except (TypeError, ValueError):
        return 0


def _dh_season_now(config=None):
    """(season key or None, lobby theme id or 0) for today."""
    config = config if isinstance(config, dict) else _dh_lobby_config()
    mode = str(config.get('theme_mode') or 'auto').lower()
    seasons = _dh_season_rows(config)
    if mode == 'off':
        return None, 0
    if mode != 'auto':
        return (mode, _dh_season_theme_of(mode, config)) if (mode in seasons or mode in _DH_SEASON_LOBBY) else (None, 0)
    month_day = _dh_server_monthday()
    if month_day is None:
        return None, 0
    for key in sorted(seasons):
        row = seasons.get(key) if isinstance(seasons.get(key), dict) else {}
        if row.get('enabled') is False:
            continue
        window = row.get('window') or (_DH_SEASON_LOBBY.get(key) or {}).get('window')
        if window and _dh_in_window(month_day, window):
            return key, _dh_season_theme_of(key, config)
    return None, 0


def _dh_lobbytheme_pass():
    try:
        if not _dh_in_lobby():
            return
        import BigWorld as _bw
        if getattr(_bw, '_dh_theme_suspended', False):
            return                               # m126: after a match keep the default hall (an equipped/season theme can't rebuild post-battle; the game crashes on the torn-down scene); it returns at the next login
        player = _bw.player()
        switch = getattr(player, 'onUpdateDtsHallThemeID', None) if player is not None else None
        if switch is None:
            return
        season, theme = _dh_season_now()
        target = int(theme or 0) or _DH_DEFAULT_LOBBY_THEME
        current = int(getattr(player, 'dtsHallThemeID', 0) or 0)
        if current == target:
            return
        managed = set([0, _DH_DEFAULT_LOBBY_THEME, 270000, 279008])
        for key in set(list(_DH_SEASON_LOBBY) + list(_dh_season_rows())):
            managed.add(_dh_season_theme_of(key))
        if current not in managed:
            return                               # a lobby theme the player chose: theirs
        try:
            player.dtsHallThemeID = target
        except Exception:
            pass
        switch(target)
        _dh_lobbytheme['applied'] = target
        log('local-lobby-theme', season=season, theme=target, was=current)
    except Exception:
        log_error('local-lobby-theme-error')


def _dh_lobbytheme_watch(gen=None):
    if gen is not None and gen != _dh_lobbytheme.get('gen'):
        return                                   # m108: a reloaded patch runs its own loop; this older one stops
    _dh_lobbytheme_pass()
    call_later(10.0, _dh_lobbytheme_watch, _dh_lobbytheme.get('gen'))


_dh_lobbytheme['gen'] = int(_dh_lobbytheme.get('gen') or 0) + 1
try:
    call_later(3.0, _dh_lobbytheme_watch, _dh_lobbytheme['gen'])
except Exception:
    log_error('local-lobby-theme-start-error')




