# --- m109: Friends -> Meet and the player cards answered by OUR server (2026-10-28).
# The Meet page's web calls (meethttp.*) and the avatar / rank-frame lookups (helpers.msf_client.batchGetPlayerData)
# go to msHttpAP = the runtime's local mirror on this PC, which answers {} and keeps nothing: a signature, tags, cover
# or like was lost, the people-to-meet list was always empty and an unknown sender's card blank (the mirror logged
# 62 blank get_player_info on 10-21/22).  They are now asked as RPCs (server_ext/meet_profile.py) and answered with
# one callback rlWebReply [seq, data] that is handed to the game's own callback in the shape the web reply had
# (meethttp: cb(json text of {"Ret": 0, "Data": ...}); msf_client: cb(0, {gid: props})).  No answer / not handled /
# in a battle: the original web call runs, exactly as before.  Photos, voice, portrait (dead NetEase file storage)
# and SetLBS (location) are left alone.
_dh_web = globals().get('_dh_web') or {'seq': 0, 'pending': {}}
_DH_MEET_SETTERS = (('httpMeetSetSignature', 'signature'), ('httpMeetSetLable', 'tags'), ('httpMeetSetMyCover', 'cover'))


def _dh_web_player():
    lobby = globals().get('_lobby')
    return lobby.get('player') if isinstance(lobby, dict) else None


def _dh_web_reply(player, seq, data=None, *rest):
    entry = _dh_web['pending'].pop(int(seq or 0), None)
    if entry is None:
        return None
    kind, cb = entry[0], entry[1]
    if not callable(cb):
        return None
    if kind == 'cards':
        cards = {}
        remember = globals().get('remember_player_card')
        for key, card in (data or {}).items():
            try:
                gid = int(key)
            except (TypeError, ValueError):
                continue
            cards[gid] = dict(card or {})
            if callable(remember):
                try:
                    remember(dict(card or {}, gid=gid))
                except Exception:
                    pass
        cb(0, cards)
    else:
        import json as _dh_json109
        cb(_dh_json109.dumps({'Ret': 0, 'Data': data if data is not None else {}}))
    return None


def _dh_web_ask(name, args, kind, cb, fallback):
    """Ask the server; fallback() (the original web call) when it does not answer this seq."""
    ask, asks, finish = globals().get('ask_backend'), globals().get('asks_backend'), globals().get('finish_rpc')
    if not (callable(ask) and callable(asks) and callable(finish)) or not asks(name):
        return fallback()
    _dh_web['seq'] += 1
    seq = _dh_web['seq']
    _dh_web['pending'][seq] = (kind, cb)

    def done(reply):
        if isinstance(reply, dict) and reply.get('handled') and reply.get('callbacks'):
            try:
                finish(_dh_web_player(), name, [seq] + list(args), {}, reply, 1)
            except Exception:
                log_error('local-web-rpc-finish-error', method=name)
        if _dh_web['pending'].pop(seq, None) is not None:
            log('local-web-rpc-fallback', method=name, answered=isinstance(reply, dict) and bool(reply.get('handled')))
            try:
                fallback()
            except Exception:
                log_error('local-web-rpc-fallback-error', method=name)
        return None
    return ask(name, [seq] + list(args), {}, done)


def _dh_wrap_meet_setter(module, fn_name, field):
    original = getattr(module, fn_name, None)
    if not callable(original) or getattr(original, '_dh_m109', False):
        return False

    def wrapper(gid, value, cb=None, *args, **kwargs):
        return _dh_web_ask('rlMeetSet', [field, value], 'meet', cb,
                           lambda: original(gid, value, cb, *args, **kwargs))
    wrapper._dh_m109 = True
    setattr(module, fn_name, wrapper)
    return True


def _dh_install_meet_web():
    meethttp = _dh_sys.modules.get('meethttp')
    if meethttp is None:
        return None
    done = [_dh_wrap_meet_setter(meethttp, name, field) for name, field in _DH_MEET_SETTERS]
    like = getattr(meethttp, 'httpMeetLike', None)
    if callable(like) and not getattr(like, '_dh_m109', False):
        def httpMeetLike(gid, opgid, isLike, cb=None, *args, **kwargs):
            return _dh_web_ask('rlMeetLike', [opgid, 1 if isLike else 0], 'meet', cb,
                               lambda: like(gid, opgid, isLike, cb, *args, **kwargs))
        httpMeetLike._dh_m109 = True
        meethttp.httpMeetLike = httpMeetLike
        done.append(True)
    people = getattr(meethttp, 'httpMeetUserInfoList', None)
    if callable(people) and not getattr(people, '_dh_m109', False):
        def httpMeetUserInfoList(gid, cb=None, *args, **kwargs):
            return _dh_web_ask('rlMeetList', [], 'meet', cb, lambda: people(gid, cb, *args, **kwargs))
        httpMeetUserInfoList._dh_m109 = True
        meethttp.httpMeetUserInfoList = httpMeetUserInfoList
        done.append(True)
    return sum(1 for d in done if d)


def _dh_install_player_cards_web():
    msf = _dh_sys.modules.get('helpers.msf_client')
    inner = getattr(msf, 'batchGetPlayerData', None) if msf is not None else None
    if not callable(inner):
        return None
    if getattr(inner, '_dh_m109', False):
        return True                 # a reload: the wrapper reads _dh_web_ask from these globals at call time
    known_cards = globals().get('_player_cards')

    def batchGetPlayerData(gids, props, cb, *args, **kwargs):
        try:
            cache = known_cards if isinstance(known_cards, dict) else {}
            unknown = [g for g in (gids or ()) if int(g) not in cache]
            if not unknown:
                return inner(gids, props, cb, *args, **kwargs)        # all cached: the runtime answers them
            known = [g for g in (gids or ()) if int(g) in cache]
            if known:
                inner(known, props, cb, *args, **kwargs)
            return _dh_web_ask('rlPlayerCards', [[int(g) for g in unknown], list(props or ())], 'cards', cb,
                               lambda: inner(unknown, props, cb, *args, **kwargs))
        except Exception:
            log_error('local-player-cards-web-error')
            return inner(gids, props, cb, *args, **kwargs)
    batchGetPlayerData._dh_m109 = True
    msf.batchGetPlayerData = batchGetPlayerData
    return True


def _dh_install_m109(tries=0):
    try:
        meet = _dh_install_meet_web()
        cards = _dh_install_player_cards_web()
    except Exception:
        log_error('local-web-rpc-install-error')
        return None
    if (meet is None or cards is None) and tries < 20:
        call_later(3.0, _dh_install_m109, tries + 1)      # the modules load with the lobby
        return None
    log('local-web-rpc-installed', meet=meet, cards=cards, tries=tries)
    return None


try:
    LOCAL_CALLBACKS['rlWebReply'] = _dh_web_reply
    _dh_install_m109()
except Exception:
    log_error('local-web-rpc-load-error')


log('local-art-installed', version='m109')


# --- m110 (2026-10-28): re-lands m104j (service access point) + the speed-check guard (m104l, redone), both dropped by the
# 10-27 incident rollback to m104m; neither had anything to do with that incident (the cause was the NetEase web
# services answered 200).  Retried for a minute in case extconfigs / iGMAdmin load after this patch.
# --- m104j: give Athlete.onBecomePlayer its service access point.  extconfigs.getServiceAccessPoint(ap) builds
# 'https://%s:%d' % (ap[0], ap[2]) or 'http://%s:%d' % (ap[0], ap[1]) from ap = (host, http_port, https_port)
# (probe m104i: those consts, indices 0/1/2, argcount 1).  Our server never sends that access point, so ap is None,
# extconfigs.py:50 raises "'NoneType' object has no attribute '__getitem__'" and the rest of onBecomePlayer is
# skipped (75x in the error log).  When ap is None, use the runtime's local update mirror (local_update/
# mirror_ports.json - the same 127.0.0.1 the lobby's other web-service calls already use, msHttpAP) and let the
# game's own function format it.  Also rebinds the name inside entities.Athlete in case it was imported with
# "from extconfigs import ...".  Guarded; idempotent across hot re-applies.
def _dh_mirror_access_point():
    host, http_port, https_port = '127.0.0.1', 80, 443
    try:
        import json as _json
        path = _dh_os.path.join(_dh_os.path.dirname(_dh_logs_dir()), 'mirror_ports.json')
        with open(path, 'rb') as handle:
            info = _json.loads(handle.read())
        host = str(info.get('host') or host)
        http_port = int(info.get('http') or http_port)
        https_port = int(info.get('https') or https_port)
    except Exception:
        pass
    return (host, http_port, https_port)


def _dh_install_service_ap():
    try:
        ec = _dh_sys.modules.get('extconfigs')
        if ec is None:
            return 'no-module'
        original = getattr(ec, 'getServiceAccessPoint', None)
        if original is None:
            return 'no-function'
        if getattr(original, '_dh_service_ap', False):
            return 'already'

        def getServiceAccessPoint(ap, _original=original):
            if ap is None:
                ap = _dh_mirror_access_point()
                if not globals().get('_dh_service_ap_logged'):
                    globals()['_dh_service_ap_logged'] = True
                    log('local-service-ap-defaulted', ap=list(ap))
            return _original(ap)
        getServiceAccessPoint._dh_service_ap = True
        getServiceAccessPoint._dh_inner = original
        ec.getServiceAccessPoint = getServiceAccessPoint
        rebound = []
        for mod_name in ('entities.Athlete', 'Athlete'):
            mod = _dh_sys.modules.get(mod_name)
            if mod is not None and getattr(mod, 'getServiceAccessPoint', None) is original:
                mod.getServiceAccessPoint = getServiceAccessPoint
                rebound.append(mod_name)
        return 'installed' + ((' +' + ','.join(rebound)) if rebound else '')
    except Exception:
        log_error('local-service-ap-install-error')
        return 'error'




# --- m104l: guard iGMAdmin._doCheckAndLogSpeedUp (a timer callback indexing a None at iGMAdmin.py:149, 71x in the
# error log: a client-side speed-hack LOG check whose table our server never sends; speed is judged server-side by
# cheat_guard).  m104k looked it up under a guessed module name and found nothing ('no-method'); this version finds
# the class that DEFINES the method by scanning the loaded modules once (the same walk the mmt survey does), so it
# works whatever the module is called.  Timer callback, not a SendMessage handler -> tolerant signature is safe.
def _dh_install_speedup_guard():
    """m110: _doCheckAndLogSpeedUp is a closure inside iGMAdmin.startRepeatLogSpeedUp (module 'iGMAdmin', line 145;
    found with a probe - m104k/m104l looked for a method and found none).  That repeat timer builds a NetEase SA-log
    speed report (our server acks and drops SA logs; speed is judged server-side by cheat_guard) and raised
    'NoneType ... __getitem__' at line 149.  So the timer is not started: startRepeatLogSpeedUp stops any running
    one and returns.  Called by saLogSpeedUpInfo, not a SendMessage handler, so *args is safe."""
    try:
        mod = _dh_sys.modules.get('iGMAdmin')
        klass = getattr(mod, 'iGMAdmin', None) if mod is not None else None
        original = getattr(klass, '__dict__', {}).get('startRepeatLogSpeedUp') if klass is not None else None
        if original is None:
            return 'no-method'
        if getattr(original, '_dh_speedup_guard', False):
            return 'already'

        def startRepeatLogSpeedUp(self, *args, **kwargs):
            try:
                if getattr(self, '_logSpeedUpTimer', None) is not None:
                    self.stopRepeatLogSpeedUp()
            except Exception:
                pass
            if not globals().get('_dh_speedup_logged'):
                globals()['_dh_speedup_logged'] = True
                log('local-speedup-log-off')
            return None
        startRepeatLogSpeedUp._dh_speedup_guard = True
        startRepeatLogSpeedUp._dh_inner = original
        klass.startRepeatLogSpeedUp = startRepeatLogSpeedUp
        return 'installed on iGMAdmin.startRepeatLogSpeedUp'
    except Exception:
        log_error('local-speedup-guard-error')
        return 'error'


def _dh_install_m110(tries=0):
    """Both wraps, retried every 10 s (cheap) until done: extconfigs / iGMAdmin may load after this patch.
    Stops after 6 hours."""
    ap = _dh_install_service_ap()
    speed = _dh_install_speedup_guard()
    if (ap in ('no-module', 'no-function') or speed == 'no-method') and tries < 2160:
        if tries == 0:
            log('local-m110-waiting', ap=ap, speed=speed)
        call_later(10.0, _dh_install_m110, tries + 1)
        return None
    log('local-service-ap-wrap', state=ap, tries=tries)
    log('local-speedup-guard', state=speed, tries=tries)
    return None


_dh_install_m110()
log('local-art-installed', version='m110')


