# --- m114 (2026-10-29): Gold -> diamonds in the game's Exchange dialog (UIYBExchange, the button next to Gold).  The
# game's own confirm only sends something for Horse Racing Coins (const 213, B-Coin: base.exchangeHorseRaceCoinToYB);
# for Gold it closed the dialog and did nothing (player report).  Now: the dialog shows the server's rate
# (rlExchange.gold.per gold = 1 diamond; currency_utils.getCurrencyExchangeRatioFromTo answered 0.1, the reverse of
# diamonds -> gold), and its OK sends base.rlExchangeGoldToYB(gold) (server_ext/currency_exchange.py: rate, daily cap,
# /adm Currencies -> Gold -> diamonds).
_DH_GOLD = 1
_dh_g2d = globals().get('_dh_g2d') or {}
for _dh_k, _dh_v in (('enabled', False), ('per', 100), ('daily', 0), ('ratio', False), ('screen', False), ('c2d', False)):
    _dh_g2d.setdefault(_dh_k, _dh_v)


def _dh_g2d_apply(body):
    gold = body.get('gold') if isinstance(body, dict) else None
    if isinstance(gold, dict):
        _dh_g2d.update(enabled=bool(gold.get('enabled')), per=max(1, int(gold.get('per') or 100)),
                       daily=int(gold.get('daily') or 0))


def _dh_g2d_unwrap(func, marker):
    while func is not None and getattr(func, marker, False):
        func = func._dh_inner
    return func


def _dh_g2d_ratio_factory(inner):
    """The dialog draws Gold -> diamonds from the DIAMOND -> Gold ratio (gold shown / ratio = diamonds; laptop:
    "Exchange Ratio: 10.0:1", 2000 gold -> 200).  While the dialog is in Gold -> diamonds mode (flag set by the screen
    wrappers below) that ratio is the server's gold per diamond; everywhere else the game's own."""
    def getCurrencyExchangeRatioFromTo(src, dst, *args, **kwargs):
        try:
            if _dh_g2d.get('enabled') and _dh_g2d.get('c2d'):
                pair = (int(src), int(dst))
                if pair == (_DH_DIAMOND, _DH_GOLD):
                    return float(_dh_g2d.get('per') or 100)
                if pair == (_DH_GOLD, _DH_DIAMOND):
                    return 1.0 / float(_dh_g2d.get('per') or 100)
        except Exception:
            pass
        return inner(src, dst, *args, **kwargs)
    getCurrencyExchangeRatioFromTo._dh_g2d = True
    getCurrencyExchangeRatioFromTo._dh_inner = inner
    return getCurrencyExchangeRatioFromTo


def _dh_g2d_gold_mode(screen):
    try:
        return (getattr(screen, 'exchageType', None) == getattr(type(screen), 'EXCHANGE_COIN_TO_DIAMOND_TYPE', None)
                and int(getattr(screen, 'currencyType', 0) or 0) == _DH_GOLD)
    except Exception:
        return False


def _dh_g2d_draw_factory(inner):
    def draw(self):                                # initUI / refreshUI(self): the rate shown follows the server
        _dh_g2d['c2d'] = _dh_g2d_gold_mode(self)
        try:
            return inner(self)
        finally:
            _dh_g2d['c2d'] = False
    draw.__dict__.update(getattr(inner, '__dict__', {}) or {})
    draw._dh_g2d = True
    draw._dh_inner = inner
    return draw


def _dh_g2d_confirm(screen):
    def confirm(*args, **kwargs):
        try:
            diamonds = int(float(getattr(screen, 'currentAmount', 0) or 0))   # the number pad counts diamonds
            gold = diamonds * int(_dh_g2d.get('per') or 100)
            import BigWorld
            BigWorld.player().base.rlExchangeGoldToYB(gold)
            log('local-g2d-sent', gold=gold, diamonds=diamonds)
        except Exception:
            log_error('local-g2d-send-error')
    confirm._dh_g2d = True
    return confirm


def _dh_g2d_take_dialog(screen):
    """The confirm dialog keeps its OK in _confirmCB (the game's confirmOK, which only knows Horse Racing Coins)."""
    try:
        import Globals
        dialog = getattr(Globals.uiMgr, 'UIDialog', None)
        if dialog is None or not hasattr(dialog, '_confirmCB'):
            import gc
            found = [o for o in gc.get_objects() if type(o).__name__ == 'UIDialog']
            dialog = found[-1] if found else None
        cb = getattr(dialog, '_confirmCB', None) if dialog is not None else None
        if cb is not None and not getattr(cb, '_dh_g2d', False) and getattr(cb, '__name__', '') == 'confirmOK':
            dialog._confirmCB = _dh_g2d_confirm(screen)
            dialog._confirmCBArgs = None
            return True
    except Exception:
        log_error('local-g2d-dialog-error')
    return False


def _dh_g2d_exchange_factory(inner):
    def onExchangeCoin(self, args):                # exact signature: SendMessage dispatches by argument count (R1)
        gold_in = _dh_g2d_gold_mode(self)
        try:
            ended = args.touch.phase == getattr(getattr(_dh_sys.modules.get('ui.UIYBExchange'), 'TouchPhase', None), 'Ended', None)
        except Exception:
            ended = False
        if ended:
            log('local-g2d-click', gold_mode=gold_in, amount=safe(getattr(self, 'currentAmount', None), 20),
                enabled=_dh_g2d.get('enabled'))
        if not gold_in:
            return inner(self, args)
        if not _dh_g2d.get('enabled'):
            if ended:
                try:
                    import Globals
                    Globals.uiMgr.systemJumpTip("Gold can't be exchanged into diamonds right now.")
                except Exception:
                    pass
            return None
        _dh_g2d['c2d'] = True                      # the dialog text uses the server's rate
        try:
            result = inner(self, args)
        finally:
            _dh_g2d['c2d'] = False
        if ended and _dh_g2d_take_dialog(self):
            log('local-g2d-dialog', diamonds=safe(getattr(self, 'currentAmount', None), 20), per=_dh_g2d.get('per'))
        return result
    # libclaudia only dispatches a click to a function marked ____isMessageHandler__ (the game's decorator sets it): a
    # wrapper without it made SendMessage drop the click - "message is not picked up by any component", the Exchange
    # button dead in BOTH directions (m114e, 2026-10-29).  Carry every attribute of the inner function over.
    onExchangeCoin.__dict__.update(getattr(inner, '__dict__', {}) or {})
    onExchangeCoin._dh_g2d = True
    onExchangeCoin._dh_inner = inner
    return onExchangeCoin


def _dh_g2d_refresh_handlers():
    """A screen's GameObject caches its click handlers by name (BehaviourContainer.messageHandlers) the first time a
    message is sent.  A screen already open, or clicked while an older wrapper lacked ____isMessageHandler__, cached
    onExchangeCoin -> [] or the unwrapped function: drop that entry so the next click looks the handler up again."""
    count = 0
    try:
        import gc
        for obj in gc.get_objects():
            if type(obj).__name__ != 'UIYBExchange':
                continue
            container = getattr(getattr(obj, 'gameObject', None), '____behaviourContainer__', None)
            cache = getattr(container, 'messageHandlers', None)
            if isinstance(cache, dict) and cache.pop('onExchangeCoin', None) is not None:
                count += 1
    except Exception:
        log_error('local-g2d-refresh-error')
    return count


def _dh_g2d_install(tries=0):
    try:
        if not _dh_g2d.get('ratio'):
            cu = _dh_sys.modules.get('currency_utils')
            if cu is not None and getattr(cu, 'getCurrencyExchangeRatioFromTo', None) is not None:
                inner = _dh_g2d_unwrap(cu.getCurrencyExchangeRatioFromTo, '_dh_g2d')
                cu.getCurrencyExchangeRatioFromTo = _dh_g2d_ratio_factory(inner)
                _dh_g2d['ratio'] = True
        if not _dh_g2d.get('screen'):
            mod = _dh_sys.modules.get('ui.UIYBExchange')
            cls = getattr(mod, 'UIYBExchange', None) if mod is not None else None
            if cls is not None and 'onExchangeCoin' in vars(cls):
                inner = _dh_g2d_unwrap(vars(cls)['onExchangeCoin'], '_dh_g2d')
                cls.onExchangeCoin = _dh_g2d_exchange_factory(inner)
                for name in ('initUI', 'refreshUI'):
                    if name in vars(cls):
                        setattr(cls, name, _dh_g2d_draw_factory(_dh_g2d_unwrap(vars(cls)[name], '_dh_g2d')))
                _dh_g2d['screen'] = True
        if _dh_g2d.get('ratio') and _dh_g2d.get('screen'):
            log('local-g2d-installed', per=_dh_g2d.get('per'), enabled=_dh_g2d.get('enabled'),
                refreshed=_dh_g2d_refresh_handlers())
            return
    except Exception:
        log_error('local-g2d-install-error')
        return
    if tries < 3600:                      # the screen's module loads the first time the dialog opens
        call_later(1.0, _dh_g2d_install, tries + 1)


_dh_g2d.update(ratio=False, screen=False)
call_later(1.0, _dh_g2d_install)
log('local-art-installed', version='m114f')


# --- m115 (2026-10-30): in-game TOP-UP paid with our payments, prices in pesos (server_ext/ingame_topup.py).
# The server sends rlIngameTopup {on, symbol, packs {goods id: {price, diamonds, bonus}}} (only to the accounts it is
# open for).  The TOP-UP cards (ui.UIPayment) show the server's price (client_utils.refreshPayGoodsPriceByGoodID) and
# diamonds / Extra (the PayGoods rows' AMOUNT / NORMAL_PRESENT); Buy (iPay.requsetPayGoods) asks the server for a
# checkout (rlIngameTopupStart) and opens it in the browser, then asks rlIngameTopupStatus until the order is paid
# and shows the new diamonds.  Every other pay button stays refused.
_DH_IT_POLL_SECONDS = 6.0
_DH_IT_POLL_FOR = 30 * 60.0
_dh_it = globals().get('_dh_it') or {'order': None, 'token': 0, 'tables': False, 'cfg': None}


def _dh_it_cfg(player=None):
    """The latest config: asked from the server when the TOP-UP screen opens, else the lobby-entry prop."""
    try:
        cfg = _dh_it.get('cfg')
        if not isinstance(cfg, dict):
            if player is None:
                player = BigWorld.player() if 'BigWorld' in globals() else __import__('BigWorld').player()
            cfg = getattr(player, 'rlIngameTopup', None)
        return cfg if isinstance(cfg, dict) and cfg.get('on') else None
    except Exception:
        return None


def _dh_it_refresh(then=None):
    def answered(reply):
        try:
            if reply and reply.get('ok') and isinstance(reply.get('cfg'), dict):
                _dh_it['cfg'] = reply['cfg']
                player = __import__('BigWorld').player()
                if reply['cfg'].get('on'):
                    try:
                        player.rlTopUpEnabled = True          # the hook's TOP-UP gate (topup_open)
                    except Exception:
                        pass
                    _dh_it_apply_table(reply['cfg'])
                log('local-it-config', on=bool(reply['cfg'].get('on')), packs=len(reply['cfg'].get('packs') or {}))
        except Exception:
            log_error('local-it-config-error')
        if callable(then):
            then()
    ask_backend('rlIngameTopupConfig', [], {}, answered)


def _dh_it_enter_factory(inner):
    def on_enter(self, args):                    # exact signature: SendMessage dispatches by argument count (R1)
        result = inner(self, args)
        try:
            def redraw():
                try:
                    if _dh_it_cfg() is not None and callable(getattr(self, '_initPayWidget', None)):
                        self._initPayWidget()
                except Exception:
                    log_error('local-it-redraw-error')
            _dh_it_refresh(redraw)
        except Exception:
            log_error('local-it-enter-error')
        return result
    on_enter.__dict__.update(getattr(inner, '__dict__', {}) or {})
    on_enter._dh_it = True
    on_enter._dh_inner = inner
    return on_enter


def _dh_it_pack(goods_id, player=None):
    cfg = _dh_it_cfg(player)
    if cfg is None:
        return None, None
    return cfg, (cfg.get('packs') or {}).get(str(goods_id))


def _dh_it_price_parts(cfg, pack):
    """(symbol, amount) - what client_utils.refreshPayGoodsPriceByGoodID returns (UIPayment.refreshPayGoodPrice
    unpacks the pair into its two labels; a single string crashed the screen)."""
    price = pack.get('price')
    try:
        text = '{:,}'.format(int(price)) if float(price) == int(price) else '{:,.2f}'.format(float(price))
    except Exception:
        text = str(price)
    symbol = cfg.get('symbol') or ''
    if isinstance(symbol, unicode):
        symbol = symbol.encode('utf-8')
    return symbol, text


def _dh_it_price_text(cfg, pack):
    return '%s %s' % _dh_it_price_parts(cfg, pack)


def _dh_it_price_factory(inner):
    def refreshPayGoodsPriceByGoodID(goodID, *args, **kwargs):
        try:
            cfg, pack = _dh_it_pack(goodID)
            if pack is not None:
                return _dh_it_price_parts(cfg, pack)
        except Exception:
            log_error('local-it-price-error')
        return inner(goodID, *args, **kwargs)
    refreshPayGoodsPriceByGoodID.__dict__.update(getattr(inner, '__dict__', {}) or {})
    refreshPayGoodsPriceByGoodID._dh_it = True
    refreshPayGoodsPriceByGoodID._dh_inner = inner
    return refreshPayGoodsPriceByGoodID


def _dh_it_apply_table(cfg):
    """The cards read AMOUNT / NORMAL_PRESENT from the game's PayGoods rows: the server's diamonds and Extra."""
    try:
        pu = _dh_sys.modules.get('pay_utils') or __import__('pay_utils')
        table = pu.tables.PayGoods
        changed = 0
        for goods_id, pack in (cfg.get('packs') or {}).items():
            row = table.get(goods_id)
            if row is None:
                continue
            for field, value in (('AMOUNT', pack.get('diamonds')), ('NORMAL_PRESENT', pack.get('bonus'))):
                try:
                    if value is not None and row.get(field) != int(value):
                        row[field] = int(value)
                        changed += 1
                except Exception:
                    pass
        return changed
    except Exception:
        log_error('local-it-table-error')
        return 0


def _dh_it_open(url):
    try:
        import game3d
        opener = getattr(game3d, 'open_url', None)
        if callable(opener):
            opener(str(url))
            return 'game3d'
    except Exception:
        log_error('local-it-open-error', how='game3d')
    try:
        import os
        os.startfile(str(url))
        return 'startfile'
    except Exception:
        log_error('local-it-open-error', how='startfile')
    return None


def _dh_it_tip(text):
    try:
        show_offline_tip(text, force=True)
    except Exception:
        log_error('local-it-tip-error')


def _dh_it_poll(order, token, started):
    if _dh_it.get('token') != token or _dh_it.get('order') != order:
        return
    if time.time() - started > _DH_IT_POLL_FOR:
        log('local-it-poll-timeout', order=order)
        return

    def answered(reply):
        try:
            status = (reply or {}).get('status')
            if status == 'credited':
                _dh_it['order'] = None
                player = __import__('BigWorld').player()
                applied = apply_server_props(player, reply.get('props'))
                refresh_currency_ui(player, applied)
                log('local-it-credited', order=order, diamonds=reply.get('diamonds'))
                _dh_it_tip('Payment received: +%s diamonds. Thank you!' % reply.get('diamonds'))
                return
            if status in ('failed', 'expired', 'unknown', 'refunded'):
                _dh_it['order'] = None
                log('local-it-poll-end', order=order, status=status)
                if status != 'unknown':
                    _dh_it_tip('The payment was not completed (%s).' % status)
                return
        except Exception:
            log_error('local-it-poll-error')
        call_later(_DH_IT_POLL_SECONDS, _dh_it_poll, order, token, started)
    ask_backend('rlIngameTopupStatus', [order], {}, answered)


def _dh_it_buy(player, goods_id, cfg, pack):
    def answered(reply):
        try:
            close_pay_loading()
            if not reply or not reply.get('ok'):
                _dh_it_tip((reply or {}).get('tip') or 'The payment page could not be opened - try again in a moment.')
                return
            how = _dh_it_open(reply.get('url'))
            log('local-it-checkout', goods=goods_id, order=reply.get('order'), opened=how)
            _dh_it['token'] = int(_dh_it.get('token') or 0) + 1
            _dh_it['order'] = reply.get('order')
            _dh_it_tip('Pay %s in the browser window - your %s diamonds arrive here automatically.'
                       % (_dh_it_price_text(cfg, pack), reply.get('diamonds')) if how else
                       'Open this link to pay: %s' % reply.get('url'))
            call_later(_DH_IT_POLL_SECONDS, _dh_it_poll, reply.get('order'), _dh_it['token'], time.time())
        except Exception:
            log_error('local-it-buy-reply-error')
    ask_backend('rlIngameTopupStart', [str(goods_id)], {}, answered)


def _dh_it_pay_factory(inner):
    def requsetPayGoods(self, goodsID, *args, **kwargs):
        cfg = _dh_it_cfg(self)
        if cfg is None:
            return inner(self, goodsID, *args, **kwargs)
        try:
            pack = (cfg.get('packs') or {}).get(str(goodsID))
            if pack is None:                       # month card, limit packs ...: not sold in the game (yet)
                refuse_pay('requsetPayGoods')
                return None
            log('local-it-buy', goods=str(goodsID), price=pack.get('price'))
            _dh_it_buy(self, goodsID, cfg, pack)
        except Exception:
            log_error('local-it-pay-error')
            refuse_pay('requsetPayGoods')
        return None
    requsetPayGoods._dh_it = True
    requsetPayGoods._dh_inner = inner
    return requsetPayGoods


def _dh_it_unwrap(fn):
    seen = 0
    while getattr(fn, '_dh_it', False) and getattr(fn, '_dh_inner', None) is not None and seen < 16:
        fn, seen = fn._dh_inner, seen + 1
    return fn


def _dh_it_install(tries=0):
    try:
        done = True
        cu = _dh_sys.modules.get('client_utils')
        if cu is not None and callable(getattr(cu, 'refreshPayGoodsPriceByGoodID', None)):
            if not getattr(cu.refreshPayGoodsPriceByGoodID, '_dh_it', False):
                cu.refreshPayGoodsPriceByGoodID = _dh_it_price_factory(_dh_it_unwrap(cu.refreshPayGoodsPriceByGoodID))
        else:
            done = False
        ip = _dh_sys.modules.get('iPay')
        cls = getattr(ip, 'iPay', None) if ip is not None else None
        if cls is not None and 'requsetPayGoods' in vars(cls):
            if not getattr(vars(cls)['requsetPayGoods'], '_dh_it', False):
                cls.requsetPayGoods = _dh_it_pay_factory(_dh_it_unwrap(vars(cls)['requsetPayGoods']))
        else:
            done = False
        um = _dh_sys.modules.get('ui.UIPayment')
        ucls = getattr(um, 'UIPayment', None) if um is not None else None
        if ucls is not None and 'on_enter' in vars(ucls) and not getattr(vars(ucls)['on_enter'], '_dh_it', False):
            ucls.on_enter = _dh_it_enter_factory(_dh_it_unwrap(vars(ucls)['on_enter']))
        elif ucls is None:
            done = False
        cfg = _dh_it_cfg()
        if done:
            _dh_it_refresh()
            log('local-it-installed', on=cfg is not None, packs=len((cfg or {}).get('packs') or {}))
            return
    except Exception:
        log_error('local-it-install-error')
        return
    if tries < 600:
        call_later(1.0, _dh_it_install, tries + 1)


_dh_it['tables'] = False
_dh_it['cfg'] = None
call_later(1.5, _dh_it_install)
