# ---- m116: the season's lobby theme after a match (owner 2026-10-30: "overlapping of 2 background").  Coming back
# from a battle the lobby scene is built again with the default environment (270000: day sky, mountains) while the
# avatar's dtsHallThemeID still says the season theme (Haunted Cabin 279009), so the m107 pass saw nothing to do and
# the theme's own parts were drawn over the default sky.  On the first lobby pass after a battle the theme is applied
# again through the game's own switch: default first, then the season theme, which rebuilds the environment once.
_dh_themefix = globals().get('_dh_themefix') or {'away': False, 'count': 0}
_dh_m116_pass = _dh_lobbytheme_pass


def _dh_lobbytheme_reapply(target):
    try:
        if not _dh_in_lobby():
            return
        import BigWorld as _bw
        player = _bw.player()
        player.dtsHallThemeID = target
        player.onUpdateDtsHallThemeID(target)
        _dh_themefix['count'] += 1
        log('local-lobby-theme-refreshed', theme=target, count=_dh_themefix['count'])
    except Exception:
        log_error('local-lobby-theme-refresh-error')


def _dh_lobbytheme_refresh():
    try:
        if not _dh_in_lobby():
            return
        import Globals
        ui_mgr = getattr(Globals, 'uiMgr', None)
        if ui_mgr is not None:
            for sname in ('UIDtsAppearanceVehicle', 'UIDtsAppearanceWeapon', 'UIDtsAppearanceCostume',
                          'UIDtsAppearanceOthers', 'UIDtsAppearancePet', 'UIDtsAppearanceRole',
                          'UIDtsAppearance', 'UIDtsAppearanceNewAdded', 'UIDtsAppearanceVehicleCultivate2',
                          'UIWorkshop'):
                scr = getattr(ui_mgr, sname, None)
                if scr is not None:
                    is_ent = getattr(scr, 'is_enter', False)
                    if callable(is_ent):
                        is_ent = is_ent()
                    if is_ent:
                        return
        import BigWorld as _bw
        player = _bw.player()
        switch = getattr(player, 'onUpdateDtsHallThemeID', None) if player is not None else None
        if switch is None:
            return
        _season, theme = _dh_season_now()
        target = int(theme or 0)
        current = int(getattr(player, 'dtsHallThemeID', 0) or 0)
        if not target or current == target:
            return
        player.dtsHallThemeID = target
        switch(target)
    except Exception:
        log_error('local-lobby-theme-refresh-error')


def _dh_lobby_scene_id():
    try:
        import Globals
        return id(getattr(Globals, 'loginScene', None))
    except Exception:
        return None


def _dh_lobbytheme_pass():
    try:
        scene = _dh_lobby_scene_id()
        if _dh_in_battle():
            _dh_themefix['away'] = True
        elif _dh_themefix.get('scene') not in (None, scene):
            _dh_themefix['away'] = True          # a new lobby scene (timers may sleep through the battle)
        if not _dh_in_battle():
            _dh_themefix['scene'] = scene
        if _dh_themefix.get('away') and _dh_in_lobby() and not _dh_in_battle():
            _dh_themefix['away'] = False
            call_later(2.0, _dh_lobbytheme_refresh)
    except Exception:
        log_error('local-lobby-theme-away-error')
    _dh_m116_pass()


