# (2) the text rules (m78/m124): 22 rules were run as separate substitutions over every one of ~50,000 game texts
# (~8 s on the laptop, the bar frozen at 72 %).  One combined search per text finds the ~650 that any rule can change;
# only those go through the rules.  A rule with a back-reference inside its own pattern cannot be combined - then every
# text goes through the rules as before.
_dh_m124_combo = {'key': None, 'rx': None}


def _dh_m124_combined(subs):
    key = id(subs)
    if _dh_m124_combo['key'] != key:
        rx = None
        try:
            import re as _re
            parts = [p.pattern for p, _r in subs]
            if parts and not any(_re.search(r'\\[1-9]|\(\?P=', part) for part in parts):
                rx = _re.compile(u'|'.join(u'(?:%s)' % part for part in parts))
        except Exception:
            rx = None
        _dh_m124_combo['key'], _dh_m124_combo['rx'] = key, rx
    return _dh_m124_combo['rx']


_dh_m124_rewrite_base = globals().get('_dh_rewrite')
while getattr(_dh_m124_rewrite_base, '_dh_m124', False):
    _dh_m124_rewrite_base = _dh_m124_rewrite_base._dh_inner


def _dh_m124_rewrite_factory(base):
    def _dh_rewrite(text, subs):
        rx = _dh_m124_combined(subs)
        if rx is not None:
            try:
                value = text.decode('utf-8') if isinstance(text, str) else text
                if not rx.search(value):
                    return text
            except Exception:
                return text
        return base(text, subs)
    return _dh_rewrite


if callable(_dh_m124_rewrite_base):
    _dh_rewrite = _dh_m124_rewrite_factory(_dh_m124_rewrite_base)
    _dh_rewrite._dh_m124 = True
    _dh_rewrite._dh_inner = _dh_m124_rewrite_base

_dh_m124_texts_base = globals().get('_dh_apply_texts')
while getattr(_dh_m124_texts_base, '_dh_m124', False):
    _dh_m124_texts_base = _dh_m124_texts_base._dh_inner


def _dh_m124_texts_factory(base):
    def _dh_apply_texts(body):
        started = time.time()
        result = base(body)
        if result is not None:
            log('local-texts-timing', ms=int(1000 * (time.time() - started)),
                combined=_dh_m124_combo['rx'] is not None)
        return result
    return _dh_apply_texts


if callable(_dh_m124_texts_base):
    _dh_apply_texts = _dh_m124_texts_factory(_dh_m124_texts_base)
    _dh_apply_texts._dh_m124 = True
    _dh_apply_texts._dh_inner = _dh_m124_texts_base


# ---- m125 (2026-11-01): Depot > RECENT "Go" for a lobby theme (owner: "not working if I click it" on Blight).
# The game's own jump table (ui.UIDtsAppearanceMainController.AppearanceTypeClsName2UIName, shared by the RECENT
# panel DtsNewAddedMiscPanel) has no 'HallTheme' row, so onSelectPropItem hid the Go button for every lobby theme; and
# jumpToSubPanelWithParam only knows the JumpUIName2JumpFunction tabs.  Add the row + a plain jump method that opens
# the LOBBY THEME tab through the game's own onHallThemeBtnEvent (a touch handler: it gets an object whose
# touch.phase is TouchPhase.Ended, exactly what a click delivers).  No UI handler is wrapped (message-handler rule).
# The depot modules load only when the depot first opens: sys.modules.get + retry, never a forced import.
_dh_m125 = globals().get('_dh_m125') or {'done': False, 'tries': 0}


def _dh_m125_hall_jump(self, params=None):
    import sys

    class _DhTouch(object):
        pass

    mod = sys.modules.get(type(self).__module__)
    touch = _DhTouch()
    touch.phase = getattr(getattr(mod, 'TouchPhase', None), 'Ended', None)
    args = _DhTouch()
    args.touch = touch
    log('local-hall-theme-jump', prop=safe((params or {}).get('selectedPropID') if isinstance(params, dict) else None, 40))
    return self.onHallThemeBtnEvent(args)


def _dh_m125_install():
    import sys
    try:
        mc = sys.modules.get('ui.UIDtsAppearanceMainController')
        cls = getattr(mc, 'UIDtsAppearanceMainController', None) if mc is not None else None
        jump = getattr(mc, 'JumpUIName2JumpFunction', None) if mc is not None else None
        if isinstance(cls, type) and hasattr(cls, 'onHallThemeBtnEvent') and isinstance(jump, dict):
            cls._dhOnHallThemeJump = _dh_m125_hall_jump
            jump['UIHallThemeMall'] = '_dhOnHallThemeJump'
            rows = 0
            for name in ('ui.UIDtsAppearanceMainController', 'ui.dtsAppearance.DtsNewAddedMiscPanel',
                         'ui.UIDtsAppearanceNewAdded'):
                table = getattr(sys.modules.get(name), 'AppearanceTypeClsName2UIName', None)
                if isinstance(table, dict) and table.get('HallTheme') != 'UIHallThemeMall':
                    table['HallTheme'] = 'UIHallThemeMall'
                    rows += 1
            _dh_m125['done'] = True
            log('local-hall-theme-go', installed=True, tables=rows, tries=_dh_m125['tries'])
            return
    except Exception:
        log_error('local-hall-theme-go-error')
        return
    _dh_m125['tries'] += 1
    call_later(3.0 if _dh_m125['tries'] < 400 else 20.0, _dh_m125_install)


if not _dh_m125['done']:
    _dh_m125['tries'] = 0
    call_later(2.0, _dh_m125_install)
