_dh_f5_cooldown = [0.0]

def _dh_window_title_loop():
    try:
        if '_dh_set_window_title_redemption' in globals():
            _dh_set_window_title_redemption()
    except Exception:
        pass
    try:
        import Globals
        ui_mgr = getattr(Globals, 'uiMgr', None)
        if ui_mgr is not None:
            all_ui = getattr(ui_mgr, '____all_ui__', None) or {}
            for _uin in ('UIMeetMainPage', 'UILadder', 'UIRankLadder'):
                _uio = all_ui.get(_uin)
                if _uio is not None:
                    try:
                        if hasattr(_uio, 'isVisible') and not _uio.isVisible():
                            continue
                    except Exception:
                        pass
                    _dh_relabel_seasons(_uio)
                    if _uin == 'UIMeetMainPage':
                        try:
                            _meet_rec = None
                            _mt = getattr(_uio, '_mainTab', None)
                            if _mt is not None and hasattr(_mt, 'getTabPanel'):
                                _meet_rec = _mt.getTabPanel('record')
                            if _meet_rec is None:
                                for _attr in ('battleGroundRecordPanel', 'recordPanel', '_battleGroundRecordPanel'):
                                    _meet_rec = getattr(_uio, _attr, None)
                                    if _meet_rec is not None:
                                        break
                            if _meet_rec is not None:
                                _dh_fix_record_panel(_meet_rec)
                        except Exception:
                            pass
            if 'UISubModesEnter' in all_ui:
                try:
                    _dh_patch_submodes_enter()
                except Exception:
                    pass
    except Exception:
        pass
    try:
        import ctypes, time
        now = time.time()
        # F5 Keyboard Hotkey for Instant Leaderboard / Ranking Board
        if (ctypes.windll.user32.GetAsyncKeyState(0x74) & 0x8000) and (now - _dh_f5_cooldown[0] > 0.5):
            _dh_f5_cooldown[0] = now
            try:
                import Globals
                Globals.uiMgr.enter_ui('UIRankList')
                print('>>> [ROS REDEMPTION] F5 Pressed: Opened UIRankList Leaderboard!')
            except Exception as e:
                print('>>> [ROS REDEMPTION] F5 Error: ' + repr(e))
    except Exception:
        pass
    call_later(0.2, _dh_window_title_loop)

call_later(0.05, _dh_window_title_loop)

# ==============================================================================
# ROS REDEMPTION - TEAM LEAVE FIX & 3D LOBBY SCENE SAFEGUARD
# 1. Unconditional Leave Team: player.onLeaveHallTeam & UI message unform
# 2. Instant Leave RPC Interceptor: handles leaveHallTeam immediately
# 3. 3D Lobby Road & Sky Restorer: restores classic day sky & mountains (Theme 270000)
# 4. Default Theme 270000 (Classic Day Sky) Auto-Apply for clean visuals
# ==============================================================================

# --- 1 & 2. TEAM LEAVE FIX ---
try:
    _dh_orig_rlParty = LOCAL_CALLBACKS.get('rlParty')
    def _dh_party_leave_clean(player):
        try:
            if player is not None and hasattr(player, 'onLeaveHallTeam'):
                try:
                    player.onLeaveHallTeam()
                except Exception:
                    pass
        except Exception:
            pass
        try:
            import Globals
            if hasattr(Globals, 'uiMgr') and Globals.uiMgr:
                for msg in ('onUnformTeam', 'onLeaveTeam', 'syncHallTeamMember', 'onUpdateHallTeamMode'):
                    try:
                        Globals.uiMgr.SendMessage(msg)
                    except Exception:
                        pass
                try:
                    _pnl = _ui_screen('UIMainBattleGroundInvite')
                    if _pnl is not None:
                        Globals.uiMgr.leave_ui('UIMainBattleGroundInvite')
                except Exception:
                    pass
        except Exception:
            pass
        try:
            if player is not None:
                player.matchingState = 0
                if hasattr(player, 'hallTeamReady'):
                    player.hallTeamReady = False
                if hasattr(player, 'isInFormedTeam'):
                    player.isInFormedTeam = False
                if hasattr(player, 'hallTeamLeader') and hasattr(player, 'gid'):
                    player.hallTeamLeader = player.gid
        except Exception:
            pass
        try:
            if player is not None and 'sync_local_team' in globals():
                sync_local_team(player)
        except Exception:
            pass

    _dh_orig_rlParty = LOCAL_CALLBACKS.get('rlParty')
    while getattr(_dh_orig_rlParty, '_dh_party_fixed_inner', None) is not None:
        _dh_orig_rlParty = _dh_orig_rlParty._dh_party_fixed_inner
    def _dh_rlParty_fixed(player, kind, *args):
        kind_str = str(kind)
        if kind_str == 'left':
            log('local-team-leave-handled', kind=kind_str)
            _dh_party_leave_clean(player)
            return None
        if callable(_dh_orig_rlParty):
            return _dh_orig_rlParty(player, kind, *args)
        return None
    _dh_rlParty_fixed._dh_party_fixed_inner = _dh_orig_rlParty
    LOCAL_CALLBACKS['rlParty'] = _dh_rlParty_fixed

    # Wrap handle_rpc for immediate leave response when player clicks Leave button
    _dh_orig_handle_rpc = globals().get('handle_rpc')
    while getattr(_dh_orig_handle_rpc, '_dh_team_leave_inner', None) is not None:
        _dh_orig_handle_rpc = _dh_orig_handle_rpc._dh_team_leave_inner
    def _dh_handle_rpc_team_leave(mailbox, name, args, kwargs):
        if name in ('leaveHallTeam', 'unformHallTeam', 'dismissHallTeam', 'leaveTeam'):
            try:
                import BigWorld
                p = getattr(mailbox, '_rl_owner', None) or BigWorld.player()
                _dh_party_leave_clean(p)
            except Exception:
                pass
        if callable(_dh_orig_handle_rpc):
            return _dh_orig_handle_rpc(mailbox, name, args, kwargs)
        return None
    _dh_handle_rpc_team_leave._dh_team_leave_inner = _dh_orig_handle_rpc
    handle_rpc = _dh_handle_rpc_team_leave
    globals()['handle_rpc'] = _dh_handle_rpc_team_leave
except Exception:
    log_error('local-team-leave-install-error')


# --- 3 & 4. 3D LOBBY SCENE & BACKDROP SAFEGUARD ---
try:
    _dh_orig_hall_theme_id = globals().get('hall_theme_id')
    def _dh_safe_hall_theme_id():
        own = _dh_theme_own()
        if own and own != 279008:
            return own
        tid = _dh_orig_hall_theme_id() if callable(_dh_orig_hall_theme_id) else 0
        if not tid or tid == 279008:
            return 270000
        return tid
    hall_theme_id = _dh_safe_hall_theme_id

    # Clean native backdrop passthroughs:
    # When inspecting Firearms, Vehicles, or Clothes in Depot: hides backdrops so dark smoke showroom renders cleanly.
    # When in UIMain (main lobby): ALWAYS ensure sky and backdrop planes are visible, preventing pitch black sky and clay floor!
    def _dh_show_lobby_backdrop_safe(show):
        try:
            import BigWorld
            player = BigWorld.player()
            hall = getattr(player, 'hallScene', None) if player else None
            scene = getattr(hall, '_native_scene', None) if hall else None
            if scene is None:
                return 0
            
            # Reset retirement tracking when showing lobby
            if show:
                _lobby['native_hall_models'] = []
                _lobby['retired_hall_models'] = []
                _lobby['backdrop_hidden'] = False
            else:
                _lobby['backdrop_hidden'] = True

            changed = 0
            for model, name in scene_models(scene):
                name_lower = str(name).lower()
                is_bg = is_backdrop_name(name) or any(k in name_lower for k in ('plane_bg', 'sky', 'mountain', 'road', 'city', 'building', 'terrain'))
                if not is_bg:
                    continue

                # The offline motor vehicle should always stay hidden in lobby
                if 'motor' in name_lower or 'plane_motor' in name_lower:
                    try:
                        if getattr(model, 'visible', False):
                            model.visible = False
                            changed += 1
                    except Exception:
                        pass
                    continue

                try:
                    vis = bool(show)
                    if bool(getattr(model, 'visible', False)) != vis:
                        model.visible = vis
                        changed += 1
                except Exception:
                    continue
            return changed
        except Exception:
            return 0
    show_lobby_backdrop = _dh_show_lobby_backdrop_safe
    globals()['show_lobby_backdrop'] = _dh_show_lobby_backdrop_safe

    # Neutralize ensure_self_model for existing players:
    # The male creation dummy (SHOW_MODEL_PATH) must only ever appear on UISelectCharacter for brand new accounts!
    _dh_orig_ensure_self_model = globals().get('ensure_self_model')
    while getattr(_dh_orig_ensure_self_model, '_dh_ensure_inner', None) is not None:
        _dh_orig_ensure_self_model = _dh_orig_ensure_self_model._dh_ensure_inner
    def _dh_safe_ensure_self_model(main_ui):
        try:
            saved = saved_character() if callable(globals().get('saved_character')) else None
            if saved is not None:
                return
            import BigWorld
            p = BigWorld.player()
            if p is not None and (getattr(p, 'nickname', None) or getattr(p, 'baseNickname', None)):
                return
        except Exception:
            pass
        if callable(_dh_orig_ensure_self_model):
            return _dh_orig_ensure_self_model(main_ui)
    _dh_safe_ensure_self_model._dh_ensure_inner = _dh_orig_ensure_self_model
    ensure_self_model = _dh_safe_ensure_self_model
    globals()['ensure_self_model'] = _dh_safe_ensure_self_model

    # Wrap HallTheme._clearOldTheme so a destroyed space object from battle never aborts theme creation
    try:
        import sys
        for mod_name in ('ui.main.HallTheme', 'HallTheme'):
            mod = sys.modules.get(mod_name)
            cls = getattr(mod, 'HallTheme', None) if mod is not None else None
            if cls is not None:
                orig_c = getattr(cls, '_clearOldTheme', None)
                if callable(orig_c) and not getattr(orig_c, '_dh_safe_clear', False):
                    def _dh_safe_clear_old(self, *a, **k):
                        try:
                            return orig_c(self, *a, **k)
                        except Exception:
                            return None
                    _dh_safe_clear_old._dh_safe_clear = True
                    cls._clearOldTheme = _dh_safe_clear_old
    except Exception:
        pass

    # Periodic Lobby 3D Scene loop: maintains equipped lobby theme on UIMain,
    # unhides sky and environment planes, and purges stray male creation dummy models
    _dh_theme_switching = [False]
    def _dh_lobby_scene_watchdog():
        try:
            if _dh_in_lobby():
                import Globals, BigWorld
                ui_mgr = getattr(Globals, 'uiMgr', None)
                _inspecting = False
                if ui_mgr is not None:
                    _inspect_screens = (
                        'UIDtsAppearanceVehicle', 'UIDtsAppearanceWeapon', 'UIDtsAppearanceCostume',
                        'UIDtsAppearanceOthers', 'UIDtsAppearancePet', 'UIDtsAppearanceRole',
                        'UIDtsAppearance', 'UIDtsAppearanceNewAdded', 'UIDtsAppearanceVehicleCultivate2',
                        'UIWorkshop', 'UIItemDisplay', 'UIMallController', 'UIMall', 'UIMallCloth',
                        'UISupplyController', 'UISupplyPackage', 'UIAdvanceSupplyPackage'
                    )
                    for sname in _inspect_screens:
                        scr = getattr(ui_mgr, sname, None)
                        if scr is not None:
                            is_ent = getattr(scr, 'is_enter', False)
                            if callable(is_ent):
                                is_ent = is_ent()
                            is_vis = getattr(scr, 'isVisible', None)
                            if callable(is_vis):
                                is_vis = is_vis()
                            else:
                                is_vis = getattr(scr, 'visible', False)
                            if is_ent or is_vis:
                                _inspecting = True
                                break

                player = BigWorld.player() if 'BigWorld' in globals() or BigWorld is not None else None
                hall = getattr(player, 'hallScene', None) if player else None
                scene = getattr(hall, '_native_scene', None) if hall else None
                main_ui = getattr(ui_mgr, 'UIMain', None) if ui_mgr else None

                # Purge stray male creation model from UIMain and scene
                if main_ui and player:
                    is_female = False
                    try:
                        c_type = player.getCharacterType() if hasattr(player, 'getCharacterType') else getattr(player, 'characterType', 0)
                        data = character_data(c_type) if callable(globals().get('character_data')) else None
                        if int(getattr(data, 'GENDER', 1) or 1) == 2 or 'female' in str(getattr(player, 'nickname', '')).lower():
                            is_female = True
                    except Exception:
                        pass
                    
                    m_dict = getattr(main_ui, 'models', None)
                    if isinstance(m_dict, dict):
                        for gk, entry in list(m_dict.items()):
                            m = entry.get('model') if isinstance(entry, dict) else entry
                            if m is not None and m is not getattr(hall, 'model', None):
                                m_fn = str(getattr(m, 'filename', '')).lower()
                                if 'dataosha_male' in m_fn or 'male.gim' in m_fn or 'male_show_new' in m_fn:
                                    if is_female or gk not in _team_gids(player):
                                        try:
                                            m.visible = False
                                        except Exception:
                                            pass
                                        try:
                                            destroy_model(m)
                                        except Exception:
                                            pass
                                        m_dict.pop(gk, None)

                # Only manage theme and scene backdrop when player is in the main lobby, NOT inspecting!
                if not _inspecting and scene is not None:
                    # Unhide sky and backdrop planes in UIMain
                    for model, name in scene_models(scene):
                        name_lower = str(name).lower()
                        if any(k in name_lower for k in ('plane_bg', 'sky', 'mountain', 'road', 'city', 'building', 'terrain')):
                            if 'motor' not in name_lower and not getattr(model, 'visible', False):
                                try:
                                    model.visible = True
                                except Exception:
                                    pass

                    if player is not None and not _dh_theme_switching[0]:
                        own = _dh_theme_own()
                        target_theme = own if (own and own != 279008) else 270000
                        cur_theme = int(getattr(player, 'dtsHallThemeID', 0) or 0)
                        if cur_theme != target_theme:
                            _dh_theme_switching[0] = True
                            BigWorld._dh_theme_suspended = False
                            player.dtsHallThemeID = target_theme
                            if hasattr(player, 'onUpdateDtsHallThemeID'):
                                try:
                                    player.onUpdateDtsHallThemeID(target_theme)
                                except Exception:
                                    pass
                            call_later(5.0, lambda: _dh_theme_switching.__setitem__(0, False))
        except Exception:
            pass
        call_later(2.0, _dh_lobby_scene_watchdog)

    call_later(1.0, _dh_lobby_scene_watchdog)
except Exception:
    log_error('local-lobby-scene-safeguard-error')



# ---------------------------------------------------------------------
# Post-Battle Lobby Party & Teammate 3D Model Restoration
# ---------------------------------------------------------------------
_dh_party_restore = globals().get('_dh_party_restore') or {
    'leaving': False,
    'pending_enter': None,
    'last_enter': None,
    'last_enter_at': 0.0,
}


def _dh_ui_main_models():
    """Return all 3D character models currently managed by UIMain (self + teammates)."""
    kept = []
    try:
        import Globals, BigWorld
        player = BigWorld.player()
        is_female = False
        try:
            c_type = player.getCharacterType() if hasattr(player, 'getCharacterType') else getattr(player, 'characterType', 0)
            data = character_data(c_type) if callable(globals().get('character_data')) else None
            if int(getattr(data, 'GENDER', 1) or 1) == 2 or 'female' in str(getattr(player, 'nickname', '')).lower():
                is_female = True
        except Exception:
            pass

        main_ui = getattr(getattr(Globals, 'uiMgr', None), 'UIMain', None)
        if main_ui is None:
            return kept
        models_dict = getattr(main_ui, 'models', None)
        if isinstance(models_dict, dict):
            for gid_k, entry in models_dict.items():
                m = entry.get('model') if isinstance(entry, dict) else entry
                if m is not None:
                    # Never keep stray male creation model for female player
                    if is_female:
                        m_fn = str(getattr(m, 'filename', '')).lower()
                        if 'dataosha_male' in m_fn or 'male.gim' in m_fn or 'male_show_new' in m_fn:
                            continue
                    kept.append(m)
    except Exception:
        pass
    return kept


def _dh_safe_clear_stray_characters(player=None):
    """Same as clear_stray_characters, but keeps all teammate 3D models in UIMain.models
    and purges stray male creation dummy models."""
    try:
        import BigWorld, Globals
        player = player or BigWorld.player()
        hall = getattr(player, 'hallScene', None)
        if not isinstance(hall, LocalHallScene):
            return 0

        is_female = False
        try:
            c_type = player.getCharacterType() if hasattr(player, 'getCharacterType') else getattr(player, 'characterType', 0)
            data = character_data(c_type) if callable(globals().get('character_data')) else None
            if int(getattr(data, 'GENDER', 1) or 1) == 2 or 'female' in str(getattr(player, 'nickname', '')).lower():
                is_female = True
        except Exception:
            pass

        # Purge stray male creation model from UIMain
        main_ui = getattr(getattr(Globals, 'uiMgr', None), 'UIMain', None)
        models_dict = getattr(main_ui, 'models', None) if main_ui else None
        if isinstance(models_dict, dict):
            for gk, entry in list(models_dict.items()):
                m = entry.get('model') if isinstance(entry, dict) else entry
                if m is not None and m is not hall.__dict__.get('model'):
                    m_fn = str(getattr(m, 'filename', '')).lower()
                    if 'dataosha_male' in m_fn or 'male.gim' in m_fn or 'male_show_new' in m_fn:
                        if is_female or gk not in _team_gids(player):
                            try:
                                m.visible = False
                            except Exception:
                                pass
                            try:
                                destroy_model(m)
                            except Exception:
                                pass
                            models_dict.pop(gk, None)

        keep = ([hall.__dict__.get('model')] +
                [entry[0] for entry in (hall.__dict__.get('_rl_model_cache') or {}).values()] +
                _dh_ui_main_models())
        stray = []
        for model, name in scene_models(hall._native_scene):
            name_lower = str(name).lower()
            if 'dataosha' not in name_lower:
                continue

            # Stray male model standing in center:
            if 'dataosha_male' in name_lower:
                if is_female and model is not hall.__dict__.get('model'):
                    if not any(model is kept for kept in _dh_ui_main_models() if kept is not None):
                        stray.append(model)
                        continue
                elif model is not hall.__dict__.get('model') and at_spot(model, (0.0, 0.0, 0.0), 3.0):
                    if not any(model is kept for kept in _dh_ui_main_models() if kept is not None):
                        stray.append(model)
                        continue

            if any(model is kept for kept in keep if kept is not None):
                continue
            if name_lower.endswith(CHARACTER_MODEL_ENDINGS) or at_spot(model, SELECT_SCREEN_SPOT):
                stray.append(model)

        kept = game_preloaded_models() if callable(globals().get('game_preloaded_models')) else []
        for model in stray:
            try:
                model.visible = False
            except Exception:
                pass
            if not any(model is other for other in kept):
                try:
                    destroy_model(model)
                except Exception:
                    pass
        if stray:
            log('local-lobby-stray-characters-cleared', count=len(stray))
        return len(stray)
    except Exception:
        log_error('local-lobby-safe-stray-clear-error')
        return 0


globals()['clear_stray_characters'] = _dh_safe_clear_stray_characters


def _dh_apply_party_enter_when_ready(tries=0):
    """Apply deferred rlParty('enter', ...) once UIMain and self model are ready in the lobby."""
    try:
        import BigWorld, Globals
        player = BigWorld.player()
        main_ui = getattr(getattr(Globals, 'uiMgr', None), 'UIMain', None)
        hall = getattr(player, 'hallScene', None) if player is not None else None
        if (player is None or main_ui is None or hall is None or not _lobby.get('entered')
                or not getattr(main_ui, 'models', None)):
            if tries < 40:
                call_later(0.35, _dh_apply_party_enter_when_ready, tries + 1)
            return
        args = _dh_party_restore.get('pending_enter') or _dh_party_restore.get('last_enter')
        if not args or len(args) < 4:
            return
        _dh_party_restore['pending_enter'] = None
        team_type, leader, size, cards = args[:4]
        card_list = [c for c in (cards or []) if isinstance(c, dict)]
        if len(card_list) <= 1:
            return
        models_dict = getattr(main_ui, 'models', None) or {}
        all_present = all(int(c.get('gid', 0) or 0) in models_dict for c in card_list if c.get('gid'))
        if all_present and len(_team_gids(player)) >= len(card_list):
            try:
                refresh = getattr(main_ui, 'onFormTeam', None)
                if callable(refresh):
                    refresh(False)
            except Exception:
                pass
            return
        # Ensure iHallTeam.onEnterHallTeam sees teammates as newly entering so UIMain spawns their 3D models
        try:
            own_gid = int(local_player.gid)
            td = getattr(player, 'hallTeamData', None)
            if isinstance(td, dict) and len(td) > 1 and not all_present:
                for k in list(td.keys()):
                    if int(k) != own_gid:
                        td.pop(k, None)
        except Exception:
            pass
        map_group = args[4] if len(args) > 4 else getattr(player, 'hallTeamMapGroup', 0)
        members = [_party_member(player, card) for card in card_list]
        enter_hall_team(player, team_type, leader, size, members, map_group,
                        args[5] if len(args) > 5 else False, args[6] if len(args) > 6 else 1)
        try:
            refresh = getattr(main_ui, 'onFormTeam', None)
            if callable(refresh):
                refresh(False)
            ref_mem = getattr(main_ui, '_refresh_members', None)
            if callable(ref_mem):
                ref_mem()
        except Exception:
            pass
        party_voice(player)
        log('local-lobby-party-restored-models', count=len(members), models=len(getattr(main_ui, 'models', None) or {}))
    except Exception:
        log_error('local-lobby-party-restore-error')


_dh_orig_local_party = (LOCAL_CALLBACKS.get('rlParty') if isinstance(globals().get('LOCAL_CALLBACKS'), dict) else None) \
    or globals().get('_local_party')
while getattr(_dh_orig_local_party, '_dh_party_wrap', None) is not None:
    _dh_orig_local_party = _dh_orig_local_party._dh_party_wrap

# The team-leave fix's cleanup (rlParty 'left' and the leaveHallTeam RPC) resets to a solo team: let it through
_dh_orig_leave_clean = globals().get('_dh_party_leave_clean')
while getattr(_dh_orig_leave_clean, '_dh_leave_inner', None) is not None:
    _dh_orig_leave_clean = _dh_orig_leave_clean._dh_leave_inner
if callable(_dh_orig_leave_clean):
    def _dh_party_leave_clean_flagged(player):
        _dh_party_restore['leaving'] = True
        _dh_party_restore['pending_enter'] = None
        _dh_party_restore['last_enter'] = None
        try:
            return _dh_orig_leave_clean(player)
        finally:
            _dh_party_restore['leaving'] = False
    _dh_party_leave_clean_flagged._dh_leave_inner = _dh_orig_leave_clean
    globals()['_dh_party_leave_clean'] = _dh_party_leave_clean_flagged


def _dh_wrapped_local_party(player, kind, *args):
    kind_s = str(kind)
    if kind_s == 'left':
        _dh_party_restore['leaving'] = True
        _dh_party_restore['pending_enter'] = None
        _dh_party_restore['last_enter'] = None
        try:
            return _dh_orig_local_party(player, kind, *args)
        finally:
            _dh_party_restore['leaving'] = False
    if kind_s == 'enter' and len(args) >= 4:
        cards = args[3]
        if isinstance(cards, (list, tuple)) and len(cards) > 1:
            import time as _t
            _dh_party_restore['last_enter'] = args
            _dh_party_restore['last_enter_at'] = _t.time()
            import Globals
            main_ui = getattr(getattr(Globals, 'uiMgr', None), 'UIMain', None)
            if main_ui is None or not _lobby.get('entered') or not getattr(main_ui, 'models', None):
                _dh_party_restore['pending_enter'] = args
                log('local-party-enter-deferred', count=len(cards))
                call_later(0.5, _dh_apply_party_enter_when_ready, 0)
                return
            # If UIMain is already open, ensure any missing 3D teammate model is spawned
            models_dict = getattr(main_ui, 'models', None) or {}
            all_present = all(int(c.get('gid', 0) or 0) in models_dict for c in cards if isinstance(c, dict) and c.get('gid'))
            if not all_present:
                try:
                    own_gid = int(local_player.gid)
                    td = getattr(player, 'hallTeamData', None)
                    if isinstance(td, dict) and len(td) > 1:
                        for k in list(td.keys()):
                            if int(k) != own_gid:
                                td.pop(k, None)
                except Exception:
                    pass
    elif kind_s == 'member' and args and isinstance(args[0], dict):
        try:
            gid = int(args[0].get('gid', 0) or 0)
            if gid and gid != int(local_player.gid) and gid not in _team_gids(player):
                team_call(player, 'addHallTeamMember', _party_member(player, args[0]))
                ask_party_state(player)
        except Exception:
            pass
    res = _dh_orig_local_party(player, kind, *args)
    if kind_s == 'enter' and len(args) >= 4 and isinstance(args[3], (list, tuple)) and len(args[3]) > 1:
        call_later(0.4, _dh_apply_party_enter_when_ready, 0)
    return res


_dh_wrapped_local_party._dh_party_wrap = _dh_orig_local_party
if 'LOCAL_CALLBACKS' in globals() and isinstance(LOCAL_CALLBACKS, dict):
    LOCAL_CALLBACKS['rlParty'] = _dh_wrapped_local_party


_dh_base_sync_local_team = globals().get('sync_local_team')
while getattr(_dh_base_sync_local_team, '_dh_party_guard_inner', None) is not None:
    _dh_base_sync_local_team = _dh_base_sync_local_team._dh_party_guard_inner


def _dh_guarded_sync_local_team(lobby_player, *args, **kwargs):
    """Do not overwrite an active multi-player party in hallTeamData with a 1-player solo team."""
    try:
        if not _dh_party_restore.get('leaving') and len(_team_gids(lobby_player)) > 1:
            own_gid = int(local_player.gid)
            td = getattr(lobby_player, 'hallTeamData', None)
            if isinstance(td, dict) and own_gid in td:
                try:
                    td[own_gid]['nationalFlag'] = own_flag() or 'UN'
                except Exception:
                    pass
            log('local-lobby-sync-team-preserved-party', members=len(_team_gids(lobby_player)))
            call_later(0.3, _dh_apply_party_enter_when_ready, 0)
            return
    except Exception:
        pass
    return _dh_base_sync_local_team(lobby_player, *args, **kwargs)


_dh_guarded_sync_local_team._dh_party_guard_inner = _dh_base_sync_local_team
globals()['sync_local_team'] = _dh_guarded_sync_local_team


_dh_orig_main_ready = globals().get('_dh_main_ready')
while getattr(_dh_orig_main_ready, '_dh_party_ready_inner', None) is not None:
    _dh_orig_main_ready = _dh_orig_main_ready._dh_party_ready_inner


def _dh_party_main_ready(*args, **kwargs):
    try:
        import BigWorld
        BigWorld._dh_theme_suspended = False
        p = BigWorld.player()
        own = _dh_theme_own()
        target_th = own if (own and own != 279008) else 270000
        if p is not None:
            cur_th = getattr(p, 'dtsHallThemeID', 0) or 0
            if not cur_th or cur_th == 279008:
                p.dtsHallThemeID = target_th
                if hasattr(p, 'onUpdateDtsHallThemeID'):
                    try:
                        p.onUpdateDtsHallThemeID(target_th)
                    except Exception:
                        pass

        # Unhide all sky and backdrop models when UIMain becomes ready
        hall = getattr(p, 'hallScene', None) if p else None
        scene = getattr(hall, '_native_scene', None) if hall else None
        if scene is not None:
            for model, name in scene_models(scene):
                name_lower = str(name).lower()
                if any(k in name_lower for k in ('plane_bg', 'sky', 'mountain', 'road', 'city', 'building', 'terrain')):
                    if 'motor' not in name_lower:
                        try:
                            model.visible = True
                        except Exception:
                            pass
        _lobby['retired_hall_models'] = []
        _lobby['native_hall_models'] = []
        _lobby['backdrop_hidden'] = False

        # Clear select character preloaded model so it cannot leak
        try:
            import ui.UISelectCharacter as select_module
            select_module._rl_preloaded_model = None
        except Exception:
            pass

        # Also purge any stray characters right now
        _dh_safe_clear_stray_characters(p)
    except Exception:
        pass
    res = _dh_orig_main_ready(*args, **kwargs) if callable(_dh_orig_main_ready) else None
    try:
        import BigWorld
        player = BigWorld.player()
        if player is not None:
            call_later(0.2, _dh_apply_party_enter_when_ready, 0)
            call_later(0.5, ask_party_state, player)
            call_later(2.0, ask_party_state, player)
    except Exception:
        pass
    return res


_dh_party_main_ready._dh_party_ready_inner = _dh_orig_main_ready
globals()['_dh_main_ready'] = _dh_party_main_ready



# Guard start_local_lobby against lingering ClientTeammate entities from battle quit
_dh_orig_start_local_lobby = globals().get('start_local_lobby')
while getattr(_dh_orig_start_local_lobby, '_dh_guard_inner', None) is not None:
    _dh_orig_start_local_lobby = _dh_orig_start_local_lobby._dh_guard_inner


def _dh_guarded_start_local_lobby(*args, **kwargs):
    retry_count = kwargs.pop('_dh_retry', 0)
    try:
        import BigWorld
        p = BigWorld.player()
        if p is None or not hasattr(p, 'onBecomePlayer'):
            if retry_count < 60:
                kwargs['_dh_retry'] = retry_count + 1
                call_later(0.2, _dh_guarded_start_local_lobby, *args, **kwargs)
                return None
        p_cname = getattr(getattr(p, '__class__', None), '__name__', '')
        if p_cname == 'ClientTeammate' or 'ClientTeammate' in str(type(p)):
            for ent in list(BigWorld.entities.values()):
                if ent is not None and getattr(getattr(ent, '__class__', None), '__name__', '') == 'ClientTeammate':
                    try:
                        BigWorld.destroyEntity(ent.id)
                    except Exception:
                        pass
    except Exception:
        pass
    try:
        # Reset backdrop retirement on return to lobby
        _lobby['retired_hall_models'] = []
        _lobby['native_hall_models'] = []
        _lobby['backdrop_hidden'] = False
        import ui.UISelectCharacter as select_module
        select_module._rl_preloaded_model = None
    except Exception:
        pass
    if callable(_dh_orig_start_local_lobby):
        res = _dh_orig_start_local_lobby(*args, **kwargs)
        try:
            call_later(0.5, _dh_kick_stuck_lobby)
        except Exception:
            pass
        return res
    return None


if callable(_dh_orig_start_local_lobby):
    _dh_guarded_start_local_lobby._dh_guard_inner = _dh_orig_start_local_lobby
    globals()['start_local_lobby'] = _dh_guarded_start_local_lobby



